INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23910, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23910, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一群人一起生活或做事情。", "primary_collocate": null, "pronunciation": "shè qún", "ipa": "ʂɤ˥˩ tɕʰyn˧˥", "syllable_count": 2, "sentences": [{"text": "我们这个社群有五百多个人。", "target_word": "社群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上加入了一个读书社群。", "target_word": "社群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社群的成员常常互相帮助。", "target_word": "社群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社群里的人都喜欢养猫。", "target_word": "社群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王是我们社群的负责人。", "target_word": "社群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老年人也需要自己的社群。", "target_word": "社群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在社群里认识了很多朋友。", "target_word": "社群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个社群都有自己的规矩。", "target_word": "社群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社群每周六都有活动。", "target_word": "社群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社群里的气氛很好，大家都很友好。", "target_word": "社群", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "因共同生活或共同兴趣而聚在一起的一群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c34999df-c2a8-41e6-84de-552383229488') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社群", "is_correct": true, "explanation": "社群指因共同兴趣或生活聚在一起的一群人，可以说“有五百多个人”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的功课，不是由人组成的群体，不能说“有五百多个人”。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不指人群，句中“有五百多个人”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "配价：“有”后面接人数宾语时，主语要是人群或团体，“天气”不能带这样的宾语。"}], "explanations": {"社群": "社群指因共同兴趣或生活聚在一起的一群人，可以说“有五百多个人”。", "作业": "语义：作业是学生的功课，不是由人组成的群体，不能说“有五百多个人”。", "钢琴": "语义：钢琴是乐器，不指人群，句中“有五百多个人”说不通。", "天气": "配价：“有”后面接人数宾语时，主语要是人群或团体，“天气”不能带这样的宾语。"}, "sentence_index": 0, "correct_answer": "社群"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个社群的地铁站很近，出门就能坐车。", "explanation": "这里应该用〈社区〉。社区指居住的地区，可以说“地铁站很近”；社群指一群人，不能指有地铁站的地方。"}, {"text": "车站里的社群很拥挤。", "explanation": "这里应该用〈人群〉。人群指聚在一处的许多人，车站里的人群是临时聚集；社群指长期因共同兴趣或生活而联系的一群人，不能用来形容临时聚集。"}, {"text": "这个社群里有很多公园。", "explanation": "这里应该用〈社区〉。社区指人们居住的地区，里面可以有很多公园；社群指一群人，不是地方，不能包含公园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社群", "is_correct": true, "explanation": "社群指聚在一起的一群人，她可以在其中认识朋友。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是人们聚集交往的场所，句中“认识朋友”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的物体，不能作为人际交往的场所。"}, {"text": "抽屉", "is_correct": false, "explanation": "搭配：“在……里认识朋友”的处所要能让人聚集交往，“抽屉”搭配不上。"}], "explanations": {"社群": "社群指聚在一起的一群人，她可以在其中认识朋友。", "天空": "语义：天空不是人们聚集交往的场所，句中“认识朋友”说不通。", "石头": "语义：石头是无生命的物体，不能作为人际交往的场所。", "抽屉": "搭配：“在……里认识朋友”的处所要能让人聚集交往，“抽屉”搭配不上。"}, "sentence_index": 6, "correct_answer": "社群"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个社群有三栋楼。", "explanation": "这里应该用〈小区〉。小区指有楼房的居住区，可以说“有三栋楼”；社群指一群人，不能拥有楼房。"}, {"text": "诊室门口的社群排成了长队。", "explanation": "这里应该用〈病人〉。病人指在诊室等候看病的人，是临时聚集；社群指因共同兴趣或生活而长期联系的一群人，不能用来指排队看病的人。"}, {"text": "公交车上的社群很多。", "explanation": "这里应该用〈乘客〉。乘客指乘车的人，只是临时同行；社群强调长期的共同兴趣或生活联系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她前年加入着一个登山社群。", "corrected_sentence": "她前年加入了一个登山社群。", "error_description": "助词用错：“加入”表示一次性的动作，不能用“着”表示持续，应用“了”，说“加入了一个登山社群”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前加入过这位摄影社群。", "corrected_sentence": "他以前加入过这个摄影社群。", "error_description": "量词错误：“社群”指一群人组成的群体，不能用指人的量词“位”，应说“这个摄影社群”，不能说“这位摄影社群”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '859e38d4-855c-4cf1-a0b0-1290ea3a0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
