INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23912, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "提前定好以后要怎么做。", "primary_collocate": null, "pronunciation": "yù shè", "ipa": "y˥˩ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "开会以前，经理预设了几种做法。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们预设了下雨时的活动安排。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，教练预设了每个人的位置。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他预设好了回答，等着记者提问。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做计划时，要先预设应对困难的办法。", "target_word": "预设", "complexity_tier": "T3", "furigana": "yù shè", "sentence_source": "generated"}, {"text": "妈妈预设了孩子上学的路线。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们预设过三种办法，应对意外。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司预设了新产品的卖法。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板预设了几个办法来处理投诉。", "target_word": "预设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有预设方案，只想先试试。", "target_word": "预设", "complexity_tier": "T3", "furigana": "yù shè", "sentence_source": "generated"}], "morphological_forms": [{"form": "预设了", "label": "体标"}, {"form": "预设过", "label": "体标"}, {"form": "预设好", "label": "复合"}, {"form": "預設", "label": "繁体"}], "register": "书面", "sense_fingerprint": "提前为将来的情况定好做法或步骤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f917e74-ef1d-49a8-a590-87211bbc2e31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23912, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预设", "is_correct": true, "explanation": "正确。预设 yù shè，指提前定好以后要怎么做。"}, {"text": "预热", "is_correct": false, "explanation": "rè（第四声）与 shè（第四声）声母不同（r 与 sh），意思是预先加热。"}, {"text": "预试", "is_correct": false, "explanation": "shì（第四声）与 shè（第四声）韵母不同（i 与 ê），意思是预先测试。"}, {"text": "预测", "is_correct": false, "explanation": "cè（第四声）与 shè（第四声）声母不同（c 与 sh），意思是预先推断。"}], "explanations": {"预设": "正确。预设 yù shè，指提前定好以后要怎么做。", "预热": "rè（第四声）与 shè（第四声）声母不同（r 与 sh），意思是预先加热。", "预试": "shì（第四声）与 shè（第四声）韵母不同（i 与 ê），意思是预先测试。", "预测": "cè（第四声）与 shè（第四声）声母不同（c 与 sh），意思是预先推断。"}, "sentence_index": null, "correct_answer": "预设"}, "level_3": {"options": [{"text": "预设", "is_correct": true, "explanation": "正确。此处指经理提前定好的几种做法。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“做法”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“做法”搭配，句子不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”与“开会以前”的计划语境不合，句意荒谬。"}], "explanations": {"预设": "正确。此处指经理提前定好的几种做法。", "唱": "搭配：“唱”不能与“做法”搭配。", "吃": "搭配：“吃”不能与“做法”搭配，句子不通。", "睡": "语义：“睡”与“开会以前”的计划语境不合，句意荒谬。"}, "sentence_index": 0, "correct_answer": "预设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我提前预设了两张票。", "explanation": "这里应该用〈预订〉。预设指事先定好做法或安排，买票要用预订。"}, {"text": "学生每天晚上都预设第二天的课文。", "explanation": "这里应该用〈预习〉。预设指提前定好要怎么做，不指学生提前学习，预习才用于此。"}, {"text": "医生提前预设了感冒。", "explanation": "这里应该用〈预防〉。预设指提前定好要怎么做，不能用于提前避免疾病，预防才用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '527a28a0-59a1-4cd4-9f8a-164ddafb1fbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23912, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "预设", "is_correct": true, "explanation": "正确。预设 yù shè，指提前定好以后要怎么做。"}, {"text": "遇事", "is_correct": false, "explanation": "shì 与 shè 韵母不同（i 与 ê），意思是遇到事情。"}, {"text": "预测", "is_correct": false, "explanation": "cè（第四声）与 shè（第四声）声母不同（c 与 sh），意思是预先推断。"}, {"text": "预示", "is_correct": false, "explanation": "shì（第四声）与 shè（第四声）韵母不同（i 与 ê），意思是预先显示迹象。"}], "explanations": {"预设": "正确。预设 yù shè，指提前定好以后要怎么做。", "遇事": "shì 与 shè 韵母不同（i 与 ê），意思是遇到事情。", "预测": "cè（第四声）与 shè（第四声）声母不同（c 与 sh），意思是预先推断。", "预示": "shì（第四声）与 shè（第四声）韵母不同（i 与 ê），意思是预先显示迹象。"}, "sentence_index": null, "correct_answer": "预设"}, "level_3": {"options": [{"text": "预设", "is_correct": true, "explanation": "正确。此处指提前定好的办法。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记办法无法用于应对意外，句意矛盾。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”多用于规则或纪录，不说“打破办法”。"}, {"text": "删除", "is_correct": false, "explanation": "语义：删除办法与“应对意外”的目的相反，句意不通。"}], "explanations": {"预设": "正确。此处指提前定好的办法。", "忘记": "语义：忘记办法无法用于应对意外，句意矛盾。", "打破": "搭配：“打破”多用于规则或纪录，不说“打破办法”。", "删除": "语义：删除办法与“应对意外”的目的相反，句意不通。"}, "sentence_index": 6, "correct_answer": "预设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天预设了牙医。", "explanation": "这里应该用〈预约〉。预设不能以人为对象，约人见面要用预约。"}, {"text": "这套丛书下个月开始预设。", "explanation": "这里应该用〈预售〉。预设用于设定做法或参数，不用于图书的提前销售。"}, {"text": "气象台预设了明天的降雨概率。", "explanation": "这里应该用〈预报〉。预设指提前定好要怎么做，不指预报天气，预报才用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '527a28a0-59a1-4cd4-9f8a-164ddafb1fbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没预设了回答，只想现场发挥。", "corrected_sentence": "他没预设回答，只想现场发挥。", "error_description": "错误在于“预设”后多加了“了”。“没”表示否定，与“了”不能同时用在同一动作上，应说“他没预设回答”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '527a28a0-59a1-4cd4-9f8a-164ddafb1fbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把比赛时间预设下午。", "corrected_sentence": "我们把比赛时间预设在下午。", "error_description": "错误在于缺少补语“在”。“预设”后接表示时间或处所的词语时要用“在”，直接接时间名词不符合习惯，应说“预设在下午”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '527a28a0-59a1-4cd4-9f8a-164ddafb1fbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
