INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23914, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "氏族就是有同一个祖先的一大家人。", "primary_collocate": null, "pronunciation": "shì zú", "ipa": "ʂʐ̩˥˩ tsu˧˥", "syllable_count": 2, "sentences": [{"text": "氏族就是一大家人，他们有同一个祖先。", "target_word": "氏族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个氏族有三百多口人。", "target_word": "氏族", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老人给孩子们讲氏族的故事。", "target_word": "氏族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "氏族里的人都叫他爷爷。", "target_word": "氏族", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们是同一个氏族的人，所以姓一样。", "target_word": "氏族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每年春天，整个氏族一起祭祖。", "target_word": "氏族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候，我常听奶奶说我们氏族的历史。", "target_word": "氏族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个氏族的人住在山里，种着玉米。", "target_word": "氏族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个氏族里，大家互相帮忙。", "target_word": "氏族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个氏族的祖先是一位有名的猎人。", "target_word": "氏族", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "氏族社会", "label": "复合"}, {"form": "氏族公社", "label": "复合"}], "register": "中性", "sense_fingerprint": "氏族：同一个祖先的一大家人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2900ff34-7b63-430a-b418-659efc01403e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23914, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "氏族", "is_correct": true, "explanation": "正确答案：氏族（shì zú），指同一祖先的一大家人。"}, {"text": "十足", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，十足意思是十分充足。"}, {"text": "失足", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，失足意思是不慎跌倒或误入歧途。"}, {"text": "始祖", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，zǔ（第三声）与 zú（第二声）声调也不同，始祖意思是最早的祖先。"}], "explanations": {"氏族": "正确答案：氏族（shì zú），指同一祖先的一大家人。", "十足": "shí（第二声）与 shì（第四声）声调不同，十足意思是十分充足。", "失足": "shī（第一声）与 shì（第四声）声调不同，失足意思是不慎跌倒或误入歧途。", "始祖": "shǐ（第三声）与 shì（第四声）声调不同，zǔ（第三声）与 zú（第二声）声调也不同，始祖意思是最早的祖先。"}, "sentence_index": null, "correct_answer": "氏族"}, "level_3": {"options": [{"text": "氏族", "is_correct": true, "explanation": "正确：“就是一大家人，他们有同一个祖先”说的正是同一祖先的一大家人，即氏族。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言没有祖先，不能说“就是一大家人，他们有同一个祖先”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是人群，不能有“同一个祖先”。"}, {"text": "宗谱", "is_correct": false, "explanation": "搭配：“宗谱”是记录世系的书，不与“就是一大家人”搭配。"}], "explanations": {"氏族": "正确：“就是一大家人，他们有同一个祖先”说的正是同一祖先的一大家人，即氏族。", "语言": "语义：语言没有祖先，不能说“就是一大家人，他们有同一个祖先”。", "河流": "语义：河流不是人群，不能有“同一个祖先”。", "宗谱": "搭配：“宗谱”是记录世系的书，不与“就是一大家人”搭配。"}, "sentence_index": 0, "correct_answer": "氏族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "氏族里的同学都叫他班长。", "explanation": "这里应该用〈班级〉。氏族指同一祖先的一大家人，同班的同学要说班级。"}, {"text": "我们氏族的工人每天生产三千个零件。", "explanation": "这里应该用〈工厂〉。氏族指同一祖先的一大家人，生产零件的地方要说工厂。"}, {"text": "我们氏族的人口有十四亿。", "explanation": "这里应该用〈国家〉。十四亿人口的国家不是同一祖先的一大家人，应说国家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23914, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "氏族", "is_correct": true, "explanation": "正确答案：氏族（shì zú），指同一祖先的一大家人。"}, {"text": "赤足", "is_correct": false, "explanation": "chì（第四声）与 shì（第四声）声母不同（ch 与 sh），赤足意思是光着脚。"}, {"text": "四足", "is_correct": false, "explanation": "sì（第四声）与 shì（第四声）声母不同（s 与 sh），四足意思是有四条腿。"}, {"text": "实足", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，实足意思是实际的、足额的，如“实足年龄”。"}], "explanations": {"氏族": "正确答案：氏族（shì zú），指同一祖先的一大家人。", "赤足": "chì（第四声）与 shì（第四声）声母不同（ch 与 sh），赤足意思是光着脚。", "四足": "sì（第四声）与 shì（第四声）声母不同（s 与 sh），四足意思是有四条腿。", "实足": "shí（第二声）与 shì（第四声）声调不同，实足意思是实际的、足额的，如“实足年龄”。"}, "sentence_index": null, "correct_answer": "氏族"}, "level_3": {"options": [{"text": "氏族", "is_correct": true, "explanation": "正确：“我们氏族的历史”指同一祖先的大家人讲述的家族历史，与“奶奶说”相合。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”不是家族，奶奶讲的不会是它的历史。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“水果”不是人群，不能说“我们水果的历史”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“我们……的历史”要求人或群体，“天气”不这样搭配。"}], "explanations": {"氏族": "正确：“我们氏族的历史”指同一祖先的大家人讲述的家族历史，与“奶奶说”相合。", "手机": "语义：“手机”不是家族，奶奶讲的不会是它的历史。", "水果": "语义：“水果”不是人群，不能说“我们水果的历史”。", "天气": "搭配：“我们……的历史”要求人或群体，“天气”不这样搭配。"}, "sentence_index": 6, "correct_answer": "氏族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们氏族的老师都很认真。", "explanation": "这里应该用〈学校〉。氏族指同一祖先的一大家人，学校里的老师要说学校。"}, {"text": "这个氏族的员工都很忙。", "explanation": "这里应该用〈公司〉。员工是公司里的人，不是同一祖先的一大家人，应说公司。"}, {"text": "我们氏族有十五个队员。", "explanation": "这里应该用〈球队〉。队员是为比赛组成的团体，不是血缘群体，应说球队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子里有两只氏族。", "corrected_sentence": "这个村子里有两个氏族。", "error_description": "量词错误：“只”用于动物，氏族是群体，应说“两个氏族”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两只不同氏族之间常常通婚。", "corrected_sentence": "两个不同氏族之间常常通婚。", "error_description": "量词错误：“只”用于动物，氏族是群体，应说“两个不同氏族”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
