INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23926, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "加速器是一种机器，能让东西跑得更快。", "primary_collocate": null, "pronunciation": "jiā sù qì", "ipa": "tɕja˥ su˥˩ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "这台加速器能让小东西跑得很快。", "target_word": "加速器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们在博物馆里看到了加速器。", "target_word": "加速器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加速器是一种很大的机器。", "target_word": "加速器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们看了加速器的照片。", "target_word": "加速器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加速器的声音很大。", "target_word": "加速器", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他长大后想亲手操作一台加速器。", "target_word": "加速器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个加速器是用电的。", "target_word": "加速器", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人们正在修理那台加速器。", "target_word": "加速器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我第一次见到这么大的加速器。", "target_word": "加速器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加速器让粒子越跑越快。", "target_word": "加速器", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "粒子加速器", "label": "复合"}, {"form": "回旋加速器", "label": "复合"}], "register": "中性", "sense_fingerprint": "加速器：能让东西跑得更快的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2900ff34-7b63-430a-b418-659efc01403e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23926, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加速器", "is_correct": true, "explanation": "加速器：指一台能让东西跑得更快的机器，与“这台”和“跑得很快”相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱用来制冷保鲜，不能让东西跑得更快。"}, {"text": "收音机", "is_correct": false, "explanation": "语义：收音机用来收听广播，与让东西加速没有关系。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视用来播放影像，不能让东西跑得更快，与“能让小东西跑得很快”不合。"}], "explanations": {"加速器": "加速器：指一台能让东西跑得更快的机器，与“这台”和“跑得很快”相合。", "冰箱": "语义：冰箱用来制冷保鲜，不能让东西跑得更快。", "收音机": "语义：收音机用来收听广播，与让东西加速没有关系。", "电视": "语义：电视用来播放影像，不能让东西跑得更快，与“能让小东西跑得很快”不合。"}, "sentence_index": 0, "correct_answer": "加速器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "房间里的加速器一直在工作，空气变干净了。", "explanation": "这里应该用〈净化器〉。净化器用来净化空气，加速器用于加快物体速度，不能让空气变干净。"}, {"text": "房间太干，我打开了加速器。", "explanation": "这里应该用〈加湿器〉。加湿器用来增加空气湿度，加速器与湿度无关。"}, {"text": "这辆车装了加速器，最高时速被限制在一百公里。", "explanation": "这里应该用〈限速器〉。限速器用来限制最高速度，加速器的作用是提高速度，两者正好相反，装了加速器不会限制时速。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加速器", "is_correct": true, "explanation": "加速器：这里指用电驱动的设备，与“是用电的”相合。"}, {"text": "煤", "is_correct": false, "explanation": "语义：煤是燃料，不是用电驱动的设备，“是用电的”说它不通。"}, {"text": "面条", "is_correct": false, "explanation": "语义：面条是食物，不存在用电与否的说明对象。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头是天然材料，不用电，说“这个木头是用电的”不通。"}], "explanations": {"加速器": "加速器：这里指用电驱动的设备，与“是用电的”相合。", "煤": "语义：煤是燃料，不是用电驱动的设备，“是用电的”说它不通。", "面条": "语义：面条是食物，不存在用电与否的说明对象。", "木头": "语义：木头是天然材料，不用电，说“这个木头是用电的”不通。"}, "sentence_index": 6, "correct_answer": "加速器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "物理课上，我们测出了小车的加速器是两米每秒平方。", "explanation": "这里应该用〈加速度〉。加速度是速度变化快慢的数值，单位是米每秒平方；加速器是装置，不能用来表示这一数值。"}, {"text": "这台电视的加速器很大。", "explanation": "这里应该用〈显示屏〉。显示屏是电视的画面部件，加速器是加快速度的装置，电视上并没有它。"}, {"text": "这台加速器能很快脱水，衣服很干。", "explanation": "这里应该用〈洗衣机〉。洗衣机才能脱水，加速器用于加快物体速度，不能用来脱水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师在教室里用一只加速器做演示。", "corrected_sentence": "老师在教室里用一台加速器做演示。", "error_description": "量词错误：“只”多用于动物，加速器是机器，应用“台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们以前修着这台加速器。", "corrected_sentence": "工人们以前修过这台加速器。", "error_description": "体貌错误。“以前”指已经完成的经历，应用“过”，说“修过这台加速器”；“着”表示动作正在持续，与“以前”不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
