INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23928, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做让自己开心的事情来度过时间。", "primary_collocate": null, "pronunciation": "xiāo qiǎn", "ipa": "ɕjɑʊ˥ tɕʰjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "晚饭后，我喜欢出去散步消遣。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车上很无聊，他拿出一本小说消遣。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周日下午，爸爸在院子里养花消遣。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她下班回家，常听音乐消遣。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天夜里，大家坐在树下聊天消遣。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有别的爱好，就爱打牌消遣。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试结束了，我们去唱歌消遣一下吧。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人们在公园下棋消遣，很热闹。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机晚点了，我玩游戏消遣时间。", "target_word": "消遣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子睡了，妈妈看着电视剧消遣。", "target_word": "消遣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "消遣了", "label": "体标"}, {"form": "消遣过", "label": "体标"}, {"form": "消遣消遣", "label": "重叠"}], "register": "中性", "sense_fingerprint": "做开心的事来度过时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be0b31d6-8b06-4c5f-af57-058217ab8309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消遣", "is_correct": true, "explanation": "“消遣”指做让自己开心的事来度过时间，此处说明散步的目的，符合语境。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：晚饭后散步，接着说“喜欢出去散步睡觉”，动作不连贯，句子不成立。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：“出去散步吵架”与休闲散步的日常行为相反，说不通。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”需要具体对象，“散步修理”缺少宾语，搭配不成立。"}], "explanations": {"消遣": "“消遣”指做让自己开心的事来度过时间，此处说明散步的目的，符合语境。", "睡觉": "语义：晚饭后散步，接着说“喜欢出去散步睡觉”，动作不连贯，句子不成立。", "吵架": "语义：“出去散步吵架”与休闲散步的日常行为相反，说不通。", "修理": "搭配：“修理”需要具体对象，“散步修理”缺少宾语，搭配不成立。"}, "sentence_index": 0, "correct_answer": "消遣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上在操场消遣身体。", "explanation": "这里应该用〈锻炼〉。消遣指做开心的事打发时间，锻炼身体不能说“消遣身体”。"}, {"text": "医生每天用药消遣他的病。", "explanation": "这里应该用〈治疗〉。消遣表示打发空闲时间，不用来处理病痛。"}, {"text": "这次长途旅行消遣了他的耐心，他终于放弃了。", "explanation": "这里应该用〈消磨〉。消遣指做开心的事打发时间，耗尽耐心要用“消磨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消遣", "is_correct": true, "explanation": "“消遣”指做让自己开心的事来度过时间，此处是考试后放松的提议，符合语境。"}, {"text": "复习", "is_correct": false, "explanation": "语义：考试已经结束，“去唱歌复习一下”与前句语境矛盾。"}, {"text": "备考", "is_correct": false, "explanation": "语义：考试结束后不需要“备考”，与“考试结束了”的前提冲突。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”需要具体物品作宾语，“去唱歌搬运一下”搭配不成立。"}], "explanations": {"消遣": "“消遣”指做让自己开心的事来度过时间，此处是考试后放松的提议，符合语境。", "复习": "语义：考试已经结束，“去唱歌复习一下”与前句语境矛盾。", "备考": "语义：考试结束后不需要“备考”，与“考试结束了”的前提冲突。", "搬运": "搭配：“搬运”需要具体物品作宾语，“去唱歌搬运一下”搭配不成立。"}, "sentence_index": 6, "correct_answer": "消遣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天消遣房间，很辛苦。", "explanation": "这里应该用〈收拾〉。消遣是打发时间，不能用来指整理房间。"}, {"text": "她每天消遣教室。", "explanation": "这里应该用〈打扫〉。消遣表示做开心的事打发时间，不用于清洁场所。"}, {"text": "农民在田里消遣庄稼。", "explanation": "这里应该用〈种植〉。消遣指拿有趣的活动打发时间，不能用来指照料作物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在操场上消遣很开心。", "corrected_sentence": "他在操场上消遣得很开心。", "error_description": "错误：“消遣很开心”，漏掉了补语的“得”；正确：“消遣得很开心”。表示程度的状态补语必须用“得”连接动词与形容词短语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们每天在屋里画画消遣了。", "corrected_sentence": "孩子们每天在屋里画画消遣。", "error_description": "错误：“每天”表示习惯，却用了完成态的“消遣了”，“了”多余；正确：“每天在屋里画画消遣。”去掉“了”，“消遣”表示习惯性的活动。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
