INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23932, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "达到了最好的情况，没有比这个更好的了。", "primary_collocate": null, "pronunciation": "jí zhì", "ipa": "tɕi˧˥ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这家店的服务已经到了极致。", "target_word": "极致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把舞蹈跳到了极致。", "target_word": "极致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这顿饭让我感受到了味道的极致。", "target_word": "极致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位设计师追求极致的细节。", "target_word": "极致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台相机拍出了极致的画质。", "target_word": "极致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们把环保做到了极致。", "target_word": "极致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "躺在家里的沙发上，就是舒服的极致。", "target_word": "极致", "complexity_tier": "T3", "furigana": "jí zhì", "sentence_source": "generated"}, {"text": "爸爸对干净的要求到了极致。", "target_word": "极致", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画把细节表现到了极致。", "target_word": "极致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想要成功，就要把每件小事做到极致。", "target_word": "极致", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "极致的", "label": "定语形式"}, {"form": "极致体验", "label": "复合"}], "register": "中性", "sense_fingerprint": "极致|达到最好、没有比这更好的了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be0b31d6-8b06-4c5f-af57-058217ab8309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23932, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "极致", "is_correct": true, "explanation": "jí zhì（第二声、第四声）即本词，指达到了最好的境况，没有比这更好的了。"}, {"text": "机制", "is_correct": false, "explanation": "机制 jī zhì 与 jí zhì 只有第一音节声调不同（jī 第一声，jí 第二声），意思是事物内部的构造与运行方式。"}, {"text": "集市", "is_correct": false, "explanation": "集市 jí shì 与 jí zhì 只有第二音节声母不同（sh 与 zh），意思是定期聚集交易的市场。"}, {"text": "极值", "is_correct": false, "explanation": "极值 jí zhí 与 jí zhì 只有第二音节声调不同（zhí 第二声，zhì 第四声），意思是数学上的极大或极小值。"}], "explanations": {"极致": "jí zhì（第二声、第四声）即本词，指达到了最好的境况，没有比这更好的了。", "机制": "机制 jī zhì 与 jí zhì 只有第一音节声调不同（jī 第一声，jí 第二声），意思是事物内部的构造与运行方式。", "集市": "集市 jí shì 与 jí zhì 只有第二音节声母不同（sh 与 zh），意思是定期聚集交易的市场。", "极值": "极值 jí zhí 与 jí zhì 只有第二音节声调不同（zhí 第二声，zhì 第四声），意思是数学上的极大或极小值。"}, "sentence_index": null, "correct_answer": "极致"}, "level_3": {"options": [{"text": "极致", "is_correct": true, "explanation": "与上下文相符：“到了极致”表示服务达到了最好的程度，是固定说法。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“服务到了价格”不成话，句意要求的是程度，而不是价钱。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：服务不能“到了颜色”，与句意不符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“到了年龄”搭配的是人或事物的年限，“服务到了年龄”不符合习惯说法。"}], "explanations": {"极致": "与上下文相符：“到了极致”表示服务达到了最好的程度，是固定说法。", "价格": "语义：“服务到了价格”不成话，句意要求的是程度，而不是价钱。", "颜色": "语义：服务不能“到了颜色”，与句意不符。", "年龄": "搭配：“到了年龄”搭配的是人或事物的年限，“服务到了年龄”不符合习惯说法。"}, "sentence_index": 0, "correct_answer": "极致"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛出现了一个极致的错误。", "explanation": "这里应该用〈严重〉。极致指达到最好的情况，只能形容好的事物；错误是负面的，要用严重。"}, {"text": "这道题极致难，我做不出来。", "explanation": "这里应该用〈极其〉。极致是名词，指最高的程度，不能直接放在形容词前作状语。"}, {"text": "这条小路已经走到了极致，前面就是大海。", "explanation": "这里应该用〈尽头〉。极致指程度上的最高，不指路的终点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23932, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "极致", "is_correct": true, "explanation": "jí zhì（第二声、第四声）即本词，指达到了最好的境况，没有比这更好的了。"}, {"text": "直至", "is_correct": false, "explanation": "直至 zhí zhì 与 jí zhì 只有第一音节声母不同（zh 与 j），意思是一直到某个时间或程度。"}, {"text": "节制", "is_correct": false, "explanation": "节制 jié zhì 与 jí zhì 只有第一音节韵母不同（ie 与 i），意思是控制、有所约束。"}, {"text": "基质", "is_correct": false, "explanation": "基质 jī zhì 与 jí zhì 只有第一音节声调不同（jī 第一声，jí 第二声），意思是物质的基础成分。"}], "explanations": {"极致": "jí zhì（第二声、第四声）即本词，指达到了最好的境况，没有比这更好的了。", "直至": "直至 zhí zhì 与 jí zhì 只有第一音节声母不同（zh 与 j），意思是一直到某个时间或程度。", "节制": "节制 jié zhì 与 jí zhì 只有第一音节韵母不同（ie 与 i），意思是控制、有所约束。", "基质": "基质 jī zhì 与 jí zhì 只有第一音节声调不同（jī 第一声，jí 第二声），意思是物质的基础成分。"}, "sentence_index": null, "correct_answer": "极致"}, "level_3": {"options": [{"text": "极致", "is_correct": true, "explanation": "与上下文相符：“舒服的极致”指舒适达到了最高程度。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“舒服的账单”与句中的“躺在沙发上”的舒适感无关，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“舒服”多形容身体或环境的感受，不能说“舒服的体重”。"}, {"text": "字母", "is_correct": false, "explanation": "语义：“舒服的字母”与句中描述的舒适情境毫不相关。"}], "explanations": {"极致": "与上下文相符：“舒服的极致”指舒适达到了最高程度。", "账单": "语义：“舒服的账单”与句中的“躺在沙发上”的舒适感无关，句意不通。", "体重": "搭配：“舒服”多形容身体或环境的感受，不能说“舒服的体重”。", "字母": "语义：“舒服的字母”与句中描述的舒适情境毫不相关。"}, "sentence_index": 6, "correct_answer": "极致"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的做法太极致了，大家都受不了。", "explanation": "这里应该用〈极端〉。极致指达到最好的境界，多带褒义；做法过激、令人难以接受要用极端。"}, {"text": "今天的天气极致热。", "explanation": "这里应该用〈非常〉。极致是名词，不能作副词修饰“热”。"}, {"text": "这座山我们已经爬到了极致，再往上就没路了。", "explanation": "这里应该用〈尽头〉。极致指程度上的最高，不指地点的终点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这顿饭的味道已经了极致。", "corrected_sentence": "这顿饭的味道已经到了极致。", "error_description": "错误在于“到”被省略。“到了极致”中的“到”不能省，应说“已经到了极致”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把书法练了极致。", "corrected_sentence": "她把书法练到了极致。", "error_description": "错误在于“练到”的补语“到”被省略。应说“练到了极致”，表示练习达到最高水平。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23934, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐藏", "is_correct": true, "explanation": "正确：“隐藏”与“暴露”意思相反，一个是让人看见，一个是不让人看见。"}, {"text": "保持", "is_correct": false, "explanation": "与“暴露”没有反义关系：“保持”指维持某种状态。"}, {"text": "修理", "is_correct": false, "explanation": "与“暴露”没有反义关系：“修理”指修复损坏的东西。"}, {"text": "搬运", "is_correct": false, "explanation": "与“暴露”没有反义关系：“搬运”指把东西从一处移到另一处。"}], "correct_answer": "隐藏", "explanations": {"隐藏": "正确：“隐藏”与“暴露”意思相反，一个是让人看见，一个是不让人看见。", "保持": "与“暴露”没有反义关系：“保持”指维持某种状态。", "修理": "与“暴露”没有反义关系：“修理”指修复损坏的东西。", "搬运": "与“暴露”没有反义关系：“搬运”指把东西从一处移到另一处。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23934, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐藏", "is_correct": true, "explanation": "正确：“隐藏”与“暴露”意思相反，一个是让人看见，一个是藏起来不让人看见。"}, {"text": "打扫", "is_correct": false, "explanation": "与“暴露”没有反义关系：“打扫”指清除脏物。"}, {"text": "种植", "is_correct": false, "explanation": "与“暴露”没有反义关系：“种植”指把植物栽到土里。"}, {"text": "摔碎", "is_correct": false, "explanation": "与“暴露”没有反义关系：“摔碎”指东西因撞击而破碎。"}], "correct_answer": "隐藏", "explanations": {"隐藏": "正确：“隐藏”与“暴露”意思相反，一个是让人看见，一个是藏起来不让人看见。", "打扫": "与“暴露”没有反义关系：“打扫”指清除脏物。", "种植": "与“暴露”没有反义关系：“种植”指把植物栽到土里。", "摔碎": "与“暴露”没有反义关系：“摔碎”指东西因撞击而破碎。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23934, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把原本盖住的东西让外面的人看到。", "primary_collocate": null, "pronunciation": "bào lù", "ipa": "pɑʊ˥˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "水退了，河底的石头暴露出来了。", "target_word": "暴露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不小心暴露了自己的秘密。", "target_word": "暴露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里灯太亮，把我们的位置暴露了。", "target_word": "暴露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查一开始，他的错误就暴露了。", "target_word": "暴露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次说话让他暴露了真实的想法。", "target_word": "暴露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小偷的脚印暴露了他的行踪。", "target_word": "暴露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服破了，里面的东西暴露出来。", "target_word": "暴露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一笑，就暴露了心里的紧张。", "target_word": "暴露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不要暴露地址，太危险了。", "target_word": "暴露", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树倒了，地下的老根暴露在外面。", "target_word": "暴露", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "暴露了", "label": "体标"}, {"form": "暴露着", "label": "体标"}, {"form": "暴露过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使隐藏或被遮盖的东西露出来被人发现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22aa5821-43c2-4f1a-bd68-eccc7ce09b8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暴露", "is_correct": true, "explanation": "正确：“暴露”表示原本盖住的东西被看见，与“石头暴露出来了”相符。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”与“出来”的意思相反，河底的石头不会被隐藏出来。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”用于火或灯，不能用于河底的石头。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧不会使河底的石头露出来，句子意思不通。"}], "explanations": {"暴露": "正确：“暴露”表示原本盖住的东西被看见，与“石头暴露出来了”相符。", "隐藏": "语义：“隐藏”与“出来”的意思相反，河底的石头不会被隐藏出来。", "熄灭": "搭配：“熄灭”用于火或灯，不能用于河底的石头。", "烧": "语义：烧不会使河底的石头露出来，句子意思不通。"}, "sentence_index": 0, "correct_answer": "暴露"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "博物馆里暴露着许多古代文物，供大家参观。", "explanation": "这里应该用〈展示〉。展示是有意摆出来给人看；“暴露”指原本隐藏的东西被看见，常带有意外或不利的意味。"}, {"text": "屏幕上暴露着今天的天气。", "explanation": "这里应该用〈显示〉。显示用于屏幕、仪表等；“暴露”不用于屏幕上的信息。"}, {"text": "老师暴露了他的努力。", "explanation": "这里应该用〈表扬〉。“表扬”是肯定别人的好行为；“暴露”指把隐藏的东西显露出来，不用于肯定努力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暴露", "is_correct": true, "explanation": "正确：“暴露”表示里面的东西被看见，与“衣服破了，里面的东西暴露出来”相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮不会让衣服里面的东西露出来，句子意思不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱出来”只用于歌曲，不能说东西“唱出来”。"}, {"text": "编", "is_correct": false, "explanation": "语义：“编”是虚构、编造，与东西露出来的意思无关。"}], "explanations": {"暴露": "正确：“暴露”表示里面的东西被看见，与“衣服破了，里面的东西暴露出来”相符。", "煮": "语义：煮不会让衣服里面的东西露出来，句子意思不通。", "唱": "搭配：“唱出来”只用于歌曲，不能说东西“唱出来”。", "编": "语义：“编”是虚构、编造，与东西露出来的意思无关。"}, "sentence_index": 6, "correct_answer": "暴露"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张照片暴露过度，看起来发白。", "explanation": "这里应该用〈曝光〉。拍照时光线过强称“曝光过度”；“暴露”指原本隐藏的东西被看见，不用于照片。"}, {"text": "电影院今晚暴露新片，欢迎大家。", "explanation": "这里应该用〈放映〉。放映指用设备播放影片；“暴露”不能用于播放影片。"}, {"text": "政府今天暴露了新的天气预报。", "explanation": "这里应该用〈发布〉。发布是正式公开发出消息；“暴露”指原本隐藏的东西被发现，不用于公开发布信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "退潮后，海滩上的贝壳暴露来了。", "corrected_sentence": "退潮后，海滩上的贝壳暴露出来了。", "error_description": "“出来”是趋向补语，不能省略“出”。正确是“暴露出来了”，错误是“暴露来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没暴露了自己的真实身份。", "corrected_sentence": "他从来没暴露过自己的真实身份。", "error_description": "“没”否定有过的经历时，“暴露”后应接“过”，不能接“了”。正确是“没暴露过”，错误是“没暴露了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
