INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23936, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "藏在身体里的本事，以后可以变出来。", "primary_collocate": null, "pronunciation": "qián néng", "ipa": "tɕʰjɛn˧˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小明身体里有很大的潜能。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别急，你的潜能以后会慢慢出来。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子游泳的潜能很大。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我有画画的潜能。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人身体里都藏着潜能。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多练习，才能把潜能变成本事。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练发现了他的跑步潜能。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟个子小，但是跑步的潜能很大。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道自己有什么潜能。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好好吃饭睡觉，身体的潜能才会长出来。", "target_word": "潜能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "藏在身体里、以后能表现出来的本事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2900ff34-7b63-430a-b418-659efc01403e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23936, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不用“很大”来修饰，“很大的颜色”不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不在身体里，“身体里有很大的书包”文意不通。"}, {"text": "宿舍", "is_correct": false, "explanation": "语义：宿舍是居住的地方，不在身体里，“身体里有很大的宿舍”文意不通。"}, {"text": "潜能", "is_correct": true, "explanation": "潜能指藏在身体里、以后能显现的本事，这里符合语境。"}], "explanations": {"颜色": "搭配：颜色不用“很大”来修饰，“很大的颜色”不通。", "书包": "语义：书包是物品，不在身体里，“身体里有很大的书包”文意不通。", "宿舍": "语义：宿舍是居住的地方，不在身体里，“身体里有很大的宿舍”文意不通。", "潜能": "潜能指藏在身体里、以后能显现的本事，这里符合语境。"}, "sentence_index": 0, "correct_answer": "潜能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他能轻松扛起一百斤的重物，潜能很大。", "explanation": "这里应该用〈力气〉。能直接扛起重物说明力气已经显现；潜能指藏着、尚未显现的本事。"}, {"text": "他的脾气很暴躁，潜能很大，大家都怕他。", "explanation": "这里应该用〈性格〉。形容性情急躁要说性格；潜能指藏在身体里、以后可以显现的本事，不用于形容性情。"}, {"text": "他今天很开心，潜能特别好。", "explanation": "这里应该用〈心情〉。开心说的是心情；潜能指藏在身体里、以后可以显现的本事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23936, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口味", "is_correct": false, "explanation": "搭配：“跑步的口味”不成立，口味不能用“跑步”修饰。"}, {"text": "相机", "is_correct": false, "explanation": "语义：相机是器材，不是跑步的能力，“跑步的相机”文意不通。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能是跑步的能力，“跑步的蛋糕”不通。"}, {"text": "潜能", "is_correct": true, "explanation": "潜能指藏在身体里、以后能显现的本事，这里指他跑步方面的能力，符合语境。"}], "explanations": {"口味": "搭配：“跑步的口味”不成立，口味不能用“跑步”修饰。", "相机": "语义：相机是器材，不是跑步的能力，“跑步的相机”文意不通。", "蛋糕": "语义：蛋糕是食物，不能是跑步的能力，“跑步的蛋糕”不通。", "潜能": "潜能指藏在身体里、以后能显现的本事，这里指他跑步方面的能力，符合语境。"}, "sentence_index": 6, "correct_answer": "潜能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的游泳潜能已经很熟练了。", "explanation": "这里应该用〈技能〉。熟练说的是已经掌握的技能；潜能是还没显现出来的本事，不能说熟练。"}, {"text": "她瘦了五公斤，潜能变得很苗条。", "explanation": "这里应该用〈身材〉。苗条形容身材；潜能不能用来形容人的体型。"}, {"text": "这顿饭的潜能很大，我吃得很饱。", "explanation": "这里应该用〈饭量〉。吃饱多少说明的是饭量；潜能指藏在身体里、以后可以显现的本事，不用于说吃了多少东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我相信自己身体里藏着一件潜能。", "corrected_sentence": "我相信自己身体里藏着一种潜能。", "error_description": "量词错误：“潜能”应用量词“种”，不能用“件”（件多用于事情、物品）。正确说法是“一种潜能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教练以前发现着他的跑步潜能。", "corrected_sentence": "教练以前发现过他的跑步潜能。", "error_description": "体标错误：“以前”指过去的经历，应用“过”；“着”表示持续状态，与“以前”不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
