INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23940, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "起源于某处或某事物，由它而来。", "primary_collocate": null, "pronunciation": "yuán yú", "ipa": "ɥɛn˧˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "这条河源于高山。", "target_word": "源于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "长江源于青藏高原。", "target_word": "源于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个节日源于很久以前的故事。", "target_word": "源于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的好习惯源于小时候的家庭教育。", "target_word": "源于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多汉字源于图画。", "target_word": "源于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个故事源于一件真事。", "target_word": "源于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的快乐源于对生活的爱。", "target_word": "源于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种菜源于四川，现在全国都有。", "target_word": "源于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我画画的想法源于大自然。", "target_word": "源于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个词源于古代的一种说法。", "target_word": "源于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "源於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "源于：起源于某处或某事物，来自它", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffce3848-4e7c-4ec3-885e-673579ba7e56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23940, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "源于", "is_correct": true, "explanation": "正确：“源于”（yuányú）指来自某处，是这个词本身。"}, {"text": "原油", "is_correct": false, "explanation": "yóu（第二声）与 yú 韵母不同（ou/u），意思是石油。"}, {"text": "悬于", "is_correct": false, "explanation": "xuányú（悬于）与 yuányú 仅声母不同（x/y），意思是悬在某处。"}, {"text": "原语", "is_correct": false, "explanation": "yuányǔ（原语）与 yuányú 仅第二音节声调不同，意思是原文的语言。"}], "explanations": {"源于": "正确：“源于”（yuányú）指来自某处，是这个词本身。", "原油": "yóu（第二声）与 yú 韵母不同（ou/u），意思是石油。", "悬于": "xuányú（悬于）与 yuányú 仅声母不同（x/y），意思是悬在某处。", "原语": "yuányǔ（原语）与 yuányú 仅第二音节声调不同，意思是原文的语言。"}, "sentence_index": null, "correct_answer": "源于"}, "level_3": {"options": [{"text": "源于", "is_correct": true, "explanation": "正确：“源于”说河的起源，与“这条河”“高山”搭配。"}, {"text": "流向", "is_correct": false, "explanation": "语义：“流向”说水流的走向，不说河从哪里开始。"}, {"text": "注入", "is_correct": false, "explanation": "搭配：“注入”的宾语多是湖海等水域，不能说注入高山。"}, {"text": "连接", "is_correct": false, "explanation": "语义：“连接”指两地相通，与“河的起点在高山”的句意不符。"}], "explanations": {"源于": "正确：“源于”说河的起源，与“这条河”“高山”搭配。", "流向": "语义：“流向”说水流的走向，不说河从哪里开始。", "注入": "搭配：“注入”的宾语多是湖海等水域，不能说注入高山。", "连接": "语义：“连接”指两地相通，与“河的起点在高山”的句意不符。"}, "sentence_index": 0, "correct_answer": "源于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老师源于三楼，教我们英语。", "explanation": "这里应该用〈在〉。“源于”表示起源，不表示所在位置，说人所在的地方要用“在”。"}, {"text": "这个班源于三十个学生。", "explanation": "这里应该用〈有〉。“源于”表示起源，不表示数量，说班里有多少人要用“有”。"}, {"text": "这次聚会源于下周六。", "explanation": "这里应该用〈定于〉。“源于”表示事物的来源，不表示活动的时间安排，说聚会定在哪天要用“定于”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "源于", "is_correct": true, "explanation": "正确：“源于”说快乐的来源，与“对生活的爱”搭配。"}, {"text": "缺乏", "is_correct": false, "explanation": "语义：“缺乏”表示没有某物，与“快乐来自爱”的句意相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”需要人作主语，“快乐”不能去拒绝什么，句意不通。"}, {"text": "违背", "is_correct": false, "explanation": "语义：“违背”指与原则相悖，不能说快乐违背爱。"}], "explanations": {"源于": "正确：“源于”说快乐的来源，与“对生活的爱”搭配。", "缺乏": "语义：“缺乏”表示没有某物，与“快乐来自爱”的句意相反。", "拒绝": "搭配：“拒绝”需要人作主语，“快乐”不能去拒绝什么，句意不通。", "违背": "语义：“违背”指与原则相悖，不能说快乐违背爱。"}, "sentence_index": 6, "correct_answer": "源于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫源于沙发下面。", "explanation": "这里应该用〈在〉。“源于”表示起源，不表示事物所在的位置，说位置要用“在”。"}, {"text": "这所学校源于山脚下。", "explanation": "这里应该用〈坐落于〉。“源于”表示起源，不表示建筑的位置。"}, {"text": "这家工厂源于城外。", "explanation": "这里应该用〈设在〉。“源于”不表示位置，说工厂的位置要用“设在”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种乐器源于了西域，后来传到中原。", "corrected_sentence": "这种乐器源于西域，后来传到中原。", "error_description": "体标错误：“源于”是动词，后面不能直接加“了”，应为“这种乐器源于西域”，不能说“源于了西域”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种习俗被源于古代的农业生产。", "corrected_sentence": "这种习俗源于古代的农业生产。", "error_description": "语态错误：“源于”是不及物动词，没有被动用法，不能在前面加“被”，应为“这种习俗源于古代的农业生产”，不能说“被源于”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
