INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23942, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23942, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "某样东西属于谁，就是谁的。", "primary_collocate": null, "pronunciation": "guī shǔ", "ipa": "kweɪ˥ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这辆自行车归属于学校宿舍，别随便骑走。", "target_word": "归属", "complexity_tier": "T3", "furigana": "guī shǔ", "sentence_source": "generated"}, {"text": "公园里的花草都归属于国家。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那本旧词典归属于图书馆，不能卖。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张桌子归属于谁，请你问问老师。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们吵了很久，不知道这块表归属于谁。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合同上写着，这套房子归属于妻子。", "target_word": "归属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些玩具归属于幼儿园，小朋友可以借来玩。", "target_word": "归属", "complexity_tier": "T3", "furigana": "guī shǔ", "sentence_source": "generated"}, {"text": "这张照片归属于摄影社，社员不能私自转发。", "target_word": "归属", "complexity_tier": "T3", "furigana": "guī shǔ", "sentence_source": "generated"}, {"text": "这笔钱归属于公司，不是个人的。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的操场归属于全校同学。", "target_word": "归属", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "归属于", "label": "搭配"}], "register": "中性", "sense_fingerprint": "东西属于谁就是谁的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be0b31d6-8b06-4c5f-af57-058217ab8309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23942, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "归属", "is_correct": true, "explanation": "正确：“归属于学校宿舍”表示车辆属于宿舍，与“别随便骑走”一致。"}, {"text": "效忠", "is_correct": false, "explanation": "语义：“效忠”指对人或国家忠诚，车辆不能“效忠于”宿舍。"}, {"text": "等同", "is_correct": false, "explanation": "语义：“等同于”表示相等，自行车不等于宿舍，也不表示东西属于谁。"}, {"text": "陷入", "is_correct": false, "explanation": "搭配：“陷入”后接困境等，且不说“陷入于”，句子不成立。"}], "explanations": {"归属": "正确：“归属于学校宿舍”表示车辆属于宿舍，与“别随便骑走”一致。", "效忠": "语义：“效忠”指对人或国家忠诚，车辆不能“效忠于”宿舍。", "等同": "语义：“等同于”表示相等，自行车不等于宿舍，也不表示东西属于谁。", "陷入": "搭配：“陷入”后接困境等，且不说“陷入于”，句子不成立。"}, "sentence_index": 0, "correct_answer": "归属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事最终归属于平静。", "explanation": "这里应该用〈归于〉。归属表示所属，不能表示事情最终变成平静的状态。"}, {"text": "这份资料最终归属于一个结论。", "explanation": "这里应该用〈归纳〉。归属表示所属，不能表示从资料中概括出结论。"}, {"text": "这两个班最终归属于一个班。", "explanation": "这里应该用〈归并〉。归属表示所属，不能表示两个班合并成一个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "归属", "is_correct": true, "explanation": "正确：“归属于幼儿园”表示玩具属于幼儿园，与“小朋友可以借来玩”一致。"}, {"text": "依赖", "is_correct": false, "explanation": "语义：玩具不能“依赖”幼儿园，与“借来玩”的语境矛盾。"}, {"text": "屈服", "is_correct": false, "explanation": "语义：玩具不会“屈服于”幼儿园，句意无法成立。"}, {"text": "献身", "is_correct": false, "explanation": "搭配：“献身于”后接事业或理想，不接玩具与幼儿园。"}], "explanations": {"归属": "正确：“归属于幼儿园”表示玩具属于幼儿园，与“小朋友可以借来玩”一致。", "依赖": "语义：玩具不能“依赖”幼儿园，与“借来玩”的语境矛盾。", "屈服": "语义：玩具不会“屈服于”幼儿园，句意无法成立。", "献身": "搭配：“献身于”后接事业或理想，不接玩具与幼儿园。"}, "sentence_index": 6, "correct_answer": "归属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他伤好后终于归属于原来的部队，又能训练了。", "explanation": "这里应该用〈归队〉。归属表示所属，不能表示伤愈后回到原来的部队。"}, {"text": "一切都归属于平静。", "explanation": "这里应该用〈归于〉。归属只表示所属，不能表示最终变成某种状态。"}, {"text": "玩完游戏后，棋子要归属于原位。", "explanation": "这里应该用〈归位〉。归属表示所属，不能表示把棋子放回原位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把伞归属在那位老师。", "corrected_sentence": "这把伞归属于那位老师。", "error_description": "错误在于“归属”后的介词用错。引出归属方要用“于”，“在”表示处所，应为“归属于那位老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块地归属给村里。", "corrected_sentence": "这块地归属于村里。", "error_description": "错误在于“归属”后的介词用错。引出归属方要用“于”，不用“给”，应为“归属于村里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
