INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23944, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23944, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你觉得自己属于一个地方或一个群体，心里很安稳。", "primary_collocate": null, "pronunciation": "guī shǔ gǎn", "ipa": "kweɪ˥ ʂu˨˩˦ kan˨˩˦", "syllable_count": 3, "sentences": [{"text": "在家里，我总是觉得很有归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他离开家乡多年，一直没有归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小店像家一样，客人都很有归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班同学感情好，大家都有归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬了三次家，孩子还没有找到归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们的笑声，给了我一种归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她喜欢这座小城，因为这里有归属感。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有归属感的人，常常觉得很孤单。", "target_word": "归属感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司给新同事开了欢迎会，增强了他们的归属感。", "target_word": "归属感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回到老房子，我心里有一种安稳的归属感。", "target_word": "归属感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种归属感", "label": "量词"}, {"form": "一份归属感", "label": "量词"}], "register": "中性", "sense_fingerprint": "觉得属于某处或某群体而心里安稳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be0b31d6-8b06-4c5f-af57-058217ab8309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23944, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "归属感", "is_correct": true, "explanation": "“归属感”指觉得属于某地而心里安稳，与“在家里”的语境相符。"}, {"text": "股票", "is_correct": false, "explanation": "语义：“在家里觉得很有股票”，两者不相关，句子不成立。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积是物体的属性，不能用来形容“我”的心理感受。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“很有”后接“工资”不构成表达心理感受的搭配。"}], "explanations": {"归属感": "“归属感”指觉得属于某地而心里安稳，与“在家里”的语境相符。", "股票": "语义：“在家里觉得很有股票”，两者不相关，句子不成立。", "体积": "语义：体积是物体的属性，不能用来形容“我”的心理感受。", "工资": "搭配：“很有”后接“工资”不构成表达心理感受的搭配。"}, "sentence_index": 0, "correct_answer": "归属感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他考了零分，心里却很有归属感。", "explanation": "这里应该用〈沮丧〉。归属感指觉得属于某群体的心理认同，考砸后的失望要用“沮丧”。"}, {"text": "老师对学生很有归属感。", "explanation": "这里应该用〈同情心〉。归属感指觉得属于某群体的心理认同，不表示对他人的怜悯。"}, {"text": "他说话很有归属感。", "explanation": "这里应该用〈幽默感〉。归属感指觉得属于某地或群体的认同，不用来描述说话的风格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "归属感", "is_correct": true, "explanation": "“归属感”指觉得属于某地而心里安稳，是她喜欢这座城市的理由，符合语境。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温不是让人喜欢一座城市的理由，“因为这里有体温”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：有窗户并不能构成她喜欢这座小城的理由，句子不成立。"}, {"text": "螺丝", "is_correct": false, "explanation": "搭配：“有螺丝”不构成描述地方特点的常见搭配。"}], "explanations": {"归属感": "“归属感”指觉得属于某地而心里安稳，是她喜欢这座城市的理由，符合语境。", "体温": "语义：体温不是让人喜欢一座城市的理由，“因为这里有体温”说不通。", "窗户": "语义：有窗户并不能构成她喜欢这座小城的理由，句子不成立。", "螺丝": "搭配：“有螺丝”不构成描述地方特点的常见搭配。"}, "sentence_index": 6, "correct_answer": "归属感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没有被选上，心里却很有归属感。", "explanation": "这里应该用〈失落感〉。归属感指觉得属于某群体的心理认同，落选后的失落要用“失落感”。"}, {"text": "他一整天没吃饭，归属感很强。", "explanation": "这里应该用〈饥饿感〉。归属感指觉得属于某地或群体的心理认同，空腹的感觉要用“饥饿感”。"}, {"text": "孩子对新事物很有归属感。", "explanation": "这里应该用〈好奇心〉。归属感指觉得属于某地或群体的心理安稳，不表示求知的兴趣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "搬到新城市后，我才慢慢有了一只归属感。", "corrected_sentence": "搬到新城市后，我才慢慢有了一种归属感。", "error_description": "错误：“一只归属感”，量词“只”不能修饰抽象的心理感受；正确：“一种归属感”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在这座小城里找到了很归属感。", "corrected_sentence": "她在这座小城里找到了归属感。", "error_description": "错误：“很归属感”，程度副词“很”不能直接修饰名词“归属感”；正确：“找到了归属感”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
