INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23946, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生来就注定、人改变不了的命运。", "primary_collocate": null, "pronunciation": "sù mìng", "ipa": "su˥˩ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他说这次见面是宿命。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不信宿命，我相信自己。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得分手是宿命，不能改变。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷总是把生病说成宿命。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人认为，宿命早已安排好一切，谁也改变不了。", "target_word": "宿命", "complexity_tier": "T3", "furigana": "yǒu rén rèn wéi, sù mìng zǎo yǐ ān pái hǎo yí qiè, shéi yě gǎi biàn bu liǎo.", "sentence_source": "generated"}, {"text": "听了朋友的话，我不再相信宿命。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得考不上大学是宿命。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宿命的想法让他不想再努力。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人笑着说：“这就是宿命。”", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对困难，她从不相信宿命。", "target_word": "宿命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宿命论", "label": "复合"}], "register": "书面", "sense_fingerprint": "宿命：早已注定、无法改变的命运", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81f83eb8-767f-466e-a846-5878bcd12e3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宿命", "is_correct": true, "explanation": "宿命：觉得某些事注定发生、无力改变，与“这次见面是……”的判断相合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是电器，不能作为对“见面”的判断。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：“衣服”是物品，不能用来判断“见面”的性质。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指体型，不能用来判断“见面”的性质。"}], "explanations": {"宿命": "宿命：觉得某些事注定发生、无力改变，与“这次见面是……”的判断相合。", "冰箱": "语义：“冰箱”是电器，不能作为对“见面”的判断。", "衣服": "语义：“衣服”是物品，不能用来判断“见面”的性质。", "身高": "体貌：“身高”指体型，不能用来判断“见面”的性质。"}, "sentence_index": 0, "correct_answer": "宿命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的宿命很工整。", "explanation": "这里应该用〈字迹〉。宿命是观念，不能用来形容字写得工整。"}, {"text": "他的宿命很高大。", "explanation": "这里应该用〈身材〉。宿命不能用来形容人的体型高大。"}, {"text": "他把宿命寄给了远方的朋友。", "explanation": "这里应该用〈信件〉。宿命是一种观念，不是能寄出去的东西；寄出的要说“信件”或“包裹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宿命", "is_correct": true, "explanation": "宿命：觉得考不上大学是注定的事、无力改变，与句意相合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不能作为对“考不上大学”的判断。"}, {"text": "命根子", "is_correct": false, "explanation": "语域：“命根子”是口语，指心爱之物，与书面语体不合，且句意不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是开锁的工具，不能作为对“考不上大学”的判断。"}], "explanations": {"宿命": "宿命：觉得考不上大学是注定的事、无力改变，与句意相合。", "桌子": "语义：“桌子”是家具，不能作为对“考不上大学”的判断。", "命根子": "语域：“命根子”是口语，指心爱之物，与书面语体不合，且句意不通。", "钥匙": "语义：“钥匙”是开锁的工具，不能作为对“考不上大学”的判断。"}, "sentence_index": 6, "correct_answer": "宿命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个宿命需要大家一起完成。", "explanation": "这里应该用〈计划〉。宿命是观念，不是需要大家去完成的事。"}, {"text": "她对待工作的宿命很认真。", "explanation": "这里应该用〈态度〉。宿命不能用来形容做事是否认真。"}, {"text": "她的宿命很温柔。", "explanation": "这里应该用〈性格〉。宿命是观念，不能用来形容一个人温柔的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他觉得宿命早已注定，怎么努力也改变不起。", "corrected_sentence": "他觉得宿命早已注定，怎么努力也改变不了。", "error_description": "补语用错：表示能力上无法实现应说“改变不了”；“不起”多用于负担或承受不起（如“买不起”），不能用在“改变”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没相信了宿命。", "corrected_sentence": "我从来没相信过宿命。", "error_description": "体标错误：“没”否定过去经历时用“过”，不能和“了”连用，应说“没相信过宿命”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06c83916-8394-421a-97ba-878b69bf559a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
