INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23948, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "小宝宝从妈妈肚子里出来，来到世界上。", "primary_collocate": null, "pronunciation": "dàn shēng", "ipa": "tan˥˩ ʂəŋ˥", "syllable_count": 2, "sentences": [{"text": "昨天晚上，我们家诞生了一个小宝宝。", "target_word": "诞生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小宝宝诞生在一个下雪的早上。", "target_word": "诞生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子诞生在北京，后来搬到了上海。", "target_word": "诞生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小宝宝诞生的那天，全家人都很高兴。", "target_word": "诞生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妹妹诞生在一个春天的晚上。", "target_word": "诞生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说医院里今天诞生了三个宝宝。", "target_word": "诞生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子诞生后，爸爸马上给奶奶打电话。", "target_word": "诞生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她诞生的时候，外面正在下雨。", "target_word": "诞生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小宝宝诞生了，妈妈很累，但是很开心。", "target_word": "诞生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都在等新生命诞生。", "target_word": "诞生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诞生了", "label": "完成体"}, {"form": "诞生过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "婴儿出生，来到世界上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffce3848-4e7c-4ec3-885e-673579ba7e56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诞生", "is_correct": true, "explanation": "诞生指小宝宝来到世界上，与“小宝宝”和“昨天晚上”相合，句意通顺。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的宾语是商品，不能说买一个小宝宝。"}, {"text": "离开", "is_correct": false, "explanation": "语义：离开指离去，不能表示家里迎来一个新生的小宝宝。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理用于器物，不能修理一个小宝宝。"}], "explanations": {"诞生": "诞生指小宝宝来到世界上，与“小宝宝”和“昨天晚上”相合，句意通顺。", "买": "搭配：“买”的宾语是商品，不能说买一个小宝宝。", "离开": "语义：离开指离去，不能表示家里迎来一个新生的小宝宝。", "修理": "语义：修理用于器物，不能修理一个小宝宝。"}, "sentence_index": 0, "correct_answer": "诞生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛晚上九点诞生。", "explanation": "这里应该用〈开始〉。诞生指生命或新事物出现，比赛开始时不说诞生。"}, {"text": "事故昨天下午诞生了。", "explanation": "这里应该用〈发生〉。诞生用于新生命或新事物出现，事故这类不好的事情要说发生。"}, {"text": "我们明天诞生去北京。", "explanation": "这里应该用〈出发〉。诞生只说新生命或新事物出现，人离开某地去别处要说出发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诞生", "is_correct": true, "explanation": "诞生指孩子来到世界上，与“孩子”和“爸爸给奶奶打电话”的报喜情境相合。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化用于冰、雪等，孩子不能融化。"}, {"text": "枯萎", "is_correct": false, "explanation": "语义：枯萎用于花草，不能用于孩子。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：生锈用于铁器，孩子不能生锈。"}], "explanations": {"诞生": "诞生指孩子来到世界上，与“孩子”和“爸爸给奶奶打电话”的报喜情境相合。", "融化": "语义：融化用于冰、雪等，孩子不能融化。", "枯萎": "语义：枯萎用于花草，不能用于孩子。", "生锈": "搭配：生锈用于铁器，孩子不能生锈。"}, "sentence_index": 6, "correct_answer": "诞生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他又诞生了一个错误。", "explanation": "这里应该用〈犯〉。诞生用于新生命或新事物，不能和“错误”搭配，应说犯错误。"}, {"text": "这个家庭每天都诞生一顿晚饭。", "explanation": "搭配：诞生不能和“晚饭”搭配，做晚饭应说“做”。"}, {"text": "他的身上诞生了很多汗。", "explanation": "搭配：汗是身体排出的液体，不能说诞生，应说“出”汗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的表哥诞生一个小山村。", "corrected_sentence": "我的表哥诞生在一个小山村。", "error_description": "错误：“诞生”后漏掉介词，说明出生地点要用“诞生在……”或书面的“诞生于……”。正确：“我的表哥诞生在一个小山村。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小宝宝昨天晚上诞生完了。", "corrected_sentence": "小宝宝昨天晚上诞生了。", "error_description": "错误：“诞生”本身已表示出生这一完成的动作，不能再加补语“完”。正确：“小宝宝昨天晚上诞生了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
