INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23952, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一件事从头到尾说清楚。", "primary_collocate": null, "pronunciation": "xù shì", "ipa": "ɕy⁵¹ ʂɻ⁵¹", "syllable_count": 2, "sentences": [{"text": "这篇文章以叙事为主。", "target_word": "叙事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人叙事很有条理。", "target_word": "叙事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎样叙事。", "target_word": "叙事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗既抒情又叙事。", "target_word": "叙事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作文可以叙事，也可以写景。", "target_word": "叙事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叙事要有开头和结尾。", "target_word": "叙事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用第一人称叙事。", "target_word": "叙事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影用两条线叙事。", "target_word": "叙事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写信时，他先叙事，后说想法。", "target_word": "叙事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家喜欢用简单的话叙事。", "target_word": "叙事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "叙事诗", "label": "复合"}, {"form": "叙事文", "label": "复合"}, {"form": "叙事性", "label": "复合"}], "register": "书面", "sense_fingerprint": "按顺序讲述事情的经过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe847b-453c-49ae-ad59-f1b51c9b852b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23952, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叙事", "is_correct": true, "explanation": "正确：「叙事」指讲述事情的经过，可以作为文章的主要表达方式。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：文章不能以“睡觉”为主，「睡觉」与文章的表达方式无关。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：文章不能以“跳舞”为主，「跳舞」是人的动作。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：文章不能以“洗澡”为主，「洗澡」是日常生活动作，不是表达方式。"}], "explanations": {"叙事": "正确：「叙事」指讲述事情的经过，可以作为文章的主要表达方式。", "睡觉": "语义：文章不能以“睡觉”为主，「睡觉」与文章的表达方式无关。", "跳舞": "语义：文章不能以“跳舞”为主，「跳舞」是人的动作。", "洗澡": "语义：文章不能以“洗澡”为主，「洗澡」是日常生活动作，不是表达方式。"}, "sentence_index": 0, "correct_answer": "叙事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段文字细致地叙事了山景。", "explanation": "这里应该用〈描写〉。叙事讲述事情的经过，描写景物要用“描写”。"}, {"text": "这首诗叙事了他的心情。", "explanation": "这里应该用〈抒情〉。叙事讲述事件，表达心情要用“抒情”。"}, {"text": "这位数学家叙事了一个公式。", "explanation": "语义：「叙事」讲述事情的经过，公式不是事件，这里应该用〈推导〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23952, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叙事", "is_correct": true, "explanation": "正确：「叙事」指以某种视角讲述事情，与“第一人称”搭配，符合句意。"}, {"text": "散步", "is_correct": false, "explanation": "语义：「散步」是人的休闲活动，不能“用第一人称”来进行。"}, {"text": "生气", "is_correct": false, "explanation": "语义：「生气」是情绪状态，不能“用第一人称”来进行。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：「吃饭」是日常动作，不能“用第一人称”来进行。"}], "explanations": {"叙事": "正确：「叙事」指以某种视角讲述事情，与“第一人称”搭配，符合句意。", "散步": "语义：「散步」是人的休闲活动，不能“用第一人称”来进行。", "生气": "语义：「生气」是情绪状态，不能“用第一人称”来进行。", "吃饭": "语义：「吃饭」是日常动作，不能“用第一人称”来进行。"}, "sentence_index": 6, "correct_answer": "叙事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会计每天在账本上叙事收支情况。", "explanation": "语义：这里把“叙事”当成了“记录、登记”的意思。“叙事”指把事情从头到尾说清楚，记录收支要用“记录”。"}, {"text": "他叙事了一块蛋糕。", "explanation": "语义：「叙事」讲述的是事件的经过，不能以食物作宾语。"}, {"text": "天气预报员每天叙事明天的天气。", "explanation": "语义：这里把“叙事”当成了“预报、预告”的意思。“叙事”是讲述已经发生的事情，预告未来的天气要用“预报”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23952, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人叙事地很清楚。", "corrected_sentence": "这位老人叙事得很清楚。", "error_description": "错误：“叙事地”。正确：“叙事得”。动词后接补语要用“得”，不用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23952, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位作家把叙事很简练。", "corrected_sentence": "这位作家叙事很简练。", "error_description": "错误：“把叙事很简练”。“把”字句的结构是“把+受事+动词”，这里“把”后没有受事，应去掉“把”，说“这位作家叙事很简练。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23954, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23954, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23954, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "意思是以后一定会发生。", "primary_collocate": null, "pronunciation": "zhōng jiāng", "ipa": "ʈʂʊŋ˥ tɕjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "小树终将长成大树。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪终将变成水。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题终将解决。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天练习，终将成为好歌手。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在不懂，以后终将明白。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏天气终将过去，明天会更好。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她相信自己终将回到家乡。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路虽然很长，但你终将走到终点。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们终将见面，不用太难过。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天终将结束，学校又要开学了。", "target_word": "终将", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "終將", "label": "繁体"}], "register": "书面", "sense_fingerprint": "终将:副词，以后一定会发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcdeda5-d8c7-49c0-8c4a-eb7c9e6fe46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23954, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "终将", "is_correct": true, "explanation": "“终将”表示经过较长时间必然实现，与“小树长成大树”的将来过程相合。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定词连用，“小树从来长成大树”不成立。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”指马上完成，与“长成大树”需要长时间成长的过程不符。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”修饰不常发生的动作，不能用于“长成大树”这种持续的变化。"}], "explanations": {"终将": "“终将”表示经过较长时间必然实现，与“小树长成大树”的将来过程相合。", "从来": "搭配：“从来”多与否定词连用，“小树从来长成大树”不成立。", "立刻": "语义：“立刻”指马上完成，与“长成大树”需要长时间成长的过程不符。", "偶尔": "搭配：“偶尔”修饰不常发生的动作，不能用于“长成大树”这种持续的变化。"}, "sentence_index": 0, "correct_answer": "终将"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟弟昨天终将考完试，我们都很高兴。", "explanation": "这里应该用〈终于〉。“终将”表示将来必然出现，句中的“昨天”已经过去，不能描述已经完成的事。"}, {"text": "去年，他终将获胜。", "explanation": "这里应该用〈最终〉。“终将”只用于将来必然会出现的结果，“去年”的获胜已经发生。"}, {"text": "这班车马上终将到站。", "explanation": "这里应该用〈就要〉。“终将”指将来必然会出现的结果，“马上”指眼前的事，两者语义冲突，应用“就要”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "终将", "is_correct": true, "explanation": "“终将”表示将来必然实现，与“相信自己”后面的未来愿望相合。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”是程度副词，不能修饰“回到家乡”这样的动作。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”需与否定词连用，不能直接用在“相信自己”之后表示将来的回家。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续的动作，不能与“回到”这类一次性的结果动词连用。"}], "explanations": {"终将": "“终将”表示将来必然实现，与“相信自己”后面的未来愿望相合。", "非常": "搭配：“非常”是程度副词，不能修饰“回到家乡”这样的动作。", "从来": "搭配：“从来”需与否定词连用，不能直接用在“相信自己”之后表示将来的回家。", "一直": "搭配：“一直”表示持续的动作，不能与“回到”这类一次性的结果动词连用。"}, "sentence_index": 6, "correct_answer": "终将"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "前天晚上，他终将没有回家。", "explanation": "这里应该用〈终究〉。“终将”指将来必然发生，句中的“前天晚上”已经过去，不能用“终将”描述已经发生的事。"}, {"text": "那天，他终将同意我们去。", "explanation": "这里应该用〈最后〉。这是当天已经做出的同意，“终将”只用来说将来必然出现的结果。"}, {"text": "刚才他终将离开教室。", "explanation": "这里应该用〈已经〉。“终将”指将来必然发生的结果，“刚才”说的是刚发生的事，应该用“已经”表示已经完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些烦恼终将过去了。", "corrected_sentence": "这些烦恼终将过去。", "error_description": "错误在于“终将”与“了”连用。“终将”表示将来必然发生，不能与表示完成的“了”搭配，应说“这些烦恼终将过去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法终将被人们接受了。", "corrected_sentence": "这个办法终将被人们接受。", "error_description": "错误在于“终将”与“了”连用。“终将”表示将来必然发生，不能与表示完成的“了”搭配，应说“这个办法终将被人们接受”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
