INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23956, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让你知道一个道理。", "primary_collocate": null, "pronunciation": "qǐ shì", "ipa": "tɕʰi²¹⁴ ʂɨ⁵¹", "syllable_count": 2, "sentences": [{"text": "这个故事启示我们要诚实。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件小事启示我们要珍惜时间。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用一个例子启示学生。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚂蚁搬家启示我们要团结。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗启示人们热爱生活。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次失败启示他换个方法。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人的话启示我们要谦虚。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验启示我们要认真观察。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的话启示了我，我明白了很多。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片启示人们保护环境。", "target_word": "启示", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "启示了", "label": "体标"}, {"form": "啟示", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：某人或某事让人明白一个道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '842fb074-b13a-42dd-9ece-3ecc7134eb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23956, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "启示", "is_correct": true, "explanation": "启示：使人领悟道理，即本题目标词。"}, {"text": "歧视", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，意思是区别对待、看不起人。"}, {"text": "起始", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是开始、起点。"}, {"text": "此事", "is_correct": false, "explanation": "c 与 q 声母不同，声调相同，意思是这件事。"}], "explanations": {"启示": "启示：使人领悟道理，即本题目标词。", "歧视": "qí（第二声）与 qǐ（第三声）声调不同，意思是区别对待、看不起人。", "起始": "shǐ（第三声）与 shì（第四声）声调不同，意思是开始、起点。", "此事": "c 与 q 声母不同，声调相同，意思是这件事。"}, "sentence_index": null, "correct_answer": "启示"}, "level_3": {"options": [{"text": "启示", "is_correct": true, "explanation": "启示：此处为“使人明白道理”义，与“要诚实”的道理相合；在所给选项中是唯一能填入的词。"}, {"text": "反驳", "is_correct": false, "explanation": "语义：反驳是驳斥别人的观点，与“要诚实”的道理相悖，句意矛盾。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：欺骗与“要诚实”的道理完全相反，句意不通。"}, {"text": "嘲笑", "is_correct": false, "explanation": "搭配：“嘲笑”不接“我们要诚实”这类劝诫性道理作宾语。"}], "explanations": {"启示": "启示：此处为“使人明白道理”义，与“要诚实”的道理相合；在所给选项中是唯一能填入的词。", "反驳": "语义：反驳是驳斥别人的观点，与“要诚实”的道理相悖，句意矛盾。", "欺骗": "语义：欺骗与“要诚实”的道理完全相反，句意不通。", "嘲笑": "搭配：“嘲笑”不接“我们要诚实”这类劝诫性道理作宾语。"}, "sentence_index": 0, "correct_answer": "启示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校启示学生明天放假。", "explanation": "这里应该用〈通知〉。启示指使人领悟道理，不用于告知放假等事项。"}, {"text": "警察启示他立刻停车。", "explanation": "这里应该用〈命令〉。启示是使人明白道理，不带强制要求的意思。"}, {"text": "老师启示他迟到了。", "explanation": "这里应该用〈提醒〉。启示指使人领悟一个道理，不用于直接指出某人做错的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23956, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "启示", "is_correct": true, "explanation": "启示：使人领悟道理，即本题目标词。"}, {"text": "气势", "is_correct": false, "explanation": "qì（第四声）与 qǐ（第三声）声调不同，意思是气势、气派。"}, {"text": "喜事", "is_correct": false, "explanation": "x 与 q 声母不同，声调相同，意思是喜庆的事。"}, {"text": "奇事", "is_correct": false, "explanation": "qí（第二声）与 qǐ（第三声）声调不同，意思是奇异的事情。"}], "explanations": {"启示": "启示：使人领悟道理，即本题目标词。", "气势": "qì（第四声）与 qǐ（第三声）声调不同，意思是气势、气派。", "喜事": "x 与 q 声母不同，声调相同，意思是喜庆的事。", "奇事": "qí（第二声）与 qǐ（第三声）声调不同，意思是奇异的事情。"}, "sentence_index": null, "correct_answer": "启示"}, "level_3": {"options": [{"text": "启示", "is_correct": true, "explanation": "启示：此处为“使人领悟道理”义，与“要谦虚”的道理相合；在所给选项中是唯一能填入的词。"}, {"text": "讽刺", "is_correct": false, "explanation": "语义：讽刺是挖苦、嘲讽，与“要谦虚”的劝导意思相反。"}, {"text": "惊吓", "is_correct": false, "explanation": "语义：惊吓是使人害怕，不能用来传达“要谦虚”这一道理。"}, {"text": "冷落", "is_correct": false, "explanation": "配价：“冷落”要求带人或事物作宾语，不能直接接“我们要谦虚”这样的道理。"}], "explanations": {"启示": "启示：此处为“使人领悟道理”义，与“要谦虚”的道理相合；在所给选项中是唯一能填入的词。", "讽刺": "语义：讽刺是挖苦、嘲讽，与“要谦虚”的劝导意思相反。", "惊吓": "语义：惊吓是使人害怕，不能用来传达“要谦虚”这一道理。", "冷落": "配价：“冷落”要求带人或事物作宾语，不能直接接“我们要谦虚”这样的道理。"}, "sentence_index": 6, "correct_answer": "启示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府启示了新政策。", "explanation": "这里应该用〈宣布〉。宣布是正式公开发布决定，启示指使人领悟道理，不用于公布政策。"}, {"text": "老师启示了他的作业。", "explanation": "这里应该用〈批改〉。批改是给作业做记号并评定，启示指使人领悟道理，不指评阅作业。"}, {"text": "校长启示了这个计划。", "explanation": "这里应该用〈批准〉。批准是同意某项计划，启示指使人领悟道理，不表示同意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事启示得我们要守信。", "corrected_sentence": "这件事启示了我们要守信。", "error_description": "错误：“启示”后的动态助词“了”误写为补语标记“得”。正确：应说“启示了我们”，“了”表示动作已经发生。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇报道启示保护环境。", "corrected_sentence": "这篇报道启示人们保护环境。", "error_description": "错误：缺少受事“人们”。“启示”后面要带受事，说明谁受到启发，应说“启示人们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db5df177-4ea5-4b7f-9975-32ce13f139fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
