INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23960, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "小鸟长大后，会飞回去喂自己的爸爸妈妈，这叫反哺。", "primary_collocate": null, "pronunciation": "fǎn bǔ", "ipa": "fan˨˩˦ pu˨˩˦", "syllable_count": 2, "sentences": [{"text": "小鸟长大后会反哺妈妈。", "target_word": "反哺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "乌鸦老了，小乌鸦会反哺它。", "target_word": "反哺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上说，有的鸟长大了会反哺父母。", "target_word": "反哺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟飞回巢里，把虫子喂给妈妈，这就是反哺。", "target_word": "反哺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说乌鸦有反哺的习惯。", "target_word": "反哺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，小鸟在反哺老鸟呢。", "target_word": "反哺", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小鸟长大了，就要学会反哺父母。", "target_word": "反哺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长大后的小鸟回来反哺，爸爸妈妈很高兴。", "target_word": "反哺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟长大后飞回巢里，反哺衰老的妈妈。", "target_word": "反哺", "complexity_tier": "T3", "furigana": "fǎn bǔ", "sentence_source": "generated"}, {"text": "老师给我们讲了乌鸦反哺的故事。", "target_word": "反哺", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "反哺了", "label": "完成体"}, {"form": "反哺过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "反哺|小鸟长大后喂养自己的父母", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be0b31d6-8b06-4c5f-af57-058217ab8309') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23960, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反哺", "is_correct": true, "explanation": "fǎn bǔ（第三声）即本词，指小鸟长大后回头喂养父母。"}, {"text": "反驳", "is_correct": false, "explanation": "反驳 fǎn bó 与 fǎn bǔ 只有第二音节声调不同（bó 第二声，bǔ 第三声），意思是驳斥。"}, {"text": "反腐", "is_correct": false, "explanation": "反腐 fǎn fǔ 与 fǎn bǔ 只有第二音节声母不同（f 与 b），意思是反对腐败。"}, {"text": "反比", "is_correct": false, "explanation": "反比 fǎn bǐ 与 fǎn bǔ 只有第二音节韵母不同（i 与 u），意思是此增彼减的数量关系。"}], "explanations": {"反哺": "fǎn bǔ（第三声）即本词，指小鸟长大后回头喂养父母。", "反驳": "反驳 fǎn bó 与 fǎn bǔ 只有第二音节声调不同（bó 第二声，bǔ 第三声），意思是驳斥。", "反腐": "反腐 fǎn fǔ 与 fǎn bǔ 只有第二音节声母不同（f 与 b），意思是反对腐败。", "反比": "反比 fǎn bǐ 与 fǎn bǔ 只有第二音节韵母不同（i 与 u），意思是此增彼减的数量关系。"}, "sentence_index": null, "correct_answer": "反哺"}, "level_3": {"options": [{"text": "反哺", "is_correct": true, "explanation": "与上下文相符：小鸟长大后回头喂养妈妈，正是“反哺”。"}, {"text": "孵化", "is_correct": false, "explanation": "搭配：“孵化”的对象是蛋，不能说“孵化妈妈”。"}, {"text": "贩卖", "is_correct": false, "explanation": "语义：“贩卖”指买进卖出，小鸟与妈妈之间不存在买卖关系。"}, {"text": "监禁", "is_correct": false, "explanation": "语义：“监禁”指强制关押，与小鸟长大后对妈妈的关爱相矛盾。"}], "explanations": {"反哺": "与上下文相符：小鸟长大后回头喂养妈妈，正是“反哺”。", "孵化": "搭配：“孵化”的对象是蛋，不能说“孵化妈妈”。", "贩卖": "语义：“贩卖”指买进卖出，小鸟与妈妈之间不存在买卖关系。", "监禁": "语义：“监禁”指强制关押，与小鸟长大后对妈妈的关爱相矛盾。"}, "sentence_index": 0, "correct_answer": "反哺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民每天反哺几十只鸡。", "explanation": "这里应该用〈喂养〉。反哺只用于子女回报父母，喂养家禽、牲畜要用喂养。"}, {"text": "母鸡反哺小鸡，把它们养大。", "explanation": "这里应该用〈哺育〉。反哺的方向是子女到父母，母鸡养育小鸡的方向相反，要用哺育。"}, {"text": "小猴子把香蕉反哺给同伴。", "explanation": "这里应该用〈分享〉。反哺指回报养育之恩，与同伴之间的分享无关，要用分享。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反哺", "is_correct": true, "explanation": "与上下文相符：小鸟长大后回头喂养父母，正是“反哺”。"}, {"text": "修补", "is_correct": false, "explanation": "语义：“修补”的对象是器物或破损之处，不能用来对待父母。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是货物，不能说“搬运父母”。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”的对象是火、烟火或情绪，不能说“点燃父母”。"}], "explanations": {"反哺": "与上下文相符：小鸟长大后回头喂养父母，正是“反哺”。", "修补": "语义：“修补”的对象是器物或破损之处，不能用来对待父母。", "搬运": "搭配：“搬运”的对象是货物，不能说“搬运父母”。", "点燃": "搭配：“点燃”的对象是火、烟火或情绪，不能说“点燃父母”。"}, "sentence_index": 6, "correct_answer": "反哺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "消防员冒着火勇敢地反哺了被困的人。", "explanation": "这里应该用〈挽救〉。反哺只用于子女回报父母，救出被困的人要用挽救。"}, {"text": "他把希望反哺在孩子身上。", "explanation": "这里应该用〈寄托〉。反哺指回报父母的养育之恩，把希望寄托在某人身上要用寄托。"}, {"text": "老师反哺了优秀的学生。", "explanation": "这里应该用〈奖励〉。反哺不用于老师对学生的奖赏，对优秀学生的鼓励要用奖励。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "长大的小鸟应该反哺在爸爸妈妈。", "corrected_sentence": "长大的小鸟应该反哺爸爸妈妈。", "error_description": "错误在于“反哺”后多加了介词“在”。“反哺”后直接接宾语，应说“反哺爸爸妈妈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小乌鸦长大后，反哺在老乌鸦。", "corrected_sentence": "小乌鸦长大后，反哺老乌鸦。", "error_description": "错误在于“反哺”与宾语之间多加了“在”。“反哺”后直接接宾语，应说“反哺老乌鸦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e99889-5d6b-4fd6-8fb5-1aefbdf942d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
