INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23962, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23962, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个人有一样的想法或感觉。", "primary_collocate": null, "pronunciation": "gòng míng", "ipa": "kʊŋ˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我和他都喜欢旧书，聊起来很有共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们对这件事有共鸣，都觉得应该帮他。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人看同一部电影，哭的地方一样，真有共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩在音乐上很有共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说的话，我心里特别有共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说他也想家，我听了马上有共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同桌对未来的想法有共鸣，所以成了好朋友。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在很多问题上都有共鸣，一起工作很轻松。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说的我也一样，我们真是有共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个陌生人在火车上聊天，发现彼此很有共鸣。", "target_word": "共鸣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共鳴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "共鸣：两个人想法或感觉一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcdeda5-d8c7-49c0-8c4a-eb7c9e6fe46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23962, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信用", "is_correct": false, "explanation": "语义：“信用”指个人的信誉，与聊天时的感受无关，句意不通。"}, {"text": "共鸣", "is_correct": true, "explanation": "共鸣：指两人想法或感受一致，与“很有”搭配，描述聊天时的默契。"}, {"text": "体力", "is_correct": false, "explanation": "搭配：“聊起来”描述的是交流时的状态，“体力”不能用来形容聊天的感觉。"}, {"text": "财产", "is_correct": false, "explanation": "语义：“财产”是经济概念，与两人喜欢旧书的交流无关。"}], "explanations": {"信用": "语义：“信用”指个人的信誉，与聊天时的感受无关，句意不通。", "共鸣": "共鸣：指两人想法或感受一致，与“很有”搭配，描述聊天时的默契。", "体力": "搭配：“聊起来”描述的是交流时的状态，“体力”不能用来形容聊天的感觉。", "财产": "语义：“财产”是经济概念，与两人喜欢旧书的交流无关。"}, "sentence_index": 0, "correct_answer": "共鸣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对这辆旧自行车很有共鸣，一直舍不得卖。", "explanation": "这里应该用〈感情〉。共鸣指人与人想法或感受一致，不能用于人对物品的依恋。"}, {"text": "我对这位新同事很有共鸣，但每次都要跟她争论。", "explanation": "这里应该用〈分歧〉。共鸣表示想法一致，与“争论”所体现的分歧矛盾。"}, {"text": "他的态度让我很有共鸣，我却当场拍桌子反对。", "explanation": "这里应该用〈反感〉。共鸣表示认同、想法一致，与“拍桌子反对”的排斥态度矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "利息", "is_correct": false, "explanation": "语义：“利息”是经济概念，与两人对未来的想法无关，句意不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“有脾气”只用来描述性格，不能用于修饰“想法”。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：“病毒”是医学概念，与未来的想法毫不相干，句意不通。"}, {"text": "共鸣", "is_correct": true, "explanation": "共鸣：指两人对未来的想法一致，与“有”搭配，符合“所以成了好朋友”的因果关系。"}], "explanations": {"利息": "语义：“利息”是经济概念，与两人对未来的想法无关，句意不通。", "脾气": "搭配：“有脾气”只用来描述性格，不能用于修饰“想法”。", "病毒": "语义：“病毒”是医学概念，与未来的想法毫不相干，句意不通。", "共鸣": "共鸣：指两人对未来的想法一致，与“有”搭配，符合“所以成了好朋友”的因果关系。"}, "sentence_index": 6, "correct_answer": "共鸣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们俩一直话不投机，彼此之间很有共鸣。", "explanation": "这里应该用〈隔阂〉。共鸣表示想法或感受一致，与“话不投机”矛盾；表示彼此疏远应用“隔阂”。"}, {"text": "他对这个方案很有共鸣，却一直在暗中破坏它。", "explanation": "这里应该用〈抵触〉。共鸣表示认同、想法一致，与“暗中破坏”的抵触态度矛盾；表示反对应用“抵触”。"}, {"text": "我对他的解释很有共鸣，觉得他是个骗子。", "explanation": "这里应该用〈意见〉。共鸣表示认同、想法一致，与“觉得他是骗子”的不满不符；表示不满应说“很有意见”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们读完这本书，心里有一只共鸣。", "corrected_sentence": "我们读完这本书，心里有一种共鸣。", "error_description": "量词错误：“只”用于动物、手等，“共鸣”是抽象名词，应用“种”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个老朋友重逢，聊起往事，彼此深深的共鸣。", "corrected_sentence": "两个老朋友重逢，聊起往事，彼此有了深深的共鸣。", "error_description": "漏掉“有了”：“彼此深深的共鸣”没有谓语动词，应为“彼此有了深深的共鸣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
