INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23966, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "飞机是一种能在天上飞的交通工具。", "primary_collocate": null, "pronunciation": "fēi jī", "ipa": "fei˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "我坐飞机去北京。", "target_word": "飞机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机几点起飞？", "target_word": "飞机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这架飞机很大。", "target_word": "飞机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他第一次坐飞机，有点儿紧张。", "target_word": "飞机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机在天上飞过。", "target_word": "飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从上海到北京坐飞机要两个小时。", "target_word": "飞机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机已经飞走了。", "target_word": "飞机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天上有一架飞机。", "target_word": "飞机", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "因为下大雾，飞机不能起飞。", "target_word": "飞机", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每个月都坐飞机出差。", "target_word": "飞机", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "架", "label": "量词"}, {"form": "飞机场", "label": "复合"}, {"form": "飞机票", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：能在天上飞的交通工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b205cd2-e5b8-488e-969b-5b81b72010f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23966, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "飞机", "is_correct": true, "explanation": "正确。“飞机”是能在天上飞的交通工具。"}, {"text": "肥鸡", "is_correct": false, "explanation": "féi（第二声）与 fēi（第一声）声调不同，意思是肥的鸡。"}, {"text": "分机", "is_correct": false, "explanation": "fēn 与 fēi 韵母不同（n 与 i），意思是电话的分机。"}, {"text": "风机", "is_correct": false, "explanation": "fēng 与 fēi 韵母不同（eng 与 i），意思是送风或通风的机器。"}], "explanations": {"飞机": "正确。“飞机”是能在天上飞的交通工具。", "肥鸡": "féi（第二声）与 fēi（第一声）声调不同，意思是肥的鸡。", "分机": "fēn 与 fēi 韵母不同（n 与 i），意思是电话的分机。", "风机": "fēng 与 fēi 韵母不同（eng 与 i），意思是送风或通风的机器。"}, "sentence_index": null, "correct_answer": "飞机"}, "level_3": {"options": [{"text": "飞机", "is_correct": true, "explanation": "正确。“坐飞机去北京”是常见的说法。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“坐”要搭配可以乘坐的交通工具，不说“坐桌子去北京”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被乘坐，句子不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不能被乘坐去北京，句子不通。"}], "explanations": {"飞机": "正确。“坐飞机去北京”是常见的说法。", "桌子": "搭配：“坐”要搭配可以乘坐的交通工具，不说“坐桌子去北京”。", "空气": "语义：空气不能被乘坐，句子不通。", "书包": "语义：书包不能被乘坐去北京，句子不通。"}, "sentence_index": 0, "correct_answer": "飞机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他第一次坐飞机在海底看鱼，有点儿紧张。", "explanation": "这里应该用〈潜水艇〉。飞机在天上飞，不能到海底，去海底要坐潜水艇。"}, {"text": "他第一次坐飞机穿过隧道，有点儿紧张。", "explanation": "这里应该用〈火车〉。火车会穿过隧道，飞机不会。"}, {"text": "他第一次坐飞机去图书馆借书，有点儿紧张。", "explanation": "这里应该用〈公交车〉。飞机只用于远距离飞行，去图书馆坐公交车即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b707e52-d132-4454-90c2-19cc87727299') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飞机", "is_correct": true, "explanation": "正确。飞机能飞，所以可以说“飞走了”。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：大楼是固定的建筑，不会飞走，句子不通。"}, {"text": "大山", "is_correct": false, "explanation": "语义：大山是固定的地形，不会飞走，句子不通。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙是固定的结构，不会飞走，句子不通。"}], "explanations": {"飞机": "正确。飞机能飞，所以可以说“飞走了”。", "大楼": "语义：大楼是固定的建筑，不会飞走，句子不通。", "大山": "语义：大山是固定的地形，不会飞走，句子不通。", "墙": "语义：墙是固定的结构，不会飞走，句子不通。"}, "sentence_index": 6, "correct_answer": "飞机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月都用飞机擦窗户。", "explanation": "这里应该用〈抹布〉。飞机是交通工具，擦窗户要用抹布，不能用飞机。"}, {"text": "飞机能把卫星送入太空。", "explanation": "这里应该用〈火箭〉。飞机飞不出大气层，不能把卫星送入太空。"}, {"text": "他坐飞机到五楼开会。", "explanation": "这里应该用〈电梯〉。飞机只能在空中飞行，到楼层要坐电梯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b707e52-d132-4454-90c2-19cc87727299') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只飞机起飞了。", "corrected_sentence": "那架飞机起飞了。", "error_description": "量词错误：飞机应用“架”，不用“只”。正确的说法是“那架飞机起飞了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b707e52-d132-4454-90c2-19cc87727299') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坐了过一次飞机。", "corrected_sentence": "他坐过一次飞机。", "error_description": "“了”与“过”不能同时用在动词后表示经历，应为“坐过一次飞机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b707e52-d132-4454-90c2-19cc87727299') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
