INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23968, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鸟类用来飞行的部位。", "primary_collocate": null, "pronunciation": "chì bǎng", "ipa": "tʂʰɻ̩˥˩ pɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "小鸟张开翅膀，飞上了蓝天。", "target_word": "翅膀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只鸟的翅膀受伤了，飞不起来。", "target_word": "翅膀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只麻雀的翅膀很短，飞不了多远。", "target_word": "翅膀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鹰展开大大的翅膀，在天上飞。", "target_word": "翅膀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸟用翅膀飞，鱼用尾巴游。", "target_word": "翅膀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸡的翅膀还很小，不能飞高。", "target_word": "翅膀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小燕子的翅膀刚长好，它正在练习飞。", "target_word": "翅膀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟妈妈用翅膀保护着小鸟。", "target_word": "翅膀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟在雨里飞，翅膀都湿了。", "target_word": "翅膀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸽子拍着翅膀，从屋顶飞走了。", "target_word": "翅膀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对翅膀", "label": "量词"}, {"form": "一双翅膀", "label": "量词"}], "register": "中性", "sense_fingerprint": "鸟或昆虫身体两侧用来飞的部位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22aa5821-43c2-4f1a-bd68-eccc7ce09b8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23968, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "翅膀", "is_correct": true, "explanation": "正确：“翅膀”是鸟用来飞行的部位，与“飞上蓝天”相符。"}, {"text": "尾巴", "is_correct": false, "explanation": "语义：尾巴不能用来飞上蓝天，与后半句矛盾。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“张开”一般搭配翅膀、嘴、伞等，不说“张开窗户”（应说“打开窗户”）。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：小鸟身上没有雨伞，不能张开雨伞飞上蓝天。"}], "explanations": {"翅膀": "正确：“翅膀”是鸟用来飞行的部位，与“飞上蓝天”相符。", "尾巴": "语义：尾巴不能用来飞上蓝天，与后半句矛盾。", "窗户": "搭配：“张开”一般搭配翅膀、嘴、伞等，不说“张开窗户”（应说“打开窗户”）。", "雨伞": "语义：小鸟身上没有雨伞，不能张开雨伞飞上蓝天。"}, "sentence_index": 0, "correct_answer": "翅膀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鱼用翅膀游，动作很快。", "explanation": "这里应该用〈尾巴〉。鱼靠尾巴和鳍游动，翅膀只属于鸟类和昆虫。"}, {"text": "小狗用翅膀跑得很快。", "explanation": "这里应该用〈腿〉。小狗靠四条腿跑，它没有翅膀。"}, {"text": "我用两只翅膀拿起了杯子。", "explanation": "这里应该用〈手〉。人用手拿东西，翅膀只属于鸟类和昆虫，人没有翅膀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翅膀", "is_correct": true, "explanation": "正确：刚长好、正在练习飞的，是小燕子的翅膀。"}, {"text": "巢", "is_correct": false, "explanation": "搭配：“长好”用于身体部位，不说巢“长好”，巢是“筑”或“搭”出来的。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不会生长，小燕子也没有课本，与“长好”不相符。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套不长在小燕子身上，“长好”说的是身体的生长。"}], "explanations": {"翅膀": "正确：刚长好、正在练习飞的，是小燕子的翅膀。", "巢": "搭配：“长好”用于身体部位，不说巢“长好”，巢是“筑”或“搭”出来的。", "课本": "语义：课本不会生长，小燕子也没有课本，与“长好”不相符。", "手套": "语义：手套不长在小燕子身上，“长好”说的是身体的生长。"}, "sentence_index": 6, "correct_answer": "翅膀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车的翅膀坏了，开不动了。", "explanation": "这里应该用〈轮子〉。汽车靠轮子走；翅膀是鸟用来飞的部位，汽车没有翅膀。"}, {"text": "小猫用翅膀抓住了老鼠。", "explanation": "这里应该用〈爪子〉。猫用爪子抓东西；猫没有翅膀。"}, {"text": "我把书放进翅膀里，去上学了。", "explanation": "这里应该用〈书包〉。书包用来装书；翅膀是鸟身上的部位，不能装书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小鸟的翅膀摔了断，只能在地上跳。", "corrected_sentence": "小鸟的翅膀摔断了，只能在地上跳。", "error_description": "“断”是结果补语，应紧跟在“摔”后面。正确是“摔断了”，错误是“摔了断”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鸟的翅膀被雨淋湿着了。", "corrected_sentence": "小鸟的翅膀被雨淋湿了。", "error_description": "“淋湿”表示结果，后面用“了”，不能再加“着”。正确是“淋湿了”，错误是“淋湿着了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23972, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吃", "is_correct": false, "explanation": "吃：指把食物咽下，与“推”没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "读：指看文字并发出声音，与“推”没有反义关系。"}, {"text": "拉", "is_correct": true, "explanation": "正确答案。拉与推方向相反，指使东西向自己这边移动。"}, {"text": "跑", "is_correct": false, "explanation": "跑：指快速移动双脚，与“推”没有反义关系。"}], "correct_answer": "拉", "explanations": {"吃": "吃：指把食物咽下，与“推”没有反义关系。", "读": "读：指看文字并发出声音，与“推”没有反义关系。", "拉": "正确答案。拉与推方向相反，指使东西向自己这边移动。", "跑": "跑：指快速移动双脚，与“推”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23972, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "喝", "is_correct": false, "explanation": "喝：指用嘴吞咽液体，与“推”没有反义关系。"}, {"text": "拉", "is_correct": true, "explanation": "正确答案。拉与推方向相反，指使东西向自己这边移动。"}, {"text": "睡", "is_correct": false, "explanation": "睡：指闭眼休息，与“推”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱：指发出有节奏的声音，与“推”没有反义关系。"}], "correct_answer": "拉", "explanations": {"喝": "喝：指用嘴吞咽液体，与“推”没有反义关系。", "拉": "正确答案。拉与推方向相反，指使东西向自己这边移动。", "睡": "睡：指闭眼休息，与“推”没有反义关系。", "唱": "唱：指发出有节奏的声音，与“推”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23972, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或身体使东西向前移动。", "primary_collocate": null, "pronunciation": "tuī", "ipa": "tʰuei̯˥", "syllable_count": 1, "sentences": [{"text": "妈妈推着婴儿车在公园里走。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用肩膀推开了那扇门。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他推着自行车走上了小山。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起推，车终于动了。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明从后面推了我一下。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在超市里，爸爸推着购物车。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把箱子往前推了一点。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶坐在轮椅上，孙子在后面推。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇门要往外推，不要拉。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她推开窗户，外面下雪了。", "target_word": "推", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推了", "label": "体标"}, {"form": "推着", "label": "体标"}, {"form": "推过", "label": "体标"}, {"form": "推推", "label": "重叠"}, {"form": "推开", "label": "复合"}], "register": "中性", "sense_fingerprint": "推：用手或身体使东西向前移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e3475a8-bec8-456e-a0b2-f4294a76f115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23972, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "腿", "is_correct": false, "explanation": "推（第一声）与腿（第三声）声调不同，腿指身体的下肢部分。"}, {"text": "推", "is_correct": true, "explanation": "正确答案。推 tuī（第一声），指用手或身体使东西向前移动。"}, {"text": "退", "is_correct": false, "explanation": "推（第一声）与退（第四声）声调不同，退指向后移动。"}, {"text": "堆", "is_correct": false, "explanation": "推与堆的声母不同（t 与 d），堆 duī 指堆积。"}], "explanations": {"腿": "推（第一声）与腿（第三声）声调不同，腿指身体的下肢部分。", "推": "正确答案。推 tuī（第一声），指用手或身体使东西向前移动。", "退": "推（第一声）与退（第四声）声调不同，退指向后移动。", "堆": "推与堆的声母不同（t 与 d），堆 duī 指堆积。"}, "sentence_index": null, "correct_answer": "推"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃着婴儿车”。"}, {"text": "推", "is_correct": true, "explanation": "正确答案。“推着婴儿车”表示妈妈用手使车向前移动。"}, {"text": "写", "is_correct": false, "explanation": "语义：写是用笔记录文字，无法表示推动婴儿车。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢弃，与妈妈推婴儿车在公园散步的语境不合。"}], "explanations": {"吃": "搭配：“吃”的宾语应是食物，不能说“吃着婴儿车”。", "推": "正确答案。“推着婴儿车”表示妈妈用手使车向前移动。", "写": "语义：写是用笔记录文字，无法表示推动婴儿车。", "扔": "语义：扔是丢弃，与妈妈推婴儿车在公园散步的语境不合。"}, "sentence_index": 0, "correct_answer": "推"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把碗筷推干净了。", "explanation": "这里应该用〈洗〉。推是使物体移动，把碗筷洗干净要用洗。"}, {"text": "他推起手，向大家挥了挥。", "explanation": "这里应该用〈举〉。推是使物体向前移动，把手抬起来要用举。"}, {"text": "他把饼干推成两半。", "explanation": "这里应该用〈掰〉。推是使物体移动，把饼干弄成两半要用掰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23972, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吹", "is_correct": false, "explanation": "推与吹的声母不同（t 与 ch），吹 chuī 指用嘴或风送出气流。"}, {"text": "催", "is_correct": false, "explanation": "推与催的声母不同（t 与 c），催 cuī 指促使对方快做。"}, {"text": "推", "is_correct": true, "explanation": "正确答案。推 tuī（第一声），指用手或身体使东西向前移动。"}, {"text": "追", "is_correct": false, "explanation": "推与追的声母不同（t 与 zh），追 zhuī 指跟在后面赶上。"}], "explanations": {"吹": "推与吹的声母不同（t 与 ch），吹 chuī 指用嘴或风送出气流。", "催": "推与催的声母不同（t 与 c），催 cuī 指促使对方快做。", "推": "正确答案。推 tuī（第一声），指用手或身体使东西向前移动。", "追": "推与追的声母不同（t 与 zh），追 zhuī 指跟在后面赶上。"}, "sentence_index": null, "correct_answer": "推"}, "level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：唱是发声歌唱，无法表示用力使箱子向前移动。"}, {"text": "读", "is_correct": false, "explanation": "语义：读是看文字，与移动箱子的动作无关。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的对象一般是食物或具体咬合物，不能说“咬箱子往前”。"}, {"text": "推", "is_correct": true, "explanation": "正确答案。“把箱子往前推”表示用力使箱子向前移动一点。"}], "explanations": {"唱": "语义：唱是发声歌唱，无法表示用力使箱子向前移动。", "读": "语义：读是看文字，与移动箱子的动作无关。", "咬": "搭配：“咬”的对象一般是食物或具体咬合物，不能说“咬箱子往前”。", "推": "正确答案。“把箱子往前推”表示用力使箱子向前移动一点。"}, "sentence_index": 6, "correct_answer": "推"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他推着一碗热汤，小心地走了过来。", "explanation": "这里应该用〈端〉。推是使物体向前移动，端着碗要用端。"}, {"text": "他弯腰推起了跌倒的老人。", "explanation": "这里应该用〈扶〉。推是使物体离开原位置，扶起跌倒的人要用扶。"}, {"text": "妈妈用力把毛巾推干了。", "explanation": "这里应该用〈拧〉。推是使物体移动，把毛巾里的水挤出来要用拧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用力把窗户推了开。", "corrected_sentence": "他用力把窗户推开了。", "error_description": "错误：“推了开”。“了”应放在复合动词“推开”之后，写作“推开了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶着推轮椅到了门口。", "corrected_sentence": "奶奶推着轮椅到了门口。", "error_description": "错误：“着推轮椅”。“着”应紧跟动词“推”之后，写作“推着轮椅”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23974, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "允许", "is_correct": true, "explanation": "正确：“允许”与“不让（不允许）”意义相反，是这一义项的反义词。"}, {"text": "劝说", "is_correct": false, "explanation": "无关：“劝说”指用言语使人改变想法，与“不让”的反义关系无关。"}, {"text": "帮助", "is_correct": false, "explanation": "无关：“帮助”指给予支持，与“不让”没有反义关系。"}, {"text": "照顾", "is_correct": false, "explanation": "无关：“照顾”指关心和料理，与“不让”没有反义关系。"}], "correct_answer": "允许", "explanations": {"允许": "正确：“允许”与“不让（不允许）”意义相反，是这一义项的反义词。", "劝说": "无关：“劝说”指用言语使人改变想法，与“不让”的反义关系无关。", "帮助": "无关：“帮助”指给予支持，与“不让”没有反义关系。", "照顾": "无关：“照顾”指关心和料理，与“不让”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23974, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "允许", "is_correct": true, "explanation": "正确：“允许”与“不让（不允许）”意义相反，是这一义项的反义词。"}, {"text": "鼓励", "is_correct": false, "explanation": "无关：“鼓励”指使人有信心去做，与“不让”没有反义关系。"}, {"text": "陪伴", "is_correct": false, "explanation": "无关：“陪伴”指和人在一起，与“不让”没有反义关系。"}, {"text": "送", "is_correct": false, "explanation": "无关：“送”指把东西交给别人，与“不让”没有反义关系。"}], "correct_answer": "允许", "explanations": {"允许": "正确：“允许”与“不让（不允许）”意义相反，是这一义项的反义词。", "鼓励": "无关：“鼓励”指使人有信心去做，与“不让”没有反义关系。", "陪伴": "无关：“陪伴”指和人在一起，与“不让”没有反义关系。", "送": "无关：“送”指把东西交给别人，与“不让”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23974, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不让就是不同意别人做一件事。", "primary_collocate": null, "pronunciation": "bú ràng", "ipa": "pu˨˦ ɻɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈不让我晚上出去玩。", "target_word": "不让", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不让我们在教室里吃东西。", "target_word": "不让", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生不让他喝酒。", "target_word": "不让", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不让我一个人去海边。", "target_word": "不让", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里不让带狗进去。", "target_word": "不让", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不让大家用手机玩游戏。", "target_word": "不让", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去，可是妈妈不让。", "target_word": "不让", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不让孩子看太多电视。", "target_word": "不让", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里不让大声说话。", "target_word": "不让", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐不让我用她的电脑。", "target_word": "不让", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不同意、不允许别人做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d56d81d-7b32-4ed2-b81f-faaa77360a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不让", "is_correct": true, "explanation": "正确：“不让”即“不允许”，与“妈妈……我晚上出去玩”的语境相合。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”表示终止，“结束我晚上出去玩”说不通。"}, {"text": "检查", "is_correct": false, "explanation": "配价：“检查”的宾语应是具体对象，不能接“我晚上出去玩”这样的事件。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”指想起过去的事，与“让我出去玩”的语境不合。"}], "explanations": {"不让": "正确：“不让”即“不允许”，与“妈妈……我晚上出去玩”的语境相合。", "结束": "语义：“结束”表示终止，“结束我晚上出去玩”说不通。", "检查": "配价：“检查”的宾语应是具体对象，不能接“我晚上出去玩”这样的事件。", "回忆": "语义：“回忆”指想起过去的事，与“让我出去玩”的语境不合。"}, "sentence_index": 0, "correct_answer": "不让"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车在斑马线上不让行人，被交警批评了。", "explanation": "这里的“不让”是“让路”的“让”，指车辆不礼让行人，不表示“不允许”。"}, {"text": "他不让认错，一直在狡辩。", "explanation": "这里应该用〈不肯〉。不让表示不允许别人做事，表示自己不愿认错时要用不肯。"}, {"text": "这件事不让忽视。", "explanation": "这里应该用〈不容〉。不让要带一个被允许做事的对象，“不……忽视”这种结构要用不容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不让", "is_correct": true, "explanation": "正确：“不让”即“不允许”，与“我想去，可是妈妈……”的转折语境相合。"}, {"text": "答应", "is_correct": false, "explanation": "语义：“可是”表示转折，“妈妈答应”与前句的“我想去”不构成转折。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“我想去，可是妈妈喜欢”前后意思不通，与转折语境不合。"}, {"text": "同意", "is_correct": false, "explanation": "语义：“可是”后应接阻碍，“妈妈同意”不构成转折，“我想去，可是妈妈同意”说不通。"}], "explanations": {"不让": "正确：“不让”即“不允许”，与“我想去，可是妈妈……”的转折语境相合。", "答应": "语义：“可是”表示转折，“妈妈答应”与前句的“我想去”不构成转折。", "喜欢": "语义：“我想去，可是妈妈喜欢”前后意思不通，与转折语境不合。", "同意": "语义：“可是”后应接阻碍，“妈妈同意”不构成转折，“我想去，可是妈妈同意”说不通。"}, "sentence_index": 6, "correct_answer": "不让"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "双方谁都不让，谈判僵持了两个小时。", "explanation": "这里的“不让”指双方都不退让、不示弱，是另一个意思，不表示“不允许”。"}, {"text": "他坐在车上，就是不让座，闭着眼睛装睡。", "explanation": "这里的“不让”是“让座”的“让”，指不把座位让给别人，不表示“不允许”。"}, {"text": "这块地他不让出，宁可空着。", "explanation": "这里的“不让”是“让出、转让”的“让”，指不把地转让给别人，不表示“不允许”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷不让得我一个人过马路。", "corrected_sentence": "爷爷不让我一个人过马路。", "error_description": "多余成分：“不让”后直接接宾语“我”，“让”后不能加助词“得”；应删去“得”，说“不让我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥被不让我骑他的自行车。", "corrected_sentence": "哥哥不让我骑他的自行车。", "error_description": "被动标记误用：“不让”是主动式，不能加“被”构成被动；应删去“被”，说“哥哥不让我骑他的自行车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b664e9ad-97d3-45f2-b78a-e8211ea03883') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23976, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "跳舞", "is_correct": false, "explanation": "跳舞：指随音乐摆动身体，与“向前走”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：指悠闲地走走，与“向前走”不构成反义。"}, {"text": "向后走", "is_correct": true, "explanation": "正确答案。“向后走”指朝相反方向行进，与“向前走”构成反义。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉：指闭眼休息，与“向前走”没有反义关系。"}], "correct_answer": "向后走", "explanations": {"跳舞": "跳舞：指随音乐摆动身体，与“向前走”没有反义关系。", "散步": "散步：指悠闲地走走，与“向前走”不构成反义。", "向后走": "正确答案。“向后走”指朝相反方向行进，与“向前走”构成反义。", "睡觉": "睡觉：指闭眼休息，与“向前走”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23976, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吃饭", "is_correct": false, "explanation": "吃饭：指进食，与“向前走”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：指用嗓音演唱，与“向前走”没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字：指用笔写出文字，与“向前走”没有反义关系。"}, {"text": "向后走", "is_correct": true, "explanation": "正确答案。“向后走”指朝相反方向行进，与“向前走”构成反义。"}], "correct_answer": "向后走", "explanations": {"吃饭": "吃饭：指进食，与“向前走”没有反义关系。", "唱歌": "唱歌：指用嗓音演唱，与“向前走”没有反义关系。", "写字": "写字：指用笔写出文字，与“向前走”没有反义关系。", "向后走": "正确答案。“向后走”指朝相反方向行进，与“向前走”构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "往前面走。", "primary_collocate": null, "pronunciation": "xiàng qián zǒu", "ipa": "ɕi̯ɑŋ˥˩ tɕʰi̯ɛn˧˥ tsou̯˨˩˦", "syllable_count": 3, "sentences": [{"text": "他向前走了两步，站在门口。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队伍开始向前走了。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿灯亮了，车和人都向前走。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着路，一直向前走着。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你向前走五米，再向左拐。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跟着我向前走。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路很陡，但他不停地向前走。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们向前走了一会儿，就看到了河。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，病人可以自己向前走了。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他闭着眼睛，伸出手向前走。", "target_word": "向前走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "向前走了", "label": "体标"}, {"form": "向前走着", "label": "体标"}, {"form": "向前走过", "label": "体标"}], "register": "中性", "sense_fingerprint": "向前走：往前面走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e3475a8-bec8-456e-a0b2-f4294a76f115') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：唱是发声歌唱，不能与“两步”搭配表示移动。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“两步”搭配，不说“吃了两步”。"}, {"text": "写", "is_correct": false, "explanation": "语义：写是用笔记录文字，与走两步站到门口的语境无关。"}, {"text": "向前走", "is_correct": true, "explanation": "正确答案。“向前走了两步”表示朝前方行进两步。"}], "explanations": {"唱": "语义：唱是发声歌唱，不能与“两步”搭配表示移动。", "吃": "搭配：“吃”不能与“两步”搭配，不说“吃了两步”。", "写": "语义：写是用笔记录文字，与走两步站到门口的语境无关。", "向前走": "正确答案。“向前走了两步”表示朝前方行进两步。"}, "sentence_index": 0, "correct_answer": "向前走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直向前走着不动，没有说话。", "explanation": "这里应该用〈站〉。“向前走”表示朝前行进，与“不动”矛盾，静止要用站。"}, {"text": "她向前走回了屋子，然后关上门。", "explanation": "这里应该用〈返回〉。“向前走”表示朝前行进，与“回屋子”的返回方向矛盾。"}, {"text": "她一边向前走，一边一直往后退。", "explanation": "这里的“向前走”是朝前方行进，与“一直往后退”方向相反，表示向后移动应改用〈倒着走〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "读书", "is_correct": false, "explanation": "搭配：“不停地读书”与“山路很陡”的语境不搭，不能描述爬坡。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是休息，与山路陡峭却坚持前进的语境相反。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞与在陡峭山路上行进的语境不符。"}, {"text": "向前走", "is_correct": true, "explanation": "正确答案。“不停地向前走”表示即使山路陡峭也持续前行。"}], "explanations": {"读书": "搭配：“不停地读书”与“山路很陡”的语境不搭，不能描述爬坡。", "睡觉": "语义：睡觉是休息，与山路陡峭却坚持前进的语境相反。", "跳舞": "语义：跳舞与在陡峭山路上行进的语境不符。", "向前走": "正确答案。“不停地向前走”表示即使山路陡峭也持续前行。"}, "sentence_index": 6, "correct_answer": "向前走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他闭着眼睛，向前走在床上，一动不动。", "explanation": "这里应该用〈躺〉。“向前走”表示行进，躺在床上是静止的，要用躺。"}, {"text": "他闭着眼睛，伸出手，却在原地向前走，一步也没挪。", "explanation": "这里应该用〈踏步〉。“向前走”表示朝前行进，原地不挪步应说“原地踏步”。"}, {"text": "他闭着眼睛，伸出手，向前走上了墙。", "explanation": "这里应该用〈爬〉。“向前走”指朝前方行进，不能表示沿墙面向上移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们一起向前走很慢，去看海。", "corrected_sentence": "孩子们一起向前走得很慢，去看海。", "error_description": "错误：“向前走很慢”。缺少补语标记“得”，应写作“向前走得很慢”，用“得”引出表示程度的补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们向前走着一百米，就到了河边。", "corrected_sentence": "他们向前走了一百米，就到了河边。", "error_description": "错误：“向前走着一百米”。“着”表示动作持续，不能接表示距离的数量短语；表示完成的动作应用“了”，写作“向前走了一百米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da070831-f616-4c04-9f21-0dd2245724fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
