INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23978, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "鸟用翅膀在空中动。", "primary_collocate": null, "pronunciation": "fēi", "ipa": "fei˥", "syllable_count": 1, "sentences": [{"text": "小鸟在天上飞。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟妈妈飞回家喂小鸟。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只大鸟飞过了山。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，鸟都飞回树上。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟还小，现在不会飞。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门一开，笼子里的鸟飞出去了。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白鸟飞得比黑鸟高。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只鸟飞到我的窗前。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天来了，鸟飞到南方去了。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟儿在湖边飞着，很好看。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飞了", "label": "体标"}, {"form": "飞着", "label": "体标"}, {"form": "飞过", "label": "体标"}, {"form": "飛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鸟用翅膀在空中动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e84b5b62-f832-4dbb-bc2a-7fd6d14aeece') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23978, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "飞", "is_correct": true, "explanation": "正确答案：飞（fēi），鸟用翅膀在空中动。"}, {"text": "肥", "is_correct": false, "explanation": "féi（第二声）与 fēi（第一声）声调不同，意思是肥。"}, {"text": "肺", "is_correct": false, "explanation": "fèi（第四声）与 fēi（第一声）声调不同，意思是肺。"}, {"text": "黑", "is_correct": false, "explanation": "hēi 与 fēi 声母不同（h 与 f），意思是黑色。"}, {"text": "匪", "is_correct": false, "explanation": "fěi（第三声）与 fēi（第一声）声调不同，意思是匪徒。"}], "explanations": {"飞": "正确答案：飞（fēi），鸟用翅膀在空中动。", "肥": "féi（第二声）与 fēi（第一声）声调不同，意思是肥。", "肺": "fèi（第四声）与 fēi（第一声）声调不同，意思是肺。", "黑": "hēi 与 fēi 声母不同（h 与 f），意思是黑色。", "匪": "fěi（第三声）与 fēi（第一声）声调不同，意思是匪徒。"}, "sentence_index": null, "correct_answer": "飞"}, "level_3": {"options": [{"text": "跑", "is_correct": false, "explanation": "语义：“跑”指用腿在地面快速移动，小鸟在天上不会跑。"}, {"text": "飞", "is_correct": true, "explanation": "正确：“飞”指鸟用翅膀在空中动，与“在天上”相符。"}, {"text": "爬", "is_correct": false, "explanation": "体貌：“爬”指手脚贴地或攀附，与小鸟在天上的飞行姿态不符。"}, {"text": "站", "is_correct": false, "explanation": "搭配：“站”指立在地面等处，不说“在天上站”。"}], "explanations": {"跑": "语义：“跑”指用腿在地面快速移动，小鸟在天上不会跑。", "飞": "正确：“飞”指鸟用翅膀在空中动，与“在天上”相符。", "爬": "体貌：“爬”指手脚贴地或攀附，与小鸟在天上的飞行姿态不符。", "站": "搭配：“站”指立在地面等处，不说“在天上站”。"}, "sentence_index": 0, "correct_answer": "飞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上在公园里飞。", "explanation": "这里应该用〈散步〉。人在公园里靠步行散步，不会用翅膀在空中动，“飞”不能用于人。"}, {"text": "乌龟在湖里飞来飞去。", "explanation": "这里应该用〈游〉。乌龟在水中靠四肢游动，不会飞，“飞”只用于会飞的动物。"}, {"text": "孩子们在操场上飞。", "explanation": "这里应该用〈跑〉。孩子在地上靠腿跑，不会在空中飞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23978, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "飞", "is_correct": true, "explanation": "正确答案：飞（fēi），鸟用翅膀在空中动。"}, {"text": "悲", "is_correct": false, "explanation": "bēi 与 fēi 声母不同（b 与 f），意思是悲伤。"}, {"text": "分", "is_correct": false, "explanation": "fēn 与 fēi 韵母不同（en 与 ei），意思是分开。"}, {"text": "沸", "is_correct": false, "explanation": "fèi（第四声）与 fēi（第一声）声调不同，意思是沸腾。"}], "explanations": {"飞": "正确答案：飞（fēi），鸟用翅膀在空中动。", "悲": "bēi 与 fēi 声母不同（b 与 f），意思是悲伤。", "分": "fēn 与 fēi 韵母不同（en 与 ei），意思是分开。", "沸": "fèi（第四声）与 fēi（第一声）声调不同，意思是沸腾。"}, "sentence_index": null, "correct_answer": "飞"}, "level_3": {"options": [{"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中游动，与白鸟在空中飞的动作不符。"}, {"text": "飞", "is_correct": true, "explanation": "正确：“飞”指鸟用翅膀在空中动，与“飞得比黑鸟高”相符。"}, {"text": "落", "is_correct": false, "explanation": "语义：“落”指向下降落，与“高”矛盾。"}, {"text": "滚", "is_correct": false, "explanation": "体貌：“滚”指翻转滚动，与白鸟的飞行姿态不符。"}], "explanations": {"游": "语义：“游”指在水中游动，与白鸟在空中飞的动作不符。", "飞": "正确：“飞”指鸟用翅膀在空中动，与“飞得比黑鸟高”相符。", "落": "语义：“落”指向下降落，与“高”矛盾。", "滚": "体貌：“滚”指翻转滚动，与白鸟的飞行姿态不符。"}, "sentence_index": 6, "correct_answer": "飞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蜗牛在墙上飞。", "explanation": "这里应该用〈爬〉。蜗牛靠腹足爬行，不会飞，“飞”只指鸟、虫等用翅膀的动作。"}, {"text": "小明每天飞去学校。", "explanation": "这里应该用〈走〉。人去学校靠步行或乘车，不是用翅膀在空中动。"}, {"text": "兔子飞到了草地的另一头。", "explanation": "这里应该用〈跳〉。兔子靠后腿跳跃，不会飞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只小鸟已经飞着远了。", "corrected_sentence": "那只小鸟已经飞远了。", "error_description": "“着”表示动作正在进行，与表示完成的“远了”冲突：应说“飞远了”，不说“飞着远了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一群大雁在天上飞得。", "corrected_sentence": "一群大雁在天上飞着。", "error_description": "“飞着”表示动作的持续状态，此处误用“得”；“得”后面必须接补语，单独用“飞得”不完整，应说“飞着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
