INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23982, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西的样子，比如圆形、方形。", "primary_collocate": null, "pronunciation": "xíng zhuàng", "ipa": "ɕiŋ˧˥ ʈʂwɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个盒子的形状很特别。", "target_word": "形状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮的形状每天都不一样。", "target_word": "形状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把纸剪成星星的形状。", "target_word": "形状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块蛋糕做成了心的形状。", "target_word": "形状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友喜欢认不同的形状。", "target_word": "形状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个杯子大小一样，形状不一样。", "target_word": "形状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云的形状像一只小狗。", "target_word": "形状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球的形状是圆的。", "target_word": "形状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶子的形状不好拿。", "target_word": "形状", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了三个形状。", "target_word": "形状", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种形状", "label": "量词"}], "register": "中性", "sense_fingerprint": "形状：物体外表的样子，如圆形、方形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce010c66-d877-4df7-8147-8f6d54c7cf13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性格", "is_correct": false, "explanation": "语义：性格是人的心理特点，盒子没有性格，句子不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人或动物的体型，不用来描述盒子。"}, {"text": "形状", "is_correct": true, "explanation": "正确：形状指物体的外观样子，“盒子的形状很特别”语义通顺。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气指性情，盒子没有脾气，不能说“很特别”的脾气。"}], "explanations": {"性格": "语义：性格是人的心理特点，盒子没有性格，句子不通。", "身材": "体貌：身材指人或动物的体型，不用来描述盒子。", "形状": "正确：形状指物体的外观样子，“盒子的形状很特别”语义通顺。", "脾气": "语义：脾气指性情，盒子没有脾气，不能说“很特别”的脾气。"}, "sentence_index": 0, "correct_answer": "形状"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的形状很漂亮，大家都喜欢她。", "explanation": "这里应该用〈外貌〉。形状指物体的外形轮廓，描述人的容貌要用外貌。"}, {"text": "他站得笔直，形状很标准。", "explanation": "这里应该用〈姿势〉。形状指物体的样子，人的站立姿态要用姿势。"}, {"text": "这个苹果的形状很甜。", "explanation": "这里应该用〈味道〉。甜不甜要用味道来说，形状指物体外表的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：味道是气味或口感，云没有可以用“像小狗”来比的味道。"}, {"text": "形状", "is_correct": true, "explanation": "正确：形状指物体的外观，“云的形状像一只小狗”是常见的比喻说法。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度指冷热程度，云的温度不能用“像一只小狗”来形容。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人或动物的高矮，不能用来形容云的样子。"}], "explanations": {"味道": "语义：味道是气味或口感，云没有可以用“像小狗”来比的味道。", "形状": "正确：形状指物体的外观，“云的形状像一只小狗”是常见的比喻说法。", "温度": "语义：温度指冷热程度，云的温度不能用“像一只小狗”来形容。", "身高": "体貌：身高指人或动物的高矮，不能用来形容云的样子。"}, "sentence_index": 6, "correct_answer": "形状"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的形状很好听。", "explanation": "这里应该用〈声音〉。歌曲好不好听要用声音来说，形状指物体的外形。"}, {"text": "今天的形状很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。天气的好坏不能用形状来形容，形状指物体的外形。"}, {"text": "这件衣服的形状很便宜。", "explanation": "这里应该用〈价格〉。价钱的高低要用价格来说，形状不能用来形容便宜与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我画了一只很特别的形状。", "corrected_sentence": "我画了一种很特别的形状。", "error_description": "量词错误：“一只形状”应为“一种形状”。形状是抽象的样子，应用量词“种”；“只”用于动物或成对的器物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块石头的形状方很。", "corrected_sentence": "这块石头的形状很方。", "error_description": "语序错误：应为「形状很方」。形容词「方」前要加程度副词「很」，「方很」的语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23984, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
