INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23984, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物体之间的相互作用，能使物体开始或停止运动，或改变运动的快慢和方向。", "primary_collocate": null, "pronunciation": "lì", "ipa": "li˥˩", "syllable_count": 1, "sentences": [{"text": "力可以让不动的东西动起来。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "推车的时候，你要用很大的力。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有力，球不会自己滚起来。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球给我们一个向下的力。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风也是一种力，能推动小船。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个力一样大，箱子就不动。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给球一个向前的力，球飞走了。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "力有大小，也有方向。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你给门的力太小，门没打开。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书放在桌上，桌子也给书一个向上的力。", "target_word": "力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重力", "label": "复合词"}, {"form": "推力", "label": "复合词"}, {"form": "阻力", "label": "复合词"}], "register": "中性", "sense_fingerprint": "使物体开始或停止运动、改变快慢或方向的作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dab81e9-4fc4-4e85-8310-7a60964d0d47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23984, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "力", "is_correct": true, "explanation": "正确：lì（第四声），意思是让东西动起来的作用。"}, {"text": "黎", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，“黎”意思是黎明。"}, {"text": "李", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，“李”意思是李子，也是姓。"}, {"text": "逆", "is_correct": false, "explanation": "nì（第四声）与 lì 声母不同（n 与 l），“逆”意思是逆向、倒着。"}, {"text": "腻", "is_correct": false, "explanation": "nì（第四声）与 lì 声母不同（n 与 l），“腻”意思是油腻。"}], "explanations": {"力": "正确：lì（第四声），意思是让东西动起来的作用。", "黎": "lí（第二声）与 lì（第四声）声调不同，“黎”意思是黎明。", "李": "lǐ（第三声）与 lì（第四声）声调不同，“李”意思是李子，也是姓。", "逆": "nì（第四声）与 lì 声母不同（n 与 l），“逆”意思是逆向、倒着。", "腻": "nì（第四声）与 lì 声母不同（n 与 l），“腻”意思是油腻。"}, "sentence_index": null, "correct_answer": "力"}, "level_3": {"options": [{"text": "力", "is_correct": true, "explanation": "正确：使静止的物体运动的作用，与“让不动的东西动起来”一致。"}, {"text": "光", "is_correct": false, "explanation": "语义：“光”是光线，不能使物体运动。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：“让……动起来”的主语应是能施加作用的事物，“墙”是静止的物体，搭配不通。"}, {"text": "书", "is_correct": false, "explanation": "语义：“书”是书本，不能让东西动起来。"}], "explanations": {"力": "正确：使静止的物体运动的作用，与“让不动的东西动起来”一致。", "光": "语义：“光”是光线，不能使物体运动。", "墙": "搭配：“让……动起来”的主语应是能施加作用的事物，“墙”是静止的物体，搭配不通。", "书": "语义：“书”是书本，不能让东西动起来。"}, "sentence_index": 0, "correct_answer": "力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的力很快。", "explanation": "这里应该用〈速度〉。“快”形容速度，力没有快慢之分。"}, {"text": "这个灯泡的力是六十瓦。", "explanation": "这里应该用〈功率〉。功率用“瓦”计量，表示做功的快慢；“力”用牛顿计量，不能用“瓦”。"}, {"text": "石头受到一只向下的力。", "explanation": "这里应该用〈个〉。力用“个”计量，“只”不用于力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23984, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "力", "is_correct": true, "explanation": "正确：lì（第四声），意思是让东西动起来的作用。"}, {"text": "离", "is_correct": false, "explanation": "lí（第二声）与 lì（第四声）声调不同，“离”意思是离开。"}, {"text": "礼", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，“礼”意思是礼物、礼节。"}, {"text": "里", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，“里”意思是里面。"}, {"text": "日", "is_correct": false, "explanation": "rì（第四声）与 lì 声母不同（r 与 l），“日”意思是太阳、日子。"}], "explanations": {"力": "正确：lì（第四声），意思是让东西动起来的作用。", "离": "lí（第二声）与 lì（第四声）声调不同，“离”意思是离开。", "礼": "lǐ（第三声）与 lì（第四声）声调不同，“礼”意思是礼物、礼节。", "里": "lǐ（第三声）与 lì（第四声）声调不同，“里”意思是里面。", "日": "rì（第四声）与 lì 声母不同（r 与 l），“日”意思是太阳、日子。"}, "sentence_index": null, "correct_answer": "力"}, "level_3": {"options": [{"text": "力", "is_correct": true, "explanation": "正确：使球运动的作用，与“球飞走了”一致。"}, {"text": "脚", "is_correct": false, "explanation": "搭配：“一脚”是踢、踹的计量说法，不说“一个向前的脚”。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”是表情，不能施加给球，使球飞走。"}, {"text": "声", "is_correct": false, "explanation": "语义：“声”指声音，不能使球飞走。"}], "explanations": {"力": "正确：使球运动的作用，与“球飞走了”一致。", "脚": "搭配：“一脚”是踢、踹的计量说法，不说“一个向前的脚”。", "笑": "语义：“笑”是表情，不能施加给球，使球飞走。", "声": "语义：“声”指声音，不能使球飞走。"}, "sentence_index": 6, "correct_answer": "力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块电池能储存很多力。", "explanation": "这里应该用〈能量〉。电池储存的是能量，力不能被储存。"}, {"text": "工作的力让他喘不过气来。", "explanation": "这里应该用〈压力〉。“压力”指工作、生活带来的心理或精神负担，“力”不能指这种负担。"}, {"text": "球受到一条向上的力。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，力用“个”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用了一只很大的力，把门推开了。", "corrected_sentence": "他用了很大的力，把门推开了。", "error_description": "“力”不能用“一只”计量（“只”用于动物等），“用力”时应说“用了很大的力”，不加量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用了一块很大的力，把球踢出去。", "corrected_sentence": "他用了很大的力，把球踢出去。", "error_description": "“力”不能用“一块”计量（“块”用于块状的东西），应说“很大的力”，不用量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd9359b-cf22-4c0e-aaa5-1714749d82b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
