INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23988, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "就是不能做一件事。", "primary_collocate": null, "pronunciation": "bú huì", "ipa": "pu˧˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我不会游泳，所以不敢下水。", "target_word": "不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚来中国，还不会说汉语。", "target_word": "不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟还小，不会自己穿衣服。", "target_word": "不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会开车，每天坐地铁上班。", "target_word": "不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不会做饭，常常在外面吃。", "target_word": "不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题我不会，你能教我吗？", "target_word": "不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷不会用手机，我来教他。", "target_word": "不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会跳舞，只会唱歌。", "target_word": "不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫不会说话，但是它很聪明。", "target_word": "不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会骑自行车，每天走路去学校。", "target_word": "不会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不会：没学过或不懂，所以不能做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c932acf-f05f-4d8d-ad7f-aaeceee4f32a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23988, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不会", "is_correct": true, "explanation": "不会：表示不懂游泳，所以不敢下水，前后因果成立。"}, {"text": "会", "is_correct": false, "explanation": "语义：「会游泳」与「所以不敢下水」的因果矛盾，句子说不通。"}, {"text": "敢", "is_correct": false, "explanation": "语义：「敢游泳」与「所以不敢下水」前后矛盾。"}, {"text": "愿意", "is_correct": false, "explanation": "搭配：「愿意」表示意愿，与「所以不敢下水」的因果不协调。"}], "explanations": {"不会": "不会：表示不懂游泳，所以不敢下水，前后因果成立。", "会": "语义：「会游泳」与「所以不敢下水」的因果矛盾，句子说不通。", "敢": "语义：「敢游泳」与「所以不敢下水」前后矛盾。", "愿意": "搭配：「愿意」表示意愿，与「所以不敢下水」的因果不协调。"}, "sentence_index": 0, "correct_answer": "不会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我不会他的名字，只好叫他同学。", "explanation": "这里应该用〈不知道〉。「不会」表示不能做某事，不清楚别人的名字要用「不知道」。"}, {"text": "我不会这位新来的老师，请你介绍一下。", "explanation": "这里应该用〈不认识〉。「不会」表示不能做某事，对人不熟悉要用「不认识」。"}, {"text": "我不会今天是星期几，你能告诉我吗？", "explanation": "这里应该用〈不知道〉。「不会」表示没学过、不能做某事，不清楚某个事实要用「不知道」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不会", "is_correct": true, "explanation": "不会：爷爷不懂用手机，所以我来教他，前后因果成立。"}, {"text": "很会", "is_correct": false, "explanation": "语义：「很会用手机」与「我来教他」矛盾，句子说不通。"}, {"text": "最会", "is_correct": false, "explanation": "搭配：「最会」多用于夸赞某人擅长某事，与「我来教他」的语境不搭。"}, {"text": "更会", "is_correct": false, "explanation": "语义：「更会用手机」与「我来教他」的因果矛盾。"}], "explanations": {"不会": "不会：爷爷不懂用手机，所以我来教他，前后因果成立。", "很会": "语义：「很会用手机」与「我来教他」矛盾，句子说不通。", "最会": "搭配：「最会」多用于夸赞某人擅长某事，与「我来教他」的语境不搭。", "更会": "语义：「更会用手机」与「我来教他」的因果矛盾。"}, "sentence_index": 6, "correct_answer": "不会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我不会他住在哪里，没法去找他。", "explanation": "这里应该用〈不知道〉。「不会」表示不能做某事，不清楚某个情况要用「不知道」。"}, {"text": "我不会那个穿红衣服的人，他是谁？", "explanation": "这里应该用〈不认识〉。「不会」表示不能做某事，对人不熟悉要用「不认识」。"}, {"text": "他昨天不会来上课，因为生病了。", "explanation": "这里应该用〈没〉。说过去没发生的事要用「没」，「不会」表示没学过、不能做某事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没不会跳舞，所以不去舞会。", "corrected_sentence": "我不会跳舞，所以不去舞会。", "error_description": "错误：“不会”本身已是否定，前面不能再加“没”，“没不会跳舞”属双重否定，不通；应删去“没”，为“我不会跳舞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈没不会开车，所以坐公交。", "corrected_sentence": "妈妈不会开车，所以坐公交。", "error_description": "错误：“不会”本身已是否定，前面不能再加“没”，“没不会开车”属双重否定，不通；应删去“没”，为“妈妈不会开车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffcd2bd-3ac7-4ca0-884e-a7900229f2d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23992, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "危险", "is_correct": true, "explanation": "反义：“安全”指没有危险，“危险”正是与之相对的意思。"}, {"text": "明亮", "is_correct": false, "explanation": "与“安全”无反义关系：“明亮”说光线或颜色，与“没有危险”不构成对立。"}, {"text": "快乐", "is_correct": false, "explanation": "与“安全”无反义关系：“快乐”说心情，与“没有危险”不构成对立。"}, {"text": "便宜", "is_correct": false, "explanation": "与“安全”无反义关系：“便宜”说价格低，与“没有危险”不构成对立。"}], "correct_answer": "危险", "explanations": {"危险": "反义：“安全”指没有危险，“危险”正是与之相对的意思。", "明亮": "与“安全”无反义关系：“明亮”说光线或颜色，与“没有危险”不构成对立。", "快乐": "与“安全”无反义关系：“快乐”说心情，与“没有危险”不构成对立。", "便宜": "与“安全”无反义关系：“便宜”说价格低，与“没有危险”不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23992, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "危险", "is_correct": true, "explanation": "反义：“安全”指没有危险，“危险”正是与之相对的意思。"}, {"text": "粗糙", "is_correct": false, "explanation": "与“安全”无反义关系：“粗糙”说表面不光滑，与“没有危险”不构成对立。"}, {"text": "轻松", "is_correct": false, "explanation": "与“安全”无反义关系：“轻松”说不费力或心情舒畅，与“没有危险”不构成对立。"}, {"text": "冷清", "is_correct": false, "explanation": "与“安全”无反义关系：“冷清”说人少、不热闹，与“没有危险”不构成对立。"}], "correct_answer": "危险", "explanations": {"危险": "反义：“安全”指没有危险，“危险”正是与之相对的意思。", "粗糙": "与“安全”无反义关系：“粗糙”说表面不光滑，与“没有危险”不构成对立。", "轻松": "与“安全”无反义关系：“轻松”说不费力或心情舒畅，与“没有危险”不构成对立。", "冷清": "与“安全”无反义关系：“冷清”说人少、不热闹，与“没有危险”不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23992, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不受伤、不危险，比如过马路要小心。", "primary_collocate": null, "pronunciation": "ān quán", "ipa": "an˥ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "过马路要看红绿灯，这样才安全。", "target_word": "安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市晚上很安全。", "target_word": "安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机比开车安全。", "target_word": "安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在家里最安全。", "target_word": "安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到家以后，给我发个短信，让我知道你安全。", "target_word": "安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的灯很亮，走起来很安全。", "target_word": "安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水太深，游泳不安全。", "target_word": "安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的食物很安全，大家可以放心吃。", "target_word": "安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都安全地回到了家。", "target_word": "安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把手机放在包里更安全。", "target_word": "安全", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不安全", "label": "否定式"}, {"form": "安全地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "形容词，指没有危险、不会受到伤害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '449b634c-ae74-4ccb-8934-b82cc0828b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热闹", "is_correct": false, "explanation": "语义：过马路看红绿灯是为了防止危险，与“热闹”说人声喧闹无关。"}, {"text": "干净", "is_correct": false, "explanation": "语义：“干净”说没有污垢，与看红绿灯能否避开危险无关。"}, {"text": "安全", "is_correct": true, "explanation": "正确：看红绿灯是为了不受伤，正好得出“安全”的结果。"}, {"text": "好看", "is_correct": false, "explanation": "语义：“好看”描写外观，不能说明过马路这样做的结果。"}], "explanations": {"热闹": "语义：过马路看红绿灯是为了防止危险，与“热闹”说人声喧闹无关。", "干净": "语义：“干净”说没有污垢，与看红绿灯能否避开危险无关。", "安全": "正确：看红绿灯是为了不受伤，正好得出“安全”的结果。", "好看": "语义：“好看”描写外观，不能说明过马路这样做的结果。"}, "sentence_index": 0, "correct_answer": "安全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的汉语说得很安全。", "explanation": "这里应该用〈流利〉。说话顺畅用流利，安全只说没有危险，不能用来形容说汉语。"}, {"text": "这幅画很安全。", "explanation": "这里应该用〈好看〉。形容画的外观用好看，安全指没有危险，不能用来形容画。"}, {"text": "这首歌的音调很安全。", "explanation": "这里应该用〈准〉。音高的准确用准，安全说的是没有危险，不能用来形容音调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结实", "is_correct": false, "explanation": "搭配：“结实”形容人的身体或物体坚固，不修饰“游泳”这类活动。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”形容颜色或外表，不用来说游泳怎么样。"}, {"text": "安全", "is_correct": true, "explanation": "正确：水太深时游泳有危险，所以“游泳不安全”与前文相符。"}, {"text": "热情", "is_correct": false, "explanation": "配价：“热情”要带“对……热情”的对象，不能直接修饰“游泳”。"}], "explanations": {"结实": "搭配：“结实”形容人的身体或物体坚固，不修饰“游泳”这类活动。", "鲜艳": "搭配：“鲜艳”形容颜色或外表，不用来说游泳怎么样。", "安全": "正确：水太深时游泳有危险，所以“游泳不安全”与前文相符。", "热情": "配价：“热情”要带“对……热情”的对象，不能直接修饰“游泳”。"}, "sentence_index": 6, "correct_answer": "安全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的心跳很安全。", "explanation": "这里应该用〈平稳〉。心跳的节奏规律用平稳，安全说的是没有危险，不能用来形容心跳。"}, {"text": "物价很安全。", "explanation": "这里应该用〈稳定〉。物价的平稳用稳定，安全说的是没有危险，不能用来描述物价。"}, {"text": "她的笑容很安全。", "explanation": "这里应该用〈甜美〉。笑容的美好用甜美，安全说的是没有危险，不能用来形容笑容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座桥没安全，大家最好别走。", "corrected_sentence": "这座桥不安全，大家最好别走。", "error_description": "错误形式：“没安全”；正确形式：“不安全”。形容词“安全”的否定要用“不”，不能用“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都安全的到了学校。", "corrected_sentence": "我们都安全地到了学校。", "error_description": "错误形式：“安全的到了”；正确形式：“安全地到了”。“安全”作状语修饰动词时要用“地”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
