INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24000, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24000, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "朝上方的方向。", "primary_collocate": null, "pronunciation": "xiàng shàng", "ipa": "ɕi̯ɑŋ˥˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他向上看了一眼。", "target_word": "向上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把手向上举起来。", "target_word": "向上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟向上飞去。", "target_word": "向上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟慢慢地向上升。", "target_word": "向上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们向上爬了很久。", "target_word": "向上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小草向上长，树也向上长。", "target_word": "向上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家向上望着天空。", "target_word": "向上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯正向上走。", "target_word": "向上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向上跳了一下。", "target_word": "向上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请向上看，那只鸟在树上。", "target_word": "向上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "朝着上方的方向做动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89628db-2a92-48c4-bb2a-aa8338e4bf66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "向上", "is_correct": true, "explanation": "正确。“他向上看了一眼”表示朝上方看。"}, {"text": "大声", "is_correct": false, "explanation": "搭配：“大声”修饰说、喊等发声动作，“看”不能大声。"}, {"text": "反复", "is_correct": false, "explanation": "语义：“反复”指多次重复，与“看了一眼”的单次动作相矛盾。"}, {"text": "连续", "is_correct": false, "explanation": "语义：“连续”指接连不断，与“一眼”只看一次相矛盾。"}], "explanations": {"向上": "正确。“他向上看了一眼”表示朝上方看。", "大声": "搭配：“大声”修饰说、喊等发声动作，“看”不能大声。", "反复": "语义：“反复”指多次重复，与“看了一眼”的单次动作相矛盾。", "连续": "语义：“连续”指接连不断，与“一眼”只看一次相矛盾。"}, "sentence_index": 0, "correct_answer": "向上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向上说了一个笑话。", "explanation": "这里应该用〈讲〉。“向上”表示朝上方的动作，说话不是位置移动，不能与“向上”搭配。"}, {"text": "船慢慢地向上沉下去了。", "explanation": "这里应该用〈向下〉。沉没是向下的运动，“向上”的方向与之相反。"}, {"text": "我向上想了很久，还是没有结果。", "explanation": "这里应该用〈仔细〉。“向上”只指朝上方的方向，不表示思考的深入，想问题应说“仔细想”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "向上", "is_correct": true, "explanation": "正确。“大家向上望着天空”表示抬头看天空。"}, {"text": "向下", "is_correct": false, "explanation": "语义：“向下”指朝下方，与“望着天空”的朝上方向相矛盾。"}, {"text": "急速", "is_correct": false, "explanation": "搭配：“急速”形容速度，不能修饰“望”。"}, {"text": "低声", "is_correct": false, "explanation": "搭配：“低声”修饰说话，不能修饰“望”。"}], "explanations": {"向上": "正确。“大家向上望着天空”表示抬头看天空。", "向下": "语义：“向下”指朝下方，与“望着天空”的朝上方向相矛盾。", "急速": "搭配：“急速”形容速度，不能修饰“望”。", "低声": "搭配：“低声”修饰说话，不能修饰“望”。"}, "sentence_index": 6, "correct_answer": "向上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那只鸟向上停在树枝上。", "explanation": "这里应该用〈飞上〉。“向上”指朝上方移动，“停在树枝上”是静止的结果，与方向词不搭。"}, {"text": "他向上横穿了马路。", "explanation": "这里应该用〈走过〉。“向上”是垂直方向，穿过马路是水平方向，二者冲突。"}, {"text": "他向上绕着操场走了一圈。", "explanation": "这里应该用〈沿着〉。“向上”是垂直方向，绕操场是水平方向，二者冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她慢慢地了向上望。", "corrected_sentence": "她慢慢地向上望。", "error_description": "错误：“了向上望”。正确：“向上望”。完成标记“了”要紧跟动词，不能放在状语“向上”之前，此处应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在山脚下向上爬的很久。", "corrected_sentence": "他们在山脚下向上爬了很久。", "error_description": "错误：“爬的很久”。正确：“爬了很久”。“的”不能用在动词后表示动作完成，这里动作已经完成，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24002, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24002, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24002, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水从上面或里面移动过去。", "primary_collocate": null, "pronunciation": "liú guò", "ipa": "ljoʊ˧˥ kuo˥˩", "syllable_count": 2, "sentences": [{"text": "河水从桥下流过。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水从窗户上流过。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一条小河从村子中间流过。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水从石头旁边流过，发出好听的声音。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温水从管子里流过，房间慢慢热了。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条大河流过三个省。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "泪水从她的脸上流过。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小溪流过草地，鱼在水里游。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，水从街道上流过。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山泉从石板上流过，水声清脆。", "target_word": "流过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流過", "label": "繁体"}, {"form": "流过了", "label": "体标"}], "register": "中性", "sense_fingerprint": "流过:水从上面或里面移动过去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcdeda5-d8c7-49c0-8c4a-eb7c9e6fe46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24002, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流过", "is_correct": true, "explanation": "“流过”表示水从桥下的空间移动通过，与“河水”和“桥下”的语境相合。"}, {"text": "游过", "is_correct": false, "explanation": "语义：“游过”指人或动物主动游水通过，河水本身不会游，与句意不符。"}, {"text": "爬过", "is_correct": false, "explanation": "语义：“爬过”指靠身体爬行，河水没有爬行的动作，不能这样说。"}, {"text": "跳过", "is_correct": false, "explanation": "配价：“跳过”需要一个跳跃的主体，且要带宾语表示越过的对象，“河水从桥下跳过”不成立。"}], "explanations": {"流过": "“流过”表示水从桥下的空间移动通过，与“河水”和“桥下”的语境相合。", "游过": "语义：“游过”指人或动物主动游水通过，河水本身不会游，与句意不符。", "爬过": "语义：“爬过”指靠身体爬行，河水没有爬行的动作，不能这样说。", "跳过": "配价：“跳过”需要一个跳跃的主体，且要带宾语表示越过的对象，“河水从桥下跳过”不成立。"}, "sentence_index": 0, "correct_answer": "流过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人流过检查口，没有出示证件。", "explanation": "这里应该用〈通过〉。“流过”指连续如水般的移动，单个的人不能这样说，应用“通过”。"}, {"text": "飞机流过山岭。", "explanation": "这里应该用〈越过〉。飞机是固体，“流过”不能用来描述飞机越过山岭。"}, {"text": "子弹流过木板。", "explanation": "这里应该用〈穿过〉。子弹是固体，“流过”多用于液体、气体，不能用来形容子弹穿过木板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流过", "is_correct": true, "explanation": "“流过”表示液体从表面移动过去，与泪水从脸上滑落的情景相合。"}, {"text": "飞过", "is_correct": false, "explanation": "语义：“飞过”指有翅膀的物体在空中移动，泪水不会飞，与句意不符。"}, {"text": "跑过", "is_correct": false, "explanation": "语义：“跑过”指人或动物快速移动，泪水不能跑，与语境不符。"}, {"text": "超过", "is_correct": false, "explanation": "搭配：“超过”表示数量或程度胜过，需要比较对象，不能表示泪水在脸上移动。"}], "explanations": {"流过": "“流过”表示液体从表面移动过去，与泪水从脸上滑落的情景相合。", "飞过": "语义：“飞过”指有翅膀的物体在空中移动，泪水不会飞，与句意不符。", "跑过": "语义：“跑过”指人或动物快速移动，泪水不能跑，与语境不符。", "超过": "搭配：“超过”表示数量或程度胜过，需要比较对象，不能表示泪水在脸上移动。"}, "sentence_index": 6, "correct_answer": "流过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他流过小河，不时回头张望。", "explanation": "这里应该用〈跨过〉。人是靠迈步跨越小河的，“流过”多用于液体或连续如水般的移动，不用来描述一个人的行动。"}, {"text": "一只鸟流过树梢。", "explanation": "这里应该用〈掠过〉。鸟是靠飞行快速经过，“流过”多用于液体或气体，不用来形容鸟的飞行。"}, {"text": "火车流过小镇。", "explanation": "这里应该用〈经过〉。火车是固体，“流过”不能用于火车经过小镇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "溪水正从小桥下面流过着。", "corrected_sentence": "溪水正从小桥下面流过。", "error_description": "错误在于“流过”后面的“着”。“流过”是动词加趋向补语，后面不能再加“着”，应去掉“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小溪每天傍晚都从草地上流过了。", "corrected_sentence": "小溪每天傍晚都从草地上流过。", "error_description": "错误在于句末的“了”。“每天傍晚”表示习惯性的重复，与“流过了”的完成语气不符，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
