INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24006, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出东西，比如造房子、造玩具。", "primary_collocate": null, "pronunciation": "zào", "ipa": "tsɑʊ˥˩", "syllable_count": 1, "sentences": [{"text": "爸爸想在院子里造一间小木屋。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会用纸造各种小玩具。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工厂每天造很多自行车。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们在沙滩上造了一座城堡。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们准备在山下造一座新房子。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们造过一艘很大的船。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司造的汽车很安全。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥想自己造一辆小车。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人用石头造了一座很长的桥。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在河上造桥，要花两年时间。", "target_word": "造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "造了", "label": "体标"}, {"form": "造过", "label": "体标"}, {"form": "制造", "label": "复合"}, {"form": "建造", "label": "复合"}], "register": "通用", "sense_fingerprint": "动手做出房子、玩具等东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27dbee67-57fb-4045-a9fe-c7c814b0d92e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24006, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "造", "is_correct": true, "explanation": "正确答案。zào，意思是做出、制作。"}, {"text": "早", "is_correct": false, "explanation": "zǎo（第三声）与 zào（第四声）声调不同，意思是早。"}, {"text": "糟", "is_correct": false, "explanation": "zāo（第一声）与 zào（第四声）声调不同，意思是糟糕。"}, {"text": "照", "is_correct": false, "explanation": "zhào 与 zào 声母不同（zh/z），意思是照亮或照片。"}, {"text": "在", "is_correct": false, "explanation": "zài 与 zào 韵母不同（ai/ao），意思是在。"}], "explanations": {"造": "正确答案。zào，意思是做出、制作。", "早": "zǎo（第三声）与 zào（第四声）声调不同，意思是早。", "糟": "zāo（第一声）与 zào（第四声）声调不同，意思是糟糕。", "照": "zhào 与 zào 声母不同（zh/z），意思是照亮或照片。", "在": "zài 与 zào 韵母不同（ai/ao），意思是在。"}, "sentence_index": null, "correct_answer": "造"}, "level_3": {"options": [{"text": "造", "is_correct": true, "explanation": "正确。“造小木屋”指动手做出房子，与“想在院子里”的语境相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”只能跟饮品搭配，不能说“喝一间小木屋”。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象是球或能被脚踢的东西，不能说“踢一间小木屋”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与“想在院子里……小木屋”的建造意图相反。"}], "explanations": {"造": "正确。“造小木屋”指动手做出房子，与“想在院子里”的语境相符。", "喝": "搭配：“喝”只能跟饮品搭配，不能说“喝一间小木屋”。", "踢": "搭配：“踢”的对象是球或能被脚踢的东西，不能说“踢一间小木屋”。", "扔": "语义：“扔”表示丢弃，与“想在院子里……小木屋”的建造意图相反。"}, "sentence_index": 0, "correct_answer": "造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在纸上造画。", "explanation": "这里应该用〈画〉。绘画要用“画”，“造”指做出具体的东西，不说“造画”。"}, {"text": "他每天放学后造作业。", "explanation": "这里应该用〈做〉。作业要说“做”，“造”指制造、建造具体的东西。"}, {"text": "他在厨房里造菜。", "explanation": "这里应该用〈炒〉。“造”指做出具体的东西，做菜要用“炒”或“做”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24006, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "造", "is_correct": true, "explanation": "正确答案。zào，意思是做出、制作。"}, {"text": "到", "is_correct": false, "explanation": "dào（第四声）与 zào 声母不同（d/z），意思是到达。"}, {"text": "澡", "is_correct": false, "explanation": "zǎo（第三声）与 zào（第四声）声调不同，意思是洗澡。"}, {"text": "罩", "is_correct": false, "explanation": "zhào（第四声）与 zào 声母不同（zh/z），意思是罩子。"}, {"text": "遭", "is_correct": false, "explanation": "zāo（第一声）与 zào（第四声）声调不同，意思是遇到。"}], "explanations": {"造": "正确答案。zào，意思是做出、制作。", "到": "dào（第四声）与 zào 声母不同（d/z），意思是到达。", "澡": "zǎo（第三声）与 zào（第四声）声调不同，意思是洗澡。", "罩": "zhào（第四声）与 zào 声母不同（zh/z），意思是罩子。", "遭": "zāo（第一声）与 zào（第四声）声调不同，意思是遇到。"}, "sentence_index": null, "correct_answer": "造"}, "level_3": {"options": [{"text": "造", "is_correct": true, "explanation": "正确。“造的汽车”指这家公司制造的车，与“很安全”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃的汽车”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发出歌声，与“汽车很安全”的语境无关。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说“写的汽车”。"}], "explanations": {"造": "正确。“造的汽车”指这家公司制造的车，与“很安全”的语境相符。", "吃": "搭配：“吃”的对象是食物，不能说“吃的汽车”。", "唱": "语义：“唱”是发出歌声，与“汽车很安全”的语境无关。", "写": "搭配：“写”的对象是文字，不能说“写的汽车”。"}, "sentence_index": 6, "correct_answer": "造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师让我们回家造日记。", "explanation": "这里应该用〈写〉。“造”用于制造具体的东西，写日记要用“写”。"}, {"text": "我们班每周造一次班会。", "explanation": "这里应该用〈召开〉。“造”指做出具体的东西，召开班会要用“召开”。"}, {"text": "妈妈每天造早饭。", "explanation": "这里应该用〈做〉。“造”指做出具体的东西，做早饭要说“做”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDE