INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哥哥想在河边造了一间小木屋。", "corrected_sentence": "哥哥想在河边造一间小木屋。", "error_description": "体标错误：“想”表示意愿，后面的“造”不能带“了”。应说“哥哥想在河边造一间小木屋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们造了过一座很大的桥。", "corrected_sentence": "他们造过一座很大的桥。", "error_description": "体标错误：“造过”已表示经历，“了”与“过”不能同时用在“造”后。应说“他们造过一座很大的桥”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
