INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24008, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "汽车、飞机等机器动起来的部分。", "primary_collocate": null, "pronunciation": "fā dòng jī", "ipa": "fa˥ tʊŋ˥˩ tɕi˥", "syllable_count": 3, "sentences": [{"text": "汽车的发动机在前面的车盖下面。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发动机一响，汽车就开走了。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘船有两台大发动机。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机把发动机关了，下车休息。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发动机太热了，要停一会儿。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修车师傅说发动机有问题。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的发动机在两边的机翼下。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学怎么修发动机。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新发动机比旧的安静多了。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小汽车的发动机比卡车的小。", "target_word": "发动机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "柴油发动机", "label": "复合"}, {"form": "汽油发动机", "label": "复合"}, {"form": "發動機", "label": "繁体"}], "register": "通用", "sense_fingerprint": "汽车飞机等机器上让它动起来的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27dbee67-57fb-4045-a9fe-c7c814b0d92e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发动机", "is_correct": true, "explanation": "发动机装在汽车前部的引擎舱里，车盖下面正是它的位置。"}, {"text": "轮胎", "is_correct": false, "explanation": "语义：轮胎装在车轮上，不在车盖下面。"}, {"text": "座椅", "is_correct": false, "explanation": "语义：座椅在车厢里，不在车头的车盖下面。"}, {"text": "后备箱", "is_correct": false, "explanation": "搭配：“后备箱”在车尾，不能和“前面的车盖下面”搭配。"}], "explanations": {"发动机": "发动机装在汽车前部的引擎舱里，车盖下面正是它的位置。", "轮胎": "语义：轮胎装在车轮上，不在车盖下面。", "座椅": "语义：座椅在车厢里，不在车头的车盖下面。", "后备箱": "搭配：“后备箱”在车尾，不能和“前面的车盖下面”搭配。"}, "sentence_index": 0, "correct_answer": "发动机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这款游戏的发动机很强，玩家都喜欢。", "explanation": "这里应该用〈引擎〉。“游戏引擎”是固定说法，发动机指汽车、飞机等实体机器。"}, {"text": "这座小岛靠风力发动机发电。", "explanation": "这里应该用〈发电机〉。发动机把燃料能量变成机械动力，发电需要的是发电机。"}, {"text": "这台电风扇的发动机转得很慢。", "explanation": "这里应该用〈马达〉。电风扇等小型电器的动力部件叫马达，发动机指汽车、飞机等机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发动机", "is_correct": true, "explanation": "发动机是飞机的动力部件，挂在两边的机翼下，符合句意。"}, {"text": "机舱", "is_correct": false, "explanation": "语义：机舱是机身中间载人的部分，不在机翼下面。"}, {"text": "尾翼", "is_correct": false, "explanation": "语义：尾翼在机身尾部，不在两边的机翼下面。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：窗户属于机身，不说“在两边的机翼下”。"}], "explanations": {"发动机": "发动机是飞机的动力部件，挂在两边的机翼下，符合句意。", "机舱": "语义：机舱是机身中间载人的部分，不在机翼下面。", "尾翼": "语义：尾翼在机身尾部，不在两边的机翼下面。", "窗户": "搭配：窗户属于机身，不说“在两边的机翼下”。"}, "sentence_index": 6, "correct_answer": "发动机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台笔记本的发动机太吵了，影响工作。", "explanation": "这里应该用〈风扇〉。笔记本的噪音和散热主要来自风扇，发动机指汽车、飞机等机器，不用于笔记本。"}, {"text": "工人们决定发动机罢工，明天停工。", "explanation": "这里应该用〈发动〉。“发动罢工”中是动词“发动”，发动机是名词，不能代替动词。"}, {"text": "这台空调的发动机坏了，不制冷。", "explanation": "这里应该用〈压缩机〉。空调制冷靠压缩机，发动机指汽车、飞机等机器的动力部分，不用于空调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "修车师傅换了一条新发动机。", "corrected_sentence": "修车师傅换了一台新发动机。", "error_description": "量词错误：“发动机”是机器，量词应用“台”。“条”只用于细长之物，不能用来数发动机。应改为“修车师傅换了一台新发动机。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "司机上车后，先打开了发动机。", "corrected_sentence": "司机上车后，先启动了发动机。", "error_description": "搭配错误：发动机要说“启动发动机”，不说“打开发动机”。“打开”用于门、盖子、电器开关等。应改为“司机上车后，先启动了发动机。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24010, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24010, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24010, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "风吹过来时，人能感觉到的一股流动的空气。", "primary_collocate": null, "pronunciation": "kōng qì liú", "ipa": "kʰʊŋ˥ tɕʰi˥˩ lioʊ̯˧˥", "syllable_count": 3, "sentences": [{"text": "打开门以后，我感到一股空气流。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风扇一开，就有空气流吹到脸上。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里有空气流，所以蜡烛一直在动。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我站在窗边，能感觉到凉凉的空气流。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有空气流，你不会觉得热。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁来的时候，会带来一阵空气流。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手摸了摸，没有感觉到空气流。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气流太大，纸都被吹到了地上。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩用手挡着脸，不想让空气流吹进眼睛。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门缝里进来一点空气流，脚觉得很冷。", "target_word": "空气流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "风吹来时能感觉到的气流", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3be047-ee05-479c-9375-1de3fabbe191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气流", "is_correct": true, "explanation": "正确：空气流指风吹来时感到的气流，“感到一股”与“打开门以后”的情境吻合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“感到”的对象是可以感知的气流，颜色只能看见，不能被感到。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“一股”不修饰“声音”，声音一般用“听到”，不用“感到一股”。"}, {"text": "阴影", "is_correct": false, "explanation": "语义：阴影是光线被遮挡形成的暗处，不能被感到，也不能说“一股阴影”。"}], "explanations": {"空气流": "正确：空气流指风吹来时感到的气流，“感到一股”与“打开门以后”的情境吻合。", "颜色": "语义：“感到”的对象是可以感知的气流，颜色只能看见，不能被感到。", "声音": "搭配：“一股”不修饰“声音”，声音一般用“听到”，不用“感到一股”。", "阴影": "语义：阴影是光线被遮挡形成的暗处，不能被感到，也不能说“一股阴影”。"}, "sentence_index": 0, "correct_answer": "空气流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "打开窗户，我闻到一股空气流。", "explanation": "这里应该用〈气味〉。空气流指空气的流动，能感到却闻不到；闻到的是气味。"}, {"text": "这座城市的空气流很干净。", "explanation": "这里应该用〈空气质量〉。空气流只指风吹过来的流动感，不表示清洁程度，不能用“干净”来形容。"}, {"text": "我在窗边感到一颗空气流。", "explanation": "这里应该用〈股〉。“颗”用于圆形小粒，空气流不是颗粒，不能用“颗”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气流", "is_correct": true, "explanation": "正确：空气流可以用手感知，“没有感觉到”与“用手摸了摸”前后呼应。"}, {"text": "汉字", "is_correct": false, "explanation": "语义：句子说的是用手感觉流动的气，“汉字”不是能这样感觉到的东西。"}, {"text": "色彩", "is_correct": false, "explanation": "语义：句中的动作是用手触摸，色彩不能被触摸。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不能被手摸到，句中的动作是触摸，影子无法被触摸。"}], "explanations": {"空气流": "正确：空气流可以用手感知，“没有感觉到”与“用手摸了摸”前后呼应。", "汉字": "语义：句子说的是用手感觉流动的气，“汉字”不是能这样感觉到的东西。", "色彩": "语义：句中的动作是用手触摸，色彩不能被触摸。", "影子": "语义：影子不能被手摸到，句中的动作是触摸，影子无法被触摸。"}, "sentence_index": 6, "correct_answer": "空气流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间的空气流有二十度。", "explanation": "这里应该用〈温度〉。空气流指流动的气，不表示温度；说多少度要用“温度”。"}, {"text": "我用手把门外的一阵空气流捏成了一团。", "explanation": "空气流是流动的感觉，无法被手捏成一团，这里不能用“空气流”描述被握住的东西。"}, {"text": "地上有很多空气流。", "explanation": "这里应该用〈垃圾〉。空气流是流动的气，不能堆在地上；地上堆积的东西要说“垃圾”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗户开着，有一只空气流进来。", "corrected_sentence": "窗户开着，有一阵空气流进来。", "error_description": "错误：“一只空气流”，量词“只”多用于动物等，不能用来计量空气流。正确：“一阵空气流”，量词“阵”表示一段时间内出现的气流，与空气流搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风扇转得很快，空气流的很大。", "corrected_sentence": "风扇转得很快，空气流很大。", "error_description": "错误：“空气流的很大”，多加了“的”。正确：“空气流很大”，形容词作谓语时不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24012, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24012, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24012, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "开飞机的人。", "primary_collocate": null, "pronunciation": "fēi xíng yuán", "ipa": "fei˥˥ ɕiŋ˧˥ yɛn˧˥", "syllable_count": 3, "sentences": [{"text": "飞行员正在检查飞机。", "target_word": "飞行员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想当飞行员。", "target_word": "飞行员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员对乘客说：“请系好安全带。”", "target_word": "飞行员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位飞行员已经飞了二十年。", "target_word": "飞行员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员坐在驾驶舱里，看着前面的天空。", "target_word": "飞行员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要成为飞行员，视力必须很好。", "target_word": "飞行员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员在起飞前要检查仪表。", "target_word": "飞行员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气不好，飞行员决定晚点儿起飞。", "target_word": "飞行员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叔叔是一名空军飞行员。", "target_word": "飞行员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员用无线电和机场联系。", "target_word": "飞行员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "女飞行员", "label": "复合"}], "register": "中性", "sense_fingerprint": "开飞机的人，职业名称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ab50cd-4340-49f3-b7d1-188a43322068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飞行员", "is_correct": true, "explanation": "飞行员：驾驶飞机的人，能够“正在检查飞机”。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：检查飞机是机组的工作，乘客不会“检查飞机”，句子说不通。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不是人，不能做“检查”的动作。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是地方，不能做“正在检查飞机”的主语。"}], "explanations": {"飞行员": "飞行员：驾驶飞机的人，能够“正在检查飞机”。", "乘客": "搭配：检查飞机是机组的工作，乘客不会“检查飞机”，句子说不通。", "面包": "语义：面包不是人，不能做“检查”的动作。", "教室": "语义：教室是地方，不能做“正在检查飞机”的主语。"}, "sentence_index": 0, "correct_answer": "飞行员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位开公交车的飞行员每天六点出门。", "explanation": "这里应该用〈司机〉。飞行员是驾驶飞机的人，驾驶公交车的人要说司机，不能叫飞行员。"}, {"text": "那位在餐厅掌勺的飞行员，已经做了二十年菜。", "explanation": "这里应该用〈厨师〉。飞行员是驾驶飞机的人，在餐厅掌勺做菜的人要说厨师。"}, {"text": "路口指挥交通的飞行员很辛苦。", "explanation": "这里应该用〈交警〉。飞行员是驾驶飞机的人，在路口指挥交通的人要说交警。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飞行员", "is_correct": true, "explanation": "飞行员：驾驶飞机的人，起飞前要检查仪表。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：“起飞”用于飞机、飞鸟，司机开的车不说“起飞”，句子说不通。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不负责检查飞机仪表，句意不通。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生不负责检查飞机仪表，句意不通。"}], "explanations": {"飞行员": "飞行员：驾驶飞机的人，起飞前要检查仪表。", "司机": "搭配：“起飞”用于飞机、飞鸟，司机开的车不说“起飞”，句子说不通。", "厨师": "语义：厨师不负责检查飞机仪表，句意不通。", "医生": "语义：医生不负责检查飞机仪表，句意不通。"}, "sentence_index": 6, "correct_answer": "飞行员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在医院里给病人看病的飞行员很有经验。", "explanation": "这里应该用〈医生〉。飞行员是驾驶飞机的人，给病人看病的人要说医生。"}, {"text": "在港口驾船出海的飞行员每天凌晨就出发。", "explanation": "这里应该用〈船员〉。飞行员是驾驶飞机的人，驾船出海的人要说船员。"}, {"text": "机场里负责检查行李的飞行员，一天要检查上千个包裹。", "explanation": "这里应该用〈安检员〉。飞行员负责驾驶飞机，检查行李、进行安全检查的人要说安检员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的邻居是一只飞行员。", "corrected_sentence": "我的邻居是一名飞行员。", "error_description": "量词错误：“飞行员”指人，应该用“名”或“位”，不能用“只”。“只”多用于动物，指人时不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他长大以后想飞行员。", "corrected_sentence": "他长大以后想当飞行员。", "error_description": "缺少动词：“想”后面直接接名词“飞行员”说不通，要加动词“当”，说“想当飞行员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24014, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24014, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24014, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让速度变慢。", "primary_collocate": null, "pronunciation": "màn xià lai", "ipa": "man˥˩ ɕja˥˩ lai", "syllable_count": 3, "sentences": [{"text": "过马路时，司机让车慢下来。", "target_word": "慢下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路很陡，你要让车慢下来。", "target_word": "慢下来", "complexity_tier": "T3", "furigana": "Shān lù hěn dǒu, nǐ yào ràng chē màn xiàlai.", "sentence_source": "generated"}, {"text": "风太大了，船长只好让船慢下来。", "target_word": "慢下来", "complexity_tier": "T3", "furigana": "Fēng tài dà le, chuánzhǎng zhǐ hǎo ràng chuán màn xiàlai.", "sentence_source": "generated"}, {"text": "老师让我们读课文时慢下来。", "target_word": "慢下来", "complexity_tier": "T3", "furigana": "Lǎoshī ràng wǒmen dú kèwén shí màn xiàlai.", "sentence_source": "generated"}, {"text": "快到家门口，他让自行车慢下来。", "target_word": "慢下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得太快，请慢下来，我听不懂。", "target_word": "慢下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到前面有人，教练让跑步的人都慢下来了。", "target_word": "慢下来", "complexity_tier": "T3", "furigana": "Kàndào qiánmiàn yǒu rén, jiàoliàn ràng pǎobù de rén dōu màn xiàlai le.", "sentence_source": "generated"}, {"text": "下雪天，司机让公共汽车慢下来，开得很小心。", "target_word": "慢下来", "complexity_tier": "T3", "furigana": "Xià xuě tiān, sījī ràng gōnggòng qìchē màn xiàlai, kāi de hěn xiǎoxīn.", "sentence_source": "generated"}, {"text": "比赛快结束时，他有意让脚步慢下来。", "target_word": "慢下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对孩子说：“吃饭别太快，慢下来。”", "target_word": "慢下来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "慢下来了", "label": "体标"}, {"form": "慢了下来", "label": "体标"}], "register": "中性", "sense_fingerprint": "使速度变慢·让人或物减速", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27dbee67-57fb-4045-a9fe-c7c814b0d92e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24014, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "慢下来", "is_correct": true, "explanation": "“让车慢下来”表示司机使车减速，与过马路时要小心的语境相合。"}, {"text": "快起来", "is_correct": false, "explanation": "语义：过马路要减速，“快起来”与句意相反。"}, {"text": "加速", "is_correct": false, "explanation": "语义：过马路时让车加速很危险，与句意矛盾。"}, {"text": "加快", "is_correct": false, "explanation": "语义：过马路要减速，“加快”与句意相反。"}], "explanations": {"慢下来": "“让车慢下来”表示司机使车减速，与过马路时要小心的语境相合。", "快起来": "语义：过马路要减速，“快起来”与句意相反。", "加速": "语义：过马路时让车加速很危险，与句意矛盾。", "加快": "语义：过马路要减速，“加快”与句意相反。"}, "sentence_index": 0, "correct_answer": "慢下来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她哭了很久，情绪终于慢下来了。", "explanation": "这里应该用〈平静下来〉。慢下来指速度或节奏变慢，说情绪安定要用〈平静下来〉。"}, {"text": "太阳下山了，天慢慢慢下来了。", "explanation": "这里应该用〈黑下来〉。慢下来指速度变慢，天色变暗要用〈黑下来〉或〈暗下来〉。"}, {"text": "这块刚出炉的铁，要等它慢下来。", "explanation": "这里应该用〈冷却下来〉。慢下来指速度变慢，铁块降温要用〈冷却下来〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "慢下来", "is_correct": true, "explanation": "看到前面有人要避让，教练让跑步的人放慢速度，与句意相合。"}, {"text": "跑起来", "is_correct": false, "explanation": "语义：前面有人应放慢速度，“跑起来”与句意相反。"}, {"text": "提速", "is_correct": false, "explanation": "语义：看到前面有人应减速，“提速”与句意相反。"}, {"text": "降下来", "is_correct": false, "explanation": "搭配：“降下来”多指温度、数量下降，用于“让人……”之后不自然。"}], "explanations": {"慢下来": "看到前面有人要避让，教练让跑步的人放慢速度，与句意相合。", "跑起来": "语义：前面有人应放慢速度，“跑起来”与句意相反。", "提速": "语义：看到前面有人应减速，“提速”与句意相反。", "降下来": "搭配：“降下来”多指温度、数量下降，用于“让人……”之后不自然。"}, "sentence_index": 6, "correct_answer": "慢下来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他摔伤后，疼痛终于慢下来了。", "explanation": "这里应该用〈减轻〉。慢下来指速度变慢，疼痛减弱要用〈减轻〉。"}, {"text": "他发烧了，体温慢下来了。", "explanation": "这里应该用〈降下来〉。慢下来指速度，说体温下降要用〈降下来〉。"}, {"text": "这场争吵过后，他的怒火渐渐慢下来了。", "explanation": "这里应该用〈消下去〉。慢下来指速度，说怒气消失要用〈消下去〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前面有施工，司机让车把慢下来。", "corrected_sentence": "前面有施工，司机让车慢下来。", "error_description": "“慢下来”是不及物动词，表示车速变慢，不能用「把」字；“让车”之后应直接说“慢下来”，“把”需删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教练看见他跑得太快，让他被慢下来。", "corrected_sentence": "教练看见他跑得太快，让他慢下来。", "error_description": "“慢下来”是不及物动词，不能用「被」字句；“让他”之后应直接说“慢下来”，“被”需删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24016, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进入", "is_correct": true, "explanation": "反义：进入指由外到内，与离开的“从某处走开”方向相反，是此义的反义词。"}, {"text": "写作", "is_correct": false, "explanation": "写作是创作文字，与离开没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "跳舞是身体动作，与离开的动作不相对。"}, {"text": "检查", "is_correct": false, "explanation": "检查是查看核对，与离开没有反义关系。"}], "correct_answer": "进入", "explanations": {"进入": "反义：进入指由外到内，与离开的“从某处走开”方向相反，是此义的反义词。", "写作": "写作是创作文字，与离开没有反义关系。", "跳舞": "跳舞是身体动作，与离开的动作不相对。", "检查": "检查是查看核对，与离开没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24016, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "留下", "is_correct": true, "explanation": "反义：留下指不再离去、继续停在原处，与离开的“走开”相对。"}, {"text": "种植", "is_correct": false, "explanation": "种植是栽种植物，与离开没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭是进食，与离开的动作不相对。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫是清理，与离开没有反义关系。"}], "correct_answer": "留下", "explanations": {"留下": "反义：留下指不再离去、继续停在原处，与离开的“走开”相对。", "种植": "种植是栽种植物，与离开没有反义关系。", "吃饭": "吃饭是进食，与离开的动作不相对。", "打扫": "打扫是清理，与离开没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24016, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个人从一个地方走掉，不再待在那里。", "primary_collocate": null, "pronunciation": "lí kāi", "ipa": "li˧˥ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "他九点离开了学校。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要离开这里。", "target_word": "离开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我下个月要离开这个城市。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈离开家去上班了。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们已经离开了饭店。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她离开教室，去了图书馆。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你什么时候离开北京？", "target_word": "离开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小王离开公司后，去了南方。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人都离开了，房间很安静。", "target_word": "离开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从没离开过自己的家乡。", "target_word": "离开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "离开了", "label": "体标（了）"}, {"form": "离开过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "人从一个地方走掉不再待在那里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c08b601-4318-47af-9aac-f60ca0c0c5ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "离开", "is_correct": true, "explanation": "“离开”指人从学校走开，与“九点”这个时间搭配自然。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：毕业要说“从学校毕业”，不能直接带学校作宾语。"}, {"text": "播种", "is_correct": false, "explanation": "语义：播种是把种子撒进土里，与离开学校无关，句意不成立。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：睡觉是离合词，不能带“学校”作宾语，“睡觉了学校”不成立。"}], "explanations": {"离开": "“离开”指人从学校走开，与“九点”这个时间搭配自然。", "毕业": "配价：毕业要说“从学校毕业”，不能直接带学校作宾语。", "播种": "语义：播种是把种子撒进土里，与离开学校无关，句意不成立。", "睡觉": "配价：睡觉是离合词，不能带“学校”作宾语，“睡觉了学校”不成立。"}, "sentence_index": 0, "correct_answer": "离开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于离开了那支笔，把它插进了笔筒。", "explanation": "这里应该用〈放下〉。离开指人从某处走开，笔要说“放下”，不说“离开”。"}, {"text": "他终于离开了那副眼镜，看清了黑板。", "explanation": "这里应该用〈摘下〉。离开指人从某处走开，眼镜要说“摘下”，不说“离开”。"}, {"text": "他终于离开了那件外套，走进了屋子。", "explanation": "这里应该用〈脱下〉。离开指人从某处走开，外套要说“脱下”，不说“离开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "离开", "is_correct": true, "explanation": "“离开”指人从北京走开，正好回答“什么时候”的问题。"}, {"text": "出生", "is_correct": false, "explanation": "配价：出生要说“出生在北京”，不能直接带北京作宾语。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步指悠闲地走，与“什么时候离开北京”的意思不符。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：打扮指装饰外表，与北京无法构成离去的意思。"}], "explanations": {"离开": "“离开”指人从北京走开，正好回答“什么时候”的问题。", "出生": "配价：出生要说“出生在北京”，不能直接带北京作宾语。", "散步": "语义：散步指悠闲地走，与“什么时候离开北京”的意思不符。", "打扮": "语义：打扮指装饰外表，与北京无法构成离去的意思。"}, "sentence_index": 6, "correct_answer": "离开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于离开了那双鞋，光着脚走进了屋子。", "explanation": "这里应该用〈脱下〉。离开指人从某处走开，鞋要说“脱下”，不说“离开”。"}, {"text": "她终于离开了那把剪刀，开始包饺子。", "explanation": "这里应该用〈放下〉。离开指人从某处走开，剪刀要说“放下”，不说“离开”。"}, {"text": "他终于离开了那本书，开始做饭。", "explanation": "这里应该用〈放下〉。离开指人从某处走开，书要说“放下”，不说“离开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸向车站离开，去了外地。", "corrected_sentence": "爸爸从车站离开，去了外地。", "error_description": "“向”表示朝向，不能引出离开的起点，应说“从车站离开”，不说“向车站离开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们从来没离开了这个岛。", "corrected_sentence": "我们从来没离开过这个岛。", "error_description": "“从来没”后面要用“过”表示经历，不能用“了”；正确应为“离开过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
