INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24018, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用东西不让别人过去或看不到。", "primary_collocate": null, "pronunciation": "dǎng zhù", "ipa": "tɑŋ˨˩˦ ʈ͡ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "前面的大树挡住了我的视线。", "target_word": "挡住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在门口，挡住了我的路。", "target_word": "挡住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你让一下，你挡住我了。", "target_word": "挡住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把一块大木板放在路中间，挡住了行人。", "target_word": "挡住", "complexity_tier": "T3", "furigana": "tā bǎ yí kuài dà mù bǎn fàng zài lù zhōng jiān, dǎng zhù le xíng rén.", "sentence_source": "generated"}, {"text": "他用手挡住了她的眼睛，不让她看见。", "target_word": "挡住", "complexity_tier": "T3", "furigana": "tā yòng shǒu dǎng zhù le tā de yǎn jing, bú ràng tā kàn jiàn.", "sentence_source": "generated"}, {"text": "她用手挡住脸，不让我拍照。", "target_word": "挡住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前面的人太高，挡住了我，我看不到电影。", "target_word": "挡住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把门挡住，不让孩子出去。", "target_word": "挡住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一块大石头挡住了山路。", "target_word": "挡住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车停在路中间，挡住了其他的车。", "target_word": "挡住", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "挡住了", "label": "体标（了）"}, {"form": "挡不住", "label": "可能补语（否定）"}, {"form": "挡得住", "label": "可能补语（肯定）"}], "register": "中性", "sense_fingerprint": "用东西遮挡或拦住，使人过不去或看不见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3be047-ee05-479c-9375-1de3fabbe191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挡住", "is_correct": true, "explanation": "正确：“挡住”指拦住视线，大树遮住了我的视线，符合句意。"}, {"text": "拍摄", "is_correct": false, "explanation": "语义：大树不能拍摄，视线也不能被拍摄。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”要带人作宾语，不能带“视线”作宾语。"}, {"text": "擦亮", "is_correct": false, "explanation": "搭配：“擦亮”多用于眼睛、镜子，“视线”不能被擦亮。"}], "explanations": {"挡住": "正确：“挡住”指拦住视线，大树遮住了我的视线，符合句意。", "拍摄": "语义：大树不能拍摄，视线也不能被拍摄。", "欢迎": "配价：“欢迎”要带人作宾语，不能带“视线”作宾语。", "擦亮": "搭配：“擦亮”多用于眼睛、镜子，“视线”不能被擦亮。"}, "sentence_index": 0, "correct_answer": "挡住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他挡住了怒气，没有发作。", "explanation": "这里应该用〈压制〉。挡住指用实物或身体拦住人或物，怒气要说“压制”。"}, {"text": "她挡住了朋友的道歉，没有说话。", "explanation": "这里应该用〈接受〉。挡住是拦住，朋友的道歉要说“接受”。"}, {"text": "我挡住了那段最艰难的日子，终于走了过来。", "explanation": "这里应该用〈熬过〉。挡住不能用于一段时间，经历困难时期要说“熬过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挡住", "is_correct": true, "explanation": "正确：前面的人太高，遮住了我的视线，所以我看不到电影。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：别人个子高不是祝贺我的理由，也解释不了“我看不到电影”。"}, {"text": "叫醒", "is_correct": false, "explanation": "语义：前面的人不能叫醒我，句中说的是视线受阻。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：前面的人打扮我，不会让我看不到电影，与句意不符。"}], "explanations": {"挡住": "正确：前面的人太高，遮住了我的视线，所以我看不到电影。", "祝贺": "语义：别人个子高不是祝贺我的理由，也解释不了“我看不到电影”。", "叫醒": "语义：前面的人不能叫醒我，句中说的是视线受阻。", "打扮": "语义：前面的人打扮我，不会让我看不到电影，与句意不符。"}, "sentence_index": 6, "correct_answer": "挡住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他挡住了那个任务，没有完成。", "explanation": "这里应该用〈完成〉。挡住是拦住具体的人或物，任务要说“完成”，不能说挡住。"}, {"text": "他挡住了自己的经历，没有讲给大家。", "explanation": "这里应该用〈讲述〉。挡住针对能被拦住的人或物，经历要说“讲述”。"}, {"text": "他挡住了学校的规定，结果被处罚了。", "explanation": "这里应该用〈遵守〉。挡住是拦住具体的人或物，规定要说“遵守”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这扇门挡不住了风。", "corrected_sentence": "这扇门挡不住风。", "error_description": "错误：“挡不住了风”，可能补语“挡不住”后面不能再加“了”。正确：“挡不住风”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他站在门口挡住着我的路。", "corrected_sentence": "他站在门口挡着我的路。", "error_description": "错误：“挡住着”，结果补语“住”与表示持续的“着”不能同时用在一个动词上。正确：“挡着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
