INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24020, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "方向就是你想要去的那一边。", "primary_collocate": null, "pronunciation": "fāng xiàng", "ipa": "faŋ˥ ɕiaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你走错方向了，学校在那边。", "target_word": "方向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道地铁站在哪个方向。", "target_word": "方向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我去医院的方向。", "target_word": "方向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他朝着那个方向跑去。", "target_word": "方向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，我在山里找不到方向。", "target_word": "方向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟都朝着同一个方向飞去。", "target_word": "方向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他指着学校的方向说：“在那儿。”", "target_word": "方向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该往这个方向走。", "target_word": "方向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机地图可以告诉你该走哪个方向。", "target_word": "方向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车改变了方向，往左边开去。", "target_word": "方向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "方向盘", "label": "复合"}, {"form": "方向感", "label": "复合"}], "register": "中性", "sense_fingerprint": "要去的那一边，东南西北等位置所指的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 小鸟 (Zipf 3.85), 朝着 (Zipf 3.9), 飞去 (Zipf 3.36)']::text[], 'ffce3848-4e7c-4ec3-885e-673579ba7e56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24020, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方向", "is_correct": true, "explanation": "方向指要去的那一边，与“走错”和“学校在那边”相合。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格是人的特点，不能说走错性格。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“走”不带颜色作宾语，不能说走错颜色。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能走错，与“学校在那边”的语境不符。"}], "explanations": {"方向": "方向指要去的那一边，与“走错”和“学校在那边”相合。", "性格": "语义：性格是人的特点，不能说走错性格。", "颜色": "搭配：“走”不带颜色作宾语，不能说走错颜色。", "声音": "语义：声音不能走错，与“学校在那边”的语境不符。"}, "sentence_index": 0, "correct_answer": "方向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "图书馆是一个很安静的方向。", "explanation": "这里应该用〈地点〉。方向指朝向，不能用来形容一个地方安静。"}, {"text": "这辆汽车的方向很快。", "explanation": "这里应该用〈速度〉。方向指朝向，不能描述快慢；说车子快慢要用速度。"}, {"text": "我家到学校的方向很远。", "explanation": "这里应该用〈距离〉。方向指朝向，不表示远近；说两地之间远不远要用距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方向", "is_correct": true, "explanation": "方向指朝向，可以用手指着，与“指着学校的……说：在那儿”相合。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是感觉到的，不能被手指着。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：学校不是可以标价的商品，不能说“学校的价格”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不是可以指着的具体事物，与句意不符。"}], "explanations": {"方向": "方向指朝向，可以用手指着，与“指着学校的……说：在那儿”相合。", "味道": "语义：味道是感觉到的，不能被手指着。", "价格": "搭配：学校不是可以标价的商品，不能说“学校的价格”。", "心情": "语义：心情不是可以指着的具体事物，与句意不符。"}, "sentence_index": 6, "correct_answer": "方向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的方向很高。", "explanation": "这里应该用〈个子〉。方向指朝向，不能用来形容人的身高，说人高要用个子。"}, {"text": "妈妈的方向很温柔。", "explanation": "这里应该用〈性格〉。方向指朝向，不能用来形容人，说人温柔要说性格温柔。"}, {"text": "这是我的方向，很好吃。", "explanation": "这里应该用〈菜〉。方向是指朝向，不是食物，说东西好吃要用菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路口有两座方向，你要往哪一个走？", "corrected_sentence": "路口有两个方向，你要往哪一个走？", "error_description": "错误：“方向”的量词用“座”，应为“个”。“座”用于山、桥、房屋等大型建筑，不能修饰方向。正确：“路口有两个方向”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都那个方向走去了。", "corrected_sentence": "大家都往那个方向走去了。", "error_description": "错误：介词“往”表示方向，不能省略，应说“往那个方向走去”。正确：“大家都往那个方向走去了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
