INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24022, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "我们头上高高的大片蓝色，有时有云和星星。", "primary_collocate": null, "pronunciation": "tiān kōng", "ipa": "tʰi̯ɛn˥ kʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "今天天空很蓝，我们去公园玩。", "target_word": "天空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天空中有几朵白云。", "target_word": "天空", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他躺在草地上看天空。", "target_word": "天空", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天黑了，天空出现了星星。", "target_word": "天空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机在天空飞得很高。", "target_word": "天空", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夕阳把天空染成了红色。", "target_word": "天空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天空灰灰的，好像要下雨。", "target_word": "天空", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢看天空里的云。", "target_word": "天空", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "烟花照亮了夜晚的天空。", "target_word": "天空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟在天空自由地飞。", "target_word": "天空", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "头上高高的大片蓝色，有云和星星", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c08b601-4318-47af-9aac-f60ca0c0c5ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24022, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天空", "is_correct": true, "explanation": "“天空”指头上高高的大片蓝色，是本词的正确答案。"}, {"text": "天宫", "is_correct": false, "explanation": "kōng 与 gōng 声母不同（k/g），天宫指神话中天上的宫殿或中国空间站，不是头上的蓝色天空。"}, {"text": "天坑", "is_correct": false, "explanation": "kōng 与 kēng 韵母不同（-ong/-eng），天坑指地质上陷落形成的大洞，不是天空。"}, {"text": "挑空", "is_correct": false, "explanation": "tiān 与 tiāo 韵母不同（-an/-ao），挑空指建筑中上下贯通的空间，不指天空。"}], "explanations": {"天空": "“天空”指头上高高的大片蓝色，是本词的正确答案。", "天宫": "kōng 与 gōng 声母不同（k/g），天宫指神话中天上的宫殿或中国空间站，不是头上的蓝色天空。", "天坑": "kōng 与 kēng 韵母不同（-ong/-eng），天坑指地质上陷落形成的大洞，不是天空。", "挑空": "tiān 与 tiāo 韵母不同（-an/-ao），挑空指建筑中上下贯通的空间，不指天空。"}, "sentence_index": null, "correct_answer": "天空"}, "level_3": {"options": [{"text": "天空", "is_correct": true, "explanation": "“天空”指头上高高的大片蓝色，正是“很蓝”所描述的对象。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是绿色的草木环境，不用“很蓝”来形容。"}, {"text": "草地", "is_correct": false, "explanation": "语义：草地是绿色的，不会说“今天草地很蓝”。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“很蓝”形容颜色，不用来描写作业。"}], "explanations": {"天空": "“天空”指头上高高的大片蓝色，正是“很蓝”所描述的对象。", "花园": "语义：花园是绿色的草木环境，不用“很蓝”来形容。", "草地": "语义：草地是绿色的，不会说“今天草地很蓝”。", "作业": "搭配：“很蓝”形容颜色，不用来描写作业。"}, "sentence_index": 0, "correct_answer": "天空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一本天空，很好看。", "explanation": "量词错误：天空的量词是“片”，“本”用于书，应说“一片天空”。"}, {"text": "最近天空很好，适合去郊游。", "explanation": "这里应该用〈天气〉。天气指冷暖晴雨等，天空是头顶的空间，不说天空很好。"}, {"text": "山上的天空很新鲜，我们深深呼吸吧。", "explanation": "这里应该用〈空气〉。新鲜形容空气，天空是头顶的空间，不说天空新鲜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": true, "explanation": "“天空”是灰色的，句中说它好像要下雨，指的正是天色。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌的颜色不会用“好像要下雨”来描述，句中说的是天色。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包的颜色与下雨无关，与句中“要下雨”的意思不符。"}, {"text": "作业本", "is_correct": false, "explanation": "搭配：“灰灰的”形容天色时，不用来描写作业本，且与“要下雨”无关。"}], "explanations": {"天空": "“天空”是灰色的，句中说它好像要下雨，指的正是天色。", "课桌": "语义：课桌的颜色不会用“好像要下雨”来描述，句中说的是天色。", "面包": "语义：面包的颜色与下雨无关，与句中“要下雨”的意思不符。", "作业本": "搭配：“灰灰的”形容天色时，不用来描写作业本，且与“要下雨”无关。"}, "sentence_index": 6, "correct_answer": "天空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座天空很大，鸟儿在里面飞。", "explanation": "量词错误：“座”用于山、楼等大型物体，天空要用“片”，不说“这座天空”。"}, {"text": "这颗天空很亮，孩子们都在看。", "explanation": "量词错误：“颗”用于星星、珠子等小圆的东西，天空要用“片”，不说“这颗天空”。"}, {"text": "这几天天空特别冷，大家都多穿了衣服。", "explanation": "这里应该用〈天气〉。天气指冷暖晴雨等，天空是头顶的空间，不说天空特别冷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看见一朵很蓝的天空。", "corrected_sentence": "我看见一片很蓝的天空。", "error_description": "量词错误：天空应用量词“片”，“朵”用于花、云等，应说“一片天空”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我喜欢看蓝色地天空。", "corrected_sentence": "我喜欢看蓝色的天空。", "error_description": "“地”放错了：修饰名词要用“的”，应说“蓝色的天空”，不说“蓝色地天空”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
