INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24032, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个东西能做的事情或对别的东西的改变。", "primary_collocate": null, "pronunciation": "zuò yòng", "ipa": "tswɔ˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种药对感冒很有作用。", "target_word": "作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的工具能发挥很大的作用。", "target_word": "作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这个小组里起着重要的作用。", "target_word": "作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多喝水对身体有很好的作用。", "target_word": "作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个按钮的作用是关灯。", "target_word": "作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机除了打电话，还有很多别的作用。", "target_word": "作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话对我起了很大的作用。", "target_word": "作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法没起作用，我们再想想。", "target_word": "作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳对植物的生长有重要作用。", "target_word": "作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这个小工具有什么作用吗？", "target_word": "作用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起作用", "label": "固定搭配"}, {"form": "发挥作用", "label": "固定搭配"}, {"form": "副作用", "label": "复合词"}], "register": "中性", "sense_fingerprint": "事物的功能或产生的影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af672a29-e1eb-4780-8f57-35ac2a0384e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24032, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "作用", "is_correct": true, "explanation": "正确答案：作用（zuò yòng），指事物能起的效果或功能。"}, {"text": "坐拥", "is_correct": false, "explanation": "zuò yōng（第一声）与 zuò yòng（第四声）声调不同，意思是拥有，如“坐拥百万”。"}, {"text": "作弄", "is_correct": false, "explanation": "nòng 与 yòng 声母不同，意思是戏弄、捉弄人。"}, {"text": "错用", "is_correct": false, "explanation": "cuò 与 zuò 声母不同，意思是用错、误用。"}], "explanations": {"作用": "正确答案：作用（zuò yòng），指事物能起的效果或功能。", "坐拥": "zuò yōng（第一声）与 zuò yòng（第四声）声调不同，意思是拥有，如“坐拥百万”。", "作弄": "nòng 与 yòng 声母不同，意思是戏弄、捉弄人。", "错用": "cuò 与 zuò 声母不同，意思是用错、误用。"}, "sentence_index": null, "correct_answer": "作用"}, "level_3": {"options": [{"text": "作用", "is_correct": true, "explanation": "正确：“对感冒很有作用”说的是药对病有效果，与语境相符。"}, {"text": "意义", "is_correct": false, "explanation": "语义：“意义”指价值或重要性，不指药物对病的效果。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”指滋味或趣味，不能用来说药对病的疗效。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“感情”指人与人之间的情谊，不能用来说药对感冒的作用。"}], "explanations": {"作用": "正确：“对感冒很有作用”说的是药对病有效果，与语境相符。", "意义": "语义：“意义”指价值或重要性，不指药物对病的效果。", "味道": "搭配：“味道”指滋味或趣味，不能用来说药对病的疗效。", "感情": "搭配：“感情”指人与人之间的情谊，不能用来说药对感冒的作用。"}, "sentence_index": 0, "correct_answer": "作用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他迟到的作用是堵车。", "explanation": "这里应该用〈原因〉。“作用”指事物或行为产生的效果或功能，说明迟到的缘由要用“原因”。"}, {"text": "这本书的作用是红色的。", "explanation": "这里应该用〈颜色〉。“作用”指事物的功能或效果，说书的外观要用“颜色”。"}, {"text": "他用作用打开了门。", "explanation": "这里应该用〈钥匙〉。“作用”是抽象的功能或效果，不是能拿在手里开门的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24032, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作用", "is_correct": true, "explanation": "正确：“起了很大的作用”指对我产生了影响，与语境相符。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“起”不能与“温度”搭配，温度不能对人起作用。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“起了很大的颜色”不成立，颜色不能用“起”来说明对人的影响。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”指外形，与老师的话对我产生的影响无关。"}], "explanations": {"作用": "正确：“起了很大的作用”指对我产生了影响，与语境相符。", "温度": "搭配：“起”不能与“温度”搭配，温度不能对人起作用。", "颜色": "搭配：“起了很大的颜色”不成立，颜色不能用“起”来说明对人的影响。", "形状": "语义：“形状”指外形，与老师的话对我产生的影响无关。"}, "sentence_index": 6, "correct_answer": "作用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的作用叫李明。", "explanation": "这里应该用〈名字〉。“作用”指事物产生的效果或功能，不能用来称呼人，说“叫什么”要用“名字”。"}, {"text": "这件事的作用是昨天。", "explanation": "这里应该用〈时间〉。“作用”不能表示事情发生的时候，说明时间要用“时间”。"}, {"text": "他住的作用在北京。", "explanation": "这里应该用〈地方〉。“作用”不指居住的场所，说住在哪里要用“地方”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方法在学习中做了很大的作用。", "corrected_sentence": "这个方法在学习中起了很大的作用。", "error_description": "「做了很大的作用」错误。“作用”与“起”搭配，表示产生效果，不能用“做”，正确为「起了很大的作用」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那种方法根本起没作用，别再用了。", "corrected_sentence": "那种方法根本没起作用，别再用了。", "error_description": "「起没作用」错误。否定词“没”应放在“起”之前，正确为「没起作用」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
