INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24034, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "坐飞机是坐一种能在天上飞的交通工具，从一个地方到另一个地方。", "primary_collocate": null, "pronunciation": "zuò fēi jī", "ipa": "tswo˥˩ feɪ˥ tɕi˥", "syllable_count": 3, "sentences": [{"text": "下个月我要坐飞机去广州。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机比坐火车快很多。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子坐飞机时，耳朵有点儿疼。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶年纪大了，很少坐飞机。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐飞机去海边玩儿。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机前，要先在机场办手续。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次出差，老板让我坐飞机去。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕高，所以不愿意坐飞机。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机去日本，要三个多小时。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟想坐飞机去看大海。", "target_word": "坐飞机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坐了飞机", "label": "体标"}, {"form": "坐过飞机", "label": "体标"}], "register": "中性", "sense_fingerprint": "乘坐会飞的交通工具·从甲地到乙地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27dbee67-57fb-4045-a9fe-c7c814b0d92e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24034, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坐飞机", "is_correct": true, "explanation": "正确：乘飞机去广州，符合“下个月要去广州”的语境。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”不能用来表示去广州的交通方式。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”与“去广州”之间没有可搭配的交通意义。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”不能表示前往广州的方式，语义不合。"}], "explanations": {"坐飞机": "正确：乘飞机去广州，符合“下个月要去广州”的语境。", "游泳": "语义：“游泳”不能用来表示去广州的交通方式。", "唱歌": "搭配：“唱歌”与“去广州”之间没有可搭配的交通意义。", "吃饭": "语义：“吃饭”不能表示前往广州的方式，语义不合。"}, "sentence_index": 0, "correct_answer": "坐飞机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是飞行员，每天坐飞机把乘客送到上海。", "explanation": "这里应该用〈开〉。飞行员驾驶飞机，要说“开飞机”；“坐飞机”指乘客乘机。"}, {"text": "这个学期的时间一下子就坐飞机过去了。", "explanation": "这里应该用〈飞逝〉。“坐飞机”指乘机出行，形容时间很快过去要说“时光飞逝”。"}, {"text": "这只小鸟坐飞机飞过了大海。", "explanation": "这里应该用〈飞〉。小鸟自己会飞，不是乘客；“坐飞机”指人乘机出行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坐飞机", "is_correct": true, "explanation": "正确：乘飞机去，符合“老板让我去出差”的语境。"}, {"text": "度假", "is_correct": false, "explanation": "语义：“度假”是休闲出行，与“这次出差”的工作性质相矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：出差时老板让人“睡觉去”不合情理，与“出差”语境矛盾。"}, {"text": "跳舞", "is_correct": false, "explanation": "搭配：“跳舞”不是出差的出行方式，不能与“老板让我……去”搭配。"}], "explanations": {"坐飞机": "正确：乘飞机去，符合“老板让我去出差”的语境。", "度假": "语义：“度假”是休闲出行，与“这次出差”的工作性质相矛盾。", "睡觉": "语义：出差时老板让人“睡觉去”不合情理，与“出差”语境矛盾。", "跳舞": "搭配：“跳舞”不是出差的出行方式，不能与“老板让我……去”搭配。"}, "sentence_index": 6, "correct_answer": "坐飞机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟弟想坐飞机当机长，去看大海。", "explanation": "这里应该用〈开〉。“坐飞机”指乘客乘机，想当机长要说“开飞机”，不说“坐”。"}, {"text": "这台冰箱昨天坐飞机去了广州。", "explanation": "这里应该用〈运〉。冰箱是物品，不能乘机；“坐飞机”的主语只能是人，运送物品要说“用飞机运”。"}, {"text": "这次比赛，他坐飞机跑得最快。", "explanation": "这里应该用〈跑〉。比赛中是人自己跑，不能乘机；“坐飞机”指乘机出行，此处应说“跑得最快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下个月我把坐飞机去上海。", "corrected_sentence": "下个月我坐飞机去上海。", "error_description": "“坐飞机”是不及物的动宾短语，不能放进「把」字句处置；“把”需删去，应说“坐飞机去上海”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天我们被坐飞机去北京。", "corrected_sentence": "明天我们坐飞机去北京。", "error_description": "“坐飞机”是主动的乘机行为，不能用「被」字句；“被”需删去，应说“坐飞机去北京”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f753777-3916-4e25-9a74-96a805513359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
