INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24036, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "努力去打败困难。", "primary_collocate": null, "pronunciation": "kè fú", "ipa": "kʰɤ˥˩ fu˧˥", "syllable_count": 2, "sentences": [{"text": "小明克服了对水的害怕。", "target_word": "克服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学游泳时，他先要克服恐惧。", "target_word": "克服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一起克服这个困难吧。", "target_word": "克服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她克服了很多困难，终于考上大学。", "target_word": "克服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，要克服坏习惯不容易。", "target_word": "克服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能克服睡觉前玩手机的习惯吗？", "target_word": "克服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想克服说话时的紧张。", "target_word": "克服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师帮我克服了学英语的困难。", "target_word": "克服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要努力，就能克服一切困难。", "target_word": "克服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹正在克服怕打针的毛病。", "target_word": "克服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "克服了", "label": "体标"}, {"form": "克服过", "label": "体标"}], "register": "中性", "sense_fingerprint": "努力打败困难、害怕或坏习惯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb9f15f3-ccce-46a2-a36a-890065503d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24036, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "克服", "is_correct": true, "explanation": "正确：句子说小明战胜了对水的害怕，“克服”与句意相符。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”的对象是快乐、生活等，不能说享受“害怕”。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”用于美好的事物，不能说欣赏“害怕”。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：“搬运”指移动物体，害怕是心理状态，无法搬运。"}], "explanations": {"克服": "正确：句子说小明战胜了对水的害怕，“克服”与句意相符。", "享受": "搭配：“享受”的对象是快乐、生活等，不能说享受“害怕”。", "欣赏": "搭配：“欣赏”用于美好的事物，不能说欣赏“害怕”。", "搬运": "语义：“搬运”指移动物体，害怕是心理状态，无法搬运。"}, "sentence_index": 0, "correct_answer": "克服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她克服了老师的表扬，心里很高兴。", "explanation": "这里应该用〈获得〉。克服针对困难或缺点，不能用于表扬这类好事。"}, {"text": "我们要克服这个机会，争取成功。", "explanation": "这里应该用〈把握〉。克服的对象是困难、缺点，不能用于机会。"}, {"text": "这位老师克服了一大批学生。", "explanation": "这里应该用〈教育〉。克服针对困难、缺点等事情，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "克服", "is_correct": true, "explanation": "正确：句子说他想战胜说话时的紧张，“克服”与句意相符。"}, {"text": "收集", "is_correct": false, "explanation": "语义：紧张是心理状态，不能被收集，“收集紧张”说不通。"}, {"text": "储存", "is_correct": false, "explanation": "语义：“储存”指保存物品或数据，不能用于紧张这种心理。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配生硬：“品尝”多指食物或滋味，句意变成细细体会紧张，而非克服。"}], "explanations": {"克服": "正确：句子说他想战胜说话时的紧张，“克服”与句意相符。", "收集": "语义：紧张是心理状态，不能被收集，“收集紧张”说不通。", "储存": "语义：“储存”指保存物品或数据，不能用于紧张这种心理。", "品尝": "搭配生硬：“品尝”多指食物或滋味，句意变成细细体会紧张，而非克服。"}, "sentence_index": 6, "correct_answer": "克服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈正在克服孩子的爱好。", "explanation": "这里应该用〈培养〉。克服用于困难或毛病，培养爱好要用培养，不能说克服爱好。"}, {"text": "他正在克服周末的假期。", "explanation": "这里应该用〈享受〉。克服针对困难或毛病，假期要用享受，不能说克服假期。"}, {"text": "老师正在克服这首诗的美。", "explanation": "这里应该用〈欣赏〉。克服针对困难或毛病，美要用欣赏，不能说克服美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直没克服了这个坏习惯。", "corrected_sentence": "他一直没克服这个坏习惯。", "error_description": "体标错误：“没”否定的动作后不能加“了”，应为“没克服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前克服了过怕黑的毛病。", "corrected_sentence": "我以前克服过怕黑的毛病。", "error_description": "体标错误：“了”与“过”不能同时用在同一动词后，应为“克服过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24038, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变快", "is_correct": true, "explanation": "变快与变慢意思相反，指速度提高，是反义关系。"}, {"text": "停下", "is_correct": false, "explanation": "停下指动作终止，与速度的快慢不构成反义关系。"}, {"text": "转弯", "is_correct": false, "explanation": "转弯指改变行进方向，与速度的快慢无关。"}, {"text": "生长", "is_correct": false, "explanation": "生长指生物长大，与速度的快慢没有反义关系。"}], "correct_answer": "变快", "explanations": {"变快": "变快与变慢意思相反，指速度提高，是反义关系。", "停下": "停下指动作终止，与速度的快慢不构成反义关系。", "转弯": "转弯指改变行进方向，与速度的快慢无关。", "生长": "生长指生物长大，与速度的快慢没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24038, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加快", "is_correct": true, "explanation": "加快与变慢意思相反，指速度提高，是反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考指动脑筋，与速度的快慢无关。"}, {"text": "保存", "is_correct": false, "explanation": "保存指留存下来，与变慢没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌指发出乐音，与速度的快慢无关。"}], "correct_answer": "加快", "explanations": {"加快": "加快与变慢意思相反，指速度提高，是反义关系。", "思考": "思考指动脑筋，与速度的快慢无关。", "保存": "保存指留存下来，与变慢没有反义关系。", "唱歌": "唱歌指发出乐音，与速度的快慢无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24038, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走或动的速度不如以前快了。", "primary_collocate": null, "pronunciation": "biàn màn", "ipa": "pi̯ɛn˥˩ man˥˩", "syllable_count": 2, "sentences": [{"text": "爬了一个小时的山，他的脚步变慢了。", "target_word": "变慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑到最后，我的速度变慢了。", "target_word": "变慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到前面有人，汽车开始变慢。", "target_word": "变慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红灯前，公共汽车的速度变慢了。", "target_word": "变慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他累了，走路的速度变慢了。", "target_word": "变慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了河边，水很浅，小船变慢了。", "target_word": "变慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前面堵车，我们的车变慢了。", "target_word": "变慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上坡太陡，他蹬得很吃力，车子变慢了。", "target_word": "变慢", "complexity_tier": "T3", "furigana": "shàng pō tài dǒu, tā dēng de hěn chīlì, chēzi biàn màn le.", "sentence_source": "generated"}, {"text": "风太大，骑车的人都变慢了。", "target_word": "变慢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他生病以后，走路变慢了。", "target_word": "变慢", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "变慢了", "label": "体标（了）"}, {"form": "变慢过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "人或物行走、移动的速度比原来慢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3be047-ee05-479c-9375-1de3fabbe191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24038, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变慢", "is_correct": true, "explanation": "正确：爬了一个小时的山，体力下降，脚步自然变慢。"}, {"text": "变快", "is_correct": false, "explanation": "语义：爬了一个小时的山之后脚步应当放缓，“变快”与疲惫的语境相反。"}, {"text": "变热", "is_correct": false, "explanation": "搭配：“变热”说的是温度，脚步不能变热。"}, {"text": "变胖", "is_correct": false, "explanation": "体貌：“变胖”描述人或动物的身体形态，不能用来说脚步。"}], "explanations": {"变慢": "正确：爬了一个小时的山，体力下降，脚步自然变慢。", "变快": "语义：爬了一个小时的山之后脚步应当放缓，“变快”与疲惫的语境相反。", "变热": "搭配：“变热”说的是温度，脚步不能变热。", "变胖": "体貌：“变胖”描述人或动物的身体形态，不能用来说脚步。"}, "sentence_index": 0, "correct_answer": "变慢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩变慢了，老师很着急。", "explanation": "这里应该用〈退步〉。变慢指速度降低，成绩下滑应说退步，不能说变慢。"}, {"text": "今年的物价变慢了，大家都很高兴。", "explanation": "这里应该用〈降低〉。变慢指速度降低，物价下降应说降低，不能说变慢。"}, {"text": "他的负担变慢了，身体也舒服多了。", "explanation": "这里应该用〈减轻〉。变慢指速度降低，负担变少应说减轻，不能说变慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变慢", "is_correct": true, "explanation": "正确：前面堵车，车速自然降下来，变慢了。"}, {"text": "加速", "is_correct": false, "explanation": "语义：前面堵车时车速应当降低，“加速”与堵车的语境相反。"}, {"text": "变晴", "is_correct": false, "explanation": "搭配：“变晴”只用于天气，车不能变晴。"}, {"text": "变瘦", "is_correct": false, "explanation": "体貌：“变瘦”描述人或动物的身材，不能用于车。"}], "explanations": {"变慢": "正确：前面堵车，车速自然降下来，变慢了。", "加速": "语义：前面堵车时车速应当降低，“加速”与堵车的语境相反。", "变晴": "搭配：“变晴”只用于天气，车不能变晴。", "变瘦": "体貌：“变瘦”描述人或动物的身材，不能用于车。"}, "sentence_index": 6, "correct_answer": "变慢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "由于大雪，航班变慢了两个小时。", "explanation": "这里应该用〈延迟〉。变慢指速度降低，航班晚点是时间推后，应说延迟，不能说变慢。"}, {"text": "这次意外让工期变慢了三天。", "explanation": "这里应该用〈延误〉。变慢指速度降低，工期推迟应说延误，不能说变慢。"}, {"text": "会议变慢了一个小时才开始。", "explanation": "这里应该用〈推迟〉。变慢指速度降低，会议时间后移应说推迟，不能说变慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上了年纪以后，他骑车的速度很变慢了。", "corrected_sentence": "上了年纪以后，他骑车的速度变慢了。", "error_description": "错误：“很变慢”，“很”是程度副词，不能直接修饰动词“变慢”。正确：“变慢了”，“变慢”前不加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下了雨以后，山路变滑了，我们的脚步变慢着。", "corrected_sentence": "下了雨以后，山路变滑了，我们的脚步变慢了。", "error_description": "错误形式是“变慢着”，正确形式是“变慢了”。“着”表示状态的持续，与表示变化已经发生的“变……了”不相容，这里应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
