INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24044, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "鸟或飞机在天空中移动。", "primary_collocate": null, "pronunciation": "fēi xíng", "ipa": "fei̯˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "飞机在天上飞行。", "target_word": "飞行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "鸟在天空飞行。", "target_word": "飞行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这架飞机在很高的地方飞行。", "target_word": "飞行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机飞行了十个小时。", "target_word": "飞行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的飞机正在海上飞行。", "target_word": "飞行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种鸟可以飞行很远。", "target_word": "飞行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机飞行的时候，我一直看着窗外。", "target_word": "飞行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里飞行的鸟很少。", "target_word": "飞行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机要飞行很长时间才能到北京。", "target_word": "飞行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只鸟能连续飞行好几天。", "target_word": "飞行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飞行了", "label": "体标"}, {"form": "飞行过", "label": "体标"}, {"form": "飞行员", "label": "复合"}], "register": "中性", "sense_fingerprint": "鸟或飞机在空中飞着前进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dd17ffc-a76b-42f7-bbad-b8985cc3d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飞行", "is_correct": true, "explanation": "正确：“飞机在天上飞行”表示飞机在空中飞。"}, {"text": "行驶", "is_correct": false, "explanation": "搭配：“行驶”用于汽车、火车等在地面移动的车辆，飞机在天上不说行驶。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳要在水里进行，飞机在天上不能游泳。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是人在地面上慢走，飞机在天上不能散步。"}], "explanations": {"飞行": "正确：“飞机在天上飞行”表示飞机在空中飞。", "行驶": "搭配：“行驶”用于汽车、火车等在地面移动的车辆，飞机在天上不说行驶。", "游泳": "语义：游泳要在水里进行，飞机在天上不能游泳。", "散步": "语义：散步是人在地面上慢走，飞机在天上不能散步。"}, "sentence_index": 0, "correct_answer": "飞行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "飞机在跑道上飞行。", "explanation": "这里应该用〈滑行〉。飞行指在空中飞，飞机在跑道上移动要说滑行。"}, {"text": "这艘轮船在海上飞行。", "explanation": "这里应该用〈航行〉。飞行只用于飞机、鸟等在空中飞，轮船在水上要说航行。"}, {"text": "鱼儿在水里飞行。", "explanation": "这里应该用〈游〉。飞行限于空中，鱼在水里要说游。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飞行", "is_correct": true, "explanation": "正确：“飞机飞行的时候”指飞机在空中飞的时候。"}, {"text": "潜水", "is_correct": false, "explanation": "语义：潜水是在水下活动，飞机在空中不能潜水，句意不通。"}, {"text": "游动", "is_correct": false, "explanation": "语义：游动多指在水中活动，飞机在空中飞的时候不能这样说。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞是人或动物的动作，飞机不能跳舞，句意荒谬。"}], "explanations": {"飞行": "正确：“飞机飞行的时候”指飞机在空中飞的时候。", "潜水": "语义：潜水是在水下活动，飞机在空中不能潜水，句意不通。", "游动": "语义：游动多指在水中活动，飞机在空中飞的时候不能这样说。", "跳舞": "语义：跳舞是人或动物的动作，飞机不能跳舞，句意荒谬。"}, "sentence_index": 6, "correct_answer": "飞行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车在公路上飞行。", "explanation": "这里应该用〈行驶〉。汽车在公路上移动要说行驶，飞行只用于空中。"}, {"text": "小船在河上飞行。", "explanation": "这里应该用〈航行〉。船在水上移动要说航行，飞行只用于空中。"}, {"text": "马在草原上飞行。", "explanation": "这里应该用〈奔跑〉。马在地面上快速跑要说奔跑，飞行只用于空中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这架飞机正在空中飞行过。", "corrected_sentence": "这架飞机正在空中飞行。", "error_description": "错误形式：“正在……飞行过”。正确形式：“正在……飞行”。“正在”表示动作正在进行，“过”表示曾经有过的经历，二者不能同用，应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飞机已经飞行着五个小时了。", "corrected_sentence": "飞机已经飞行了五个小时了。", "error_description": "错误形式：“飞行着五个小时”。正确形式：“飞行了五个小时”。动词后带时段时用“了”，不用表示持续状态的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
