INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24048, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让身体或东西不倒下。", "primary_collocate": null, "pronunciation": "bǎo chí píng héng", "ipa": "pɑʊ̯˨˩ ʈʂʰɻ̩˧˥ pʰiŋ˧˥ xɤŋ˧˥", "syllable_count": 4, "sentences": [{"text": "他站在小船上，很难保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩骑自行车时，还不会保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走在窄桥上，要张开手保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她单脚站着，努力保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰上很滑，老人很难保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书顶在头上，还能保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共汽车突然停了，我没能保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂技演员在绳子上走，还能保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐在船上别乱动，才能保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑着独轮车，很久都保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保持着平衡", "label": "体标"}], "register": "中性", "sense_fingerprint": "身体或物体站稳、不摔倒、不掉下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb9f15f3-ccce-46a2-a36a-890065503d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24048, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保持平衡", "is_correct": true, "explanation": "正确：站在小船上，身体很难站稳，所以说“很难保持平衡”。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：站在小船上不能说“游泳”，与“站”的情境不符。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“冻结”指变成固体或停止不动，不是人站稳的状态。"}, {"text": "谦让", "is_correct": false, "explanation": "语义：“谦让”指把好处让给别人，与站在船上身体站不稳无关。"}], "explanations": {"保持平衡": "正确：站在小船上，身体很难站稳，所以说“很难保持平衡”。", "游泳": "语义：站在小船上不能说“游泳”，与“站”的情境不符。", "冻结": "语义：“冻结”指变成固体或停止不动，不是人站稳的状态。", "谦让": "语义：“谦让”指把好处让给别人，与站在船上身体站不稳无关。"}, "sentence_index": 0, "correct_answer": "保持平衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盒饼干要保持平衡，放久了就不好吃。", "explanation": "这里应该用〈保持新鲜〉。保持平衡指让身体或东西不倒下；饼干的状态要说保持新鲜。"}, {"text": "排队的时候，大家要保持平衡，不能插队。", "explanation": "这里应该用〈保持秩序〉。保持平衡指让身体或东西不倒下；排队时的状态要说保持秩序。"}, {"text": "这份文件要保持平衡，不能让别人看到。", "explanation": "这里应该用〈保持机密〉。保持平衡指让身体或东西不倒下；文件不外泄要说保持机密。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保持平衡", "is_correct": true, "explanation": "正确：公共汽车突然停，人会摔倒，所以说“没能保持平衡”。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：公交车突然停，与“唱歌”无关，不是没能做的事。"}, {"text": "写字", "is_correct": false, "explanation": "语义：车突然停下，人没能“写字”与情境不符。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：车突然停下时人会站不稳，“翻译”与这个情境无关。"}], "explanations": {"保持平衡": "正确：公共汽车突然停，人会摔倒，所以说“没能保持平衡”。", "唱歌": "语义：公交车突然停，与“唱歌”无关，不是没能做的事。", "写字": "语义：车突然停下，人没能“写字”与情境不符。", "翻译": "语义：车突然停下时人会站不稳，“翻译”与这个情境无关。"}, "sentence_index": 6, "correct_answer": "保持平衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间要保持平衡，每天都要打扫。", "explanation": "这里应该用〈保持整洁〉。保持平衡指让身体或东西不倒下；房间干净要说保持整洁。"}, {"text": "这份合同要保持平衡，不能过期。", "explanation": "这里应该用〈保持有效〉。保持平衡指让身体或东西不倒下；合同仍然生效要说保持有效。"}, {"text": "学校要保持平衡，不能出事。", "explanation": "这里应该用〈保持安全〉。保持平衡指让身体或东西不倒下；学校平安无事要说保持安全。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他张开双手，才能保持平衡着。", "corrected_sentence": "他张开双手，才能保持平衡。", "error_description": "“着”放错位置：“平衡”后面不能加“着”，应说“才能保持平衡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把重心压低，才能了保持平衡。", "corrected_sentence": "他把重心压低，才能保持平衡。", "error_description": "“了”放错位置：“了”不能放在“才能”和“保持”之间，应说“才能保持平衡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
