INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24050, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "知道一件事情是什么意思。", "primary_collocate": null, "pronunciation": "dǒng", "ipa": "tʊŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个词是什么意思，你懂吗？", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说的话，我都懂了。", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说得太快，我不懂他的意思。", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这句话我懂，可是我不会说。", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你懂我的意思吗？", "target_word": "懂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个标志是什么意思，小孩子不懂。", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外国人不懂这个笑话，所以没有笑。", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不懂这个字，请你教教我。", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她懂了我的话，就点了点头。", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你再说一遍，我还是不懂。", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "懂了", "label": "体标"}, {"form": "懂得", "label": "复合"}, {"form": "不懂", "label": "否定"}], "register": "中性", "sense_fingerprint": "懂：知道话语、文字或事情是什么意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '772fca80-e265-4879-9a3c-3f993f58a8df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24050, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "懂", "is_correct": true, "explanation": "正确：懂（dǒng，第三声），意思是知道、明白。"}, {"text": "统", "is_correct": false, "explanation": "声母不同：tǒng 的声母是 t，dǒng 的声母是 d，此处意思是统一、统计。"}, {"text": "动", "is_correct": false, "explanation": "dòng（第四声）与 dǒng（第三声）声调不同，意思是动作、动弹。"}, {"text": "东", "is_correct": false, "explanation": "dōng（第一声）与 dǒng（第三声）声调不同，意思是东边。"}], "explanations": {"懂": "正确：懂（dǒng，第三声），意思是知道、明白。", "统": "声母不同：tǒng 的声母是 t，dǒng 的声母是 d，此处意思是统一、统计。", "动": "dòng（第四声）与 dǒng（第三声）声调不同，意思是动作、动弹。", "东": "dōng（第一声）与 dǒng（第三声）声调不同，意思是东边。"}, "sentence_index": null, "correct_answer": "懂"}, "level_3": {"options": [{"text": "懂", "is_correct": true, "explanation": "正确：“懂”表示理解词语的意思，与“这个词是什么意思”相呼应。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物，不能说穿词语的意思。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”与理解词义无关，句子问的是对方能否理解。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能用来询问对方是否理解词义。"}], "explanations": {"懂": "正确：“懂”表示理解词语的意思，与“这个词是什么意思”相呼应。", "穿": "搭配：“穿”的对象是衣物，不能说穿词语的意思。", "买": "语义：“买”与理解词义无关，句子问的是对方能否理解。", "睡": "配价：“睡”是不及物动词，不能用来询问对方是否理解词义。"}, "sentence_index": 0, "correct_answer": "懂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在隔壁懂了钢琴的声音。", "explanation": "这里应该用〈听见〉。懂指理解意思，听到声音要用听见。"}, {"text": "我懂昨天是星期几。", "explanation": "这里应该用〈知道〉。懂着重理解意思和道理，说具体的事实或日期时用知道。"}, {"text": "他懂了一张去北京的车票。", "explanation": "这里应该用〈买〉。懂指理解意思，买车票要用买，不能说懂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24050, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "懂", "is_correct": true, "explanation": "正确：懂（dǒng，第三声），意思是知道、明白。"}, {"text": "桶", "is_correct": false, "explanation": "声母不同：tǒng 的声母是 t，dǒng 的声母是 d，此处意思是水桶。"}, {"text": "洞", "is_correct": false, "explanation": "dòng（第四声）与 dǒng（第三声）声调不同，意思是洞穴、孔。"}, {"text": "冬", "is_correct": false, "explanation": "dōng（第一声）与 dǒng（第三声）声调不同，意思是冬天。"}], "explanations": {"懂": "正确：懂（dǒng，第三声），意思是知道、明白。", "桶": "声母不同：tǒng 的声母是 t，dǒng 的声母是 d，此处意思是水桶。", "洞": "dòng（第四声）与 dǒng（第三声）声调不同，意思是洞穴、孔。", "冬": "dōng（第一声）与 dǒng（第三声）声调不同，意思是冬天。"}, "sentence_index": null, "correct_answer": "懂"}, "level_3": {"options": [{"text": "懂", "is_correct": true, "explanation": "正确：“懂”表示不理解笑话，所以没有笑，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃笑话。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能说喝笑话。"}, {"text": "逛", "is_correct": false, "explanation": "语义：“逛”表示闲走，与“所以没有笑”的因果关系不符。"}], "explanations": {"懂": "正确：“懂”表示不理解笑话，所以没有笑，句意通顺。", "吃": "搭配：“吃”的对象是食物，不能说吃笑话。", "喝": "搭配：“喝”的对象是饮品，不能说喝笑话。", "逛": "语义：“逛”表示闲走，与“所以没有笑”的因果关系不符。"}, "sentence_index": 6, "correct_answer": "懂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我懂这位新邻居，他昨天刚搬来。", "explanation": "这里应该用〈认识〉。懂指明白意思或道理，初次与人相识要用认识。"}, {"text": "他一进门，我就懂出他不高兴了。", "explanation": "这里应该用〈看出〉。懂指理解意思，从表情判断别人的心情要用看出。"}, {"text": "这个号码我懂了，就不用再背了。", "explanation": "这里应该用〈记住〉。懂指理解意思，记住号码、单词等要用记住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这段话我看了懂。", "corrected_sentence": "这段话我看懂了。", "error_description": "“看懂”是动补结构，“了”应放在补语“懂”之后，说“看懂了”，不能说“看了懂”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个成语的意思，我总算弄了懂。", "corrected_sentence": "这个成语的意思，我总算弄懂了。", "error_description": "“弄懂”是动补结构，“了”应放在补语“懂”之后，说“弄懂了”，不能说“弄了懂”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
