INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24052, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "表示数量或程度等没达到需要的标准。", "primary_collocate": null, "pronunciation": "bú gòu", "ipa": "pu˧˥ kou̯˥˩", "syllable_count": 2, "sentences": [{"text": "家里的米不够了，我去超市买一点。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书不够分，有两个同学没有。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤不够咸，再放一点盐吧。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯不够亮，我看不清黑板。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十个人坐一桌，椅子不够。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的钱不够买火车票。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服不够干，现在不能穿。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房子不够大，住不下五个人。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的饭不够多，大家都没吃饱。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不够努力，所以没有进步。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量或程度没达到需要的标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb9f15f3-ccce-46a2-a36a-890065503d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24052, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不够", "is_correct": true, "explanation": "正确答案，表示数量或程度没有达到需要的标准。"}, {"text": "步骤", "is_correct": false, "explanation": "声母不同：zhòu 与 gòu 的声母分别是 zh 和 g，意思是步骤。"}, {"text": "布告", "is_correct": false, "explanation": "韵母不同：gào 与 gòu 的韵母分别是 ao 和 ou，意思是布告。"}, {"text": "不顾", "is_correct": false, "explanation": "韵母不同：gù 与 gòu 的韵母分别是 u 和 ou，意思是不考虑、不在乎。"}], "explanations": {"不够": "正确答案，表示数量或程度没有达到需要的标准。", "步骤": "声母不同：zhòu 与 gòu 的声母分别是 zh 和 g，意思是步骤。", "布告": "韵母不同：gào 与 gòu 的韵母分别是 ao 和 ou，意思是布告。", "不顾": "韵母不同：gù 与 gòu 的韵母分别是 u 和 ou，意思是不考虑、不在乎。"}, "sentence_index": null, "correct_answer": "不够"}, "level_3": {"options": [{"text": "不够", "is_correct": true, "explanation": "正确答案。米没有达到需要的量，所以要去超市买一点。"}, {"text": "多了", "is_correct": false, "explanation": "语义：“多了”表示米已超出需要，与后文“去超市买一点”矛盾。"}, {"text": "够用", "is_correct": false, "explanation": "语义：“够用”表示满足需要，与后文“去超市买一点”矛盾。"}, {"text": "变多", "is_correct": false, "explanation": "搭配：“变多”说明数量增加，与后文“去超市买”的原因不合。"}], "explanations": {"不够": "正确答案。米没有达到需要的量，所以要去超市买一点。", "多了": "语义：“多了”表示米已超出需要，与后文“去超市买一点”矛盾。", "够用": "语义：“够用”表示满足需要，与后文“去超市买一点”矛盾。", "变多": "搭配：“变多”说明数量增加，与后文“去超市买”的原因不合。"}, "sentence_index": 0, "correct_answer": "不够"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盏灯不够亮，我们一开灯就刺得眼睛疼。", "explanation": "这里应该用〈过亮〉。“不够亮”表示亮度未达到需要，这里说的是太亮，应该用“过亮”。"}, {"text": "这碗面不够烫，我吃得满头大汗。", "explanation": "这里应该用〈过烫〉。“不够烫”表示温度未达到需要，这里说的是太烫，应该用“过烫”。"}, {"text": "这条河不够深，我们一下水就被冲走了。", "explanation": "这里应该用〈过深〉。“不够深”表示深度未达到需要，这里说的是太深，应该用“过深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24052, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不够", "is_correct": true, "explanation": "正确答案。衣服还没干透，所以现在不能穿。"}, {"text": "够", "is_correct": false, "explanation": "语义：“够”表示衣服已经足够干，与后文“现在不能穿”矛盾。"}, {"text": "干透", "is_correct": false, "explanation": "语法：填入后成“衣服干透干”，“干”重复，不成句；意思上也与“现在不能穿”矛盾。"}, {"text": "晾干", "is_correct": false, "explanation": "语法：填入后成“衣服晾干干”，“干”重复，不成句；意思上也与“现在不能穿”矛盾。"}], "explanations": {"不够": "正确答案。衣服还没干透，所以现在不能穿。", "够": "语义：“够”表示衣服已经足够干，与后文“现在不能穿”矛盾。", "干透": "语法：填入后成“衣服干透干”，“干”重复，不成句；意思上也与“现在不能穿”矛盾。", "晾干": "语法：填入后成“衣服晾干干”，“干”重复，不成句；意思上也与“现在不能穿”矛盾。"}, "sentence_index": 6, "correct_answer": "不够"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这双鞋不够大，我穿上后觉得松松垮垮。", "explanation": "这里应该用〈太大〉。“不够大”表示未达到需要的大小，这里说鞋子超过了需要，应该用“太大”。"}, {"text": "他的脾气不够温和，每次说话都轻声细语。", "explanation": "这里应该用〈过于温和〉。“不够温和”表示未达到需要的程度，这里说的是温和过了头，应该用“过于温和”。"}, {"text": "这个班的同学不够多，教室里却挤得转不开身。", "explanation": "这里应该用〈太多〉。“不够多”表示数量未达到需要，这里说的是数量超过了需要，应该用“太多”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这点钱不够的买票，我再去取一些吧。", "corrected_sentence": "这点钱不够买票，我再去取一些吧。", "error_description": "多加了“的”：“不够”后直接接动词，不能加“的”，应说“这点钱不够买票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双鞋不够得大，我穿着很挤。", "corrected_sentence": "这双鞋不够大，我穿着很挤。", "error_description": "“得”用错：“不够大”是谓语，前面不能加“得”，应说“这双鞋不够大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24056, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "困难", "is_correct": true, "explanation": "困难与顺利意思相反，指事情做起来有麻烦、有阻碍。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速说速度快，与事情是否顺利无关，不是反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、不模糊，与顺利没有相反关系。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐说排列有序，与顺利没有相反关系。"}], "correct_answer": "困难", "explanations": {"困难": "困难与顺利意思相反，指事情做起来有麻烦、有阻碍。", "迅速": "迅速说速度快，与事情是否顺利无关，不是反义词。", "清楚": "清楚指明白、不模糊，与顺利没有相反关系。", "整齐": "整齐说排列有序，与顺利没有相反关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24056, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "困难", "is_correct": true, "explanation": "困难与顺利意思相反，指事情做起来有麻烦、有阻碍。"}, {"text": "安静", "is_correct": false, "explanation": "安静说没有声音，与顺利没有相反关系。"}, {"text": "凉爽", "is_correct": false, "explanation": "凉爽说温度低、舒适，与顺利无关。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软说质地软，与顺利没有相反关系。"}], "correct_answer": "困难", "explanations": {"困难": "困难与顺利意思相反，指事情做起来有麻烦、有阻碍。", "安静": "安静说没有声音，与顺利没有相反关系。", "凉爽": "凉爽说温度低、舒适，与顺利无关。", "柔软": "柔软说质地软，与顺利没有相反关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24056, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事情做起来很顺，没有麻烦。", "primary_collocate": null, "pronunciation": "shùn lì", "ipa": "ʂu̯ən˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "今天的工作很顺利。", "target_word": "顺利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的考试顺利吗？", "target_word": "顺利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一切都很顺利，请你放心。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生活过得不太顺利。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝你旅行顺利！", "target_word": "顺利", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次会议开得很顺利，大家都满意。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚开始不太顺利，后来越来越好。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上很顺利，我们中午就到了。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新公司的事情进行得很顺利。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说考试很顺利，题目都会做。", "target_word": "顺利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "顺顺利利", "label": "重叠"}], "register": "中性", "sense_fingerprint": "形容事情、工作、过程很顺，没有麻烦，如工作很顺利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c08b601-4318-47af-9aac-f60ca0c0c5ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24056, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "顺利", "is_correct": true, "explanation": "顺利指工作进展没有麻烦。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不形容工作。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不用来说工作的状况。"}, {"text": "圆滑", "is_correct": false, "explanation": "搭配：“圆滑”形容人处事灵活，不用来说工作本身。"}], "explanations": {"顺利": "顺利指工作进展没有麻烦。", "清脆": "语义：“清脆”形容声音，不形容工作。", "明亮": "搭配：“明亮”形容光线或颜色，不用来说工作的状况。", "圆滑": "搭配：“圆滑”形容人处事灵活，不用来说工作本身。"}, "sentence_index": 0, "correct_answer": "顺利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对老板很顺利，从不反驳。", "explanation": "这里应该用〈顺从〉。顺利说事情进展，不用来形容人对别人的态度，听从别人要用顺从。"}, {"text": "这块布料很顺利，摸上去很舒服。", "explanation": "这里应该用〈顺滑〉。顺利说事情进展没有麻烦，形容布料、头发的光滑触感要用顺滑。"}, {"text": "这个小女孩很顺利，每天都笑得很开心。", "explanation": "这里应该用〈开朗〉。顺利用于事情进展，形容人的性格要用开朗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "顺利", "is_correct": true, "explanation": "顺利指事情进展没有障碍，与“不太”搭配表示开始时不太顺。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”形容外貌，不用于描述事情的进展。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”说空间大，不能用来形容事情的进展。"}, {"text": "轻巧", "is_correct": false, "explanation": "语义：“轻巧”说物体轻便，不形容事情的进展。"}], "explanations": {"顺利": "顺利指事情进展没有障碍，与“不太”搭配表示开始时不太顺。", "漂亮": "语义：“漂亮”形容外貌，不用于描述事情的进展。", "宽敞": "搭配：“宽敞”说空间大，不能用来形容事情的进展。", "轻巧": "语义：“轻巧”说物体轻便，不形容事情的进展。"}, "sentence_index": 6, "correct_answer": "顺利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的价格很顺利，买什么都很划算。", "explanation": "这里应该用〈实惠〉。顺利说事情进展，不用来形容价格，价格低、划算要用实惠。"}, {"text": "他的想法很顺利，考虑问题很周全。", "explanation": "这里应该用〈成熟〉。顺利用于事情进展，形容人的想法、认识的水平要用成熟。"}, {"text": "他的身体很顺利，一年都没生过病。", "explanation": "这里应该用〈健康〉。顺利说事情进展，形容身体状况要用健康。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天的会议应该开很顺利。", "corrected_sentence": "明天的会议应该开得很顺利。", "error_description": "补语要用“得”连接，“开很顺利”漏了“得”，正确是“开得很顺利”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的计划顺利完成的了。", "corrected_sentence": "我们的计划顺利完成了。", "error_description": "多了一个“的”：动词“完成”后直接接“了”，中间不能插入“的”。正确是“顺利完成了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24058, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "飞得动", "is_correct": true, "explanation": "反义词：“飞得动”表示有能力继续飞，与“飞不动”正好相反。"}, {"text": "挑选", "is_correct": false, "explanation": "与“飞不动”没有反义或近义关系，表示从多个中选出。"}, {"text": "停留", "is_correct": false, "explanation": "与“飞不动”没有语义关系，表示在某处不再前进。"}, {"text": "收藏", "is_correct": false, "explanation": "与“飞不动”没有语义关系，表示把东西保存起来。"}], "correct_answer": "飞得动", "explanations": {"飞得动": "反义词：“飞得动”表示有能力继续飞，与“飞不动”正好相反。", "挑选": "与“飞不动”没有反义或近义关系，表示从多个中选出。", "停留": "与“飞不动”没有语义关系，表示在某处不再前进。", "收藏": "与“飞不动”没有语义关系，表示把东西保存起来。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24058, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "飞得动", "is_correct": true, "explanation": "反义词：“飞得动”表示有能力继续飞，与“飞不动”正好相反。"}, {"text": "讨论", "is_correct": false, "explanation": "与“飞不动”没有反义或近义关系，表示大家一起交换意见。"}, {"text": "摆放", "is_correct": false, "explanation": "与“飞不动”没有语义关系，表示把东西按一定位置放好。"}, {"text": "清洗", "is_correct": false, "explanation": "与“飞不动”没有语义关系，表示用水等去除污物。"}], "correct_answer": "飞得动", "explanations": {"飞得动": "反义词：“飞得动”表示有能力继续飞，与“飞不动”正好相反。", "讨论": "与“飞不动”没有反义或近义关系，表示大家一起交换意见。", "摆放": "与“飞不动”没有语义关系，表示把东西按一定位置放好。", "清洗": "与“飞不动”没有语义关系，表示用水等去除污物。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24058, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "小鸟或飞机没有力气，不能飞了。", "primary_collocate": null, "pronunciation": "fēi bu dòng", "ipa": "feɪ̯˥ pu toŋ˥˩", "syllable_count": 3, "sentences": [{"text": "小鸟没有力气，飞不动了。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟生病了，飞不动。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的发动机坏了，飞不动。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小鸟受伤流血后，没有力气，飞不动了。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天很冷，小鸟冻得飞不动。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞了一天，累得飞不动了。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟太小，风又大，飞不动。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机没油了，再也飞不动了。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟饿了一天，现在飞不动。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小鸟的翅膀淋了雨，没有力气，飞不动。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飞得动", "label": "肯定式"}], "register": "中性", "sense_fingerprint": "小鸟或飞机没有力气，不能再飞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb9f15f3-ccce-46a2-a36a-890065503d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24058, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飞不动", "is_correct": true, "explanation": "正确答案。小鸟没有力气，所以已经飞不动了。"}, {"text": "飞得快", "is_correct": false, "explanation": "语义：小鸟没有力气时，“飞得快”与前面的原因矛盾。"}, {"text": "飞得动", "is_correct": false, "explanation": "语义：“飞得动”表示有力气，与“没有力气”矛盾。"}, {"text": "飞得很远", "is_correct": false, "explanation": "语义：小鸟没有力气，“飞得很远”与前面的原因矛盾。"}], "explanations": {"飞不动": "正确答案。小鸟没有力气，所以已经飞不动了。", "飞得快": "语义：小鸟没有力气时，“飞得快”与前面的原因矛盾。", "飞得动": "语义：“飞得动”表示有力气，与“没有力气”矛盾。", "飞得很远": "语义：小鸟没有力气，“飞得很远”与前面的原因矛盾。"}, "sentence_index": 0, "correct_answer": "飞不动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条鱼吃饱喝足，精神抖擞，却飞不动了。", "explanation": "这里应该用〈游得很快〉。“飞不动”只用于会飞的鸟和飞机，鱼不会飞，应说“游得很快”。"}, {"text": "他跑了一天，没有力气，飞不动了。", "explanation": "这里应该用〈走不动〉。人不会飞，没有力气时应说“走不动”或“跑不动”，“飞不动”只用于鸟和飞机。"}, {"text": "他划了一天船，没有力气，船飞不动了。", "explanation": "这里应该用〈划不动〉。船在水上靠划，没力气时应说“划不动”，“飞不动”只用于鸟和飞机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飞不动", "is_correct": true, "explanation": "正确答案。小鸟太小，风又大，所以飞不动。"}, {"text": "飞得高", "is_correct": false, "explanation": "语义：小鸟太小、风又大，“飞得高”与前面的原因矛盾。"}, {"text": "飞得稳", "is_correct": false, "explanation": "语义：风又大，“飞得稳”与“风又大”的条件矛盾。"}, {"text": "起飞", "is_correct": false, "explanation": "搭配：“起飞”指开始飞行，不能表达因太小、风大而无法继续飞行的结果。"}], "explanations": {"飞不动": "正确答案。小鸟太小，风又大，所以飞不动。", "飞得高": "语义：小鸟太小、风又大，“飞得高”与前面的原因矛盾。", "飞得稳": "语义：风又大，“飞得稳”与“风又大”的条件矛盾。", "起飞": "搭配：“起飞”指开始飞行，不能表达因太小、风大而无法继续飞行的结果。"}, "sentence_index": 6, "correct_answer": "飞不动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆卡车跑了一天，没有力气，飞不动了。", "explanation": "这里应该用〈开不动〉。卡车在路上行驶应说“开不动”，“飞不动”只用于鸟和飞机。"}, {"text": "这只鸡天生就不会飞，它没有力气，飞不动了。", "explanation": "这里应该用〈走不动〉。鸡本来不会飞，“飞不动”预设了能飞，这里应说“走不动”。"}, {"text": "这只狗吃饱喝足，精神抖擞，现在却飞不动了。", "explanation": "这里应该用〈跑得很快〉。“飞不动”只用于会飞的鸟和飞机，狗不会飞，应说“跑得很快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小鸟没有力气，已经飞不动过。", "corrected_sentence": "小鸟没有力气，已经飞不动了。", "error_description": "错误形式：“飞不动过”。正确形式：“飞不动了”。“飞不动”描述小鸟已经没有力气的状态，应用“了”表示变化，不能用“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风太大了，小鸟的翅膀又湿，能飞不动了。", "corrected_sentence": "风太大了，小鸟的翅膀又湿，飞不动了。", "error_description": "错误形式：“能飞不动”。正确形式：“飞不动”。“飞不动”本身已表示无法飞行，前面不能再加“能”，二者语义冲突。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
