INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24060, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "地球对物体的吸引力，使东西往下落。", "primary_collocate": null, "pronunciation": "zhòng lì", "ipa": "ʈʂʊŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "因为有重力，球扔上去会掉下来。", "target_word": "重力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "重力像地球的手，把东西往下拉。", "target_word": "重力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有重力，我们会飘在空中。", "target_word": "重力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "重力让我们站在地上，不会飞走。", "target_word": "重力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书从桌子上掉下来，是重力的原因。", "target_word": "重力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球的重力很大，所以东西都往下掉。", "target_word": "重力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树叶落到地上，是重力在拉它。", "target_word": "重力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太空中重力很小，人可以飘起来。", "target_word": "重力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你扔出去的球，重力会把它拉回地面。", "target_word": "重力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳得再高，重力也会把你拉回来。", "target_word": "重力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重力场", "label": "复合"}, {"form": "重力加速度", "label": "复合"}], "register": "中性", "sense_fingerprint": "地球把东西往下拉的力，让东西落地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb9f15f3-ccce-46a2-a36a-890065503d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24060, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "重力", "is_correct": true, "explanation": "正确：指地球对物体的吸引力。"}, {"text": "中立", "is_correct": false, "explanation": "zhōng（第一声）与 zhòng（第四声）声调不同，意思是中立，不偏向任何一方。"}, {"text": "正例", "is_correct": false, "explanation": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是正面的例子。"}, {"text": "正立", "is_correct": false, "explanation": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是端正地竖立。"}], "explanations": {"重力": "正确：指地球对物体的吸引力。", "中立": "zhōng（第一声）与 zhòng（第四声）声调不同，意思是中立，不偏向任何一方。", "正例": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是正面的例子。", "正立": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是端正地竖立。"}, "sentence_index": null, "correct_answer": "重力"}, "level_3": {"options": [{"text": "重力", "is_correct": true, "explanation": "正确：有重力，球扔上去才会掉下来。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色和球会不会掉下来无关，不能作为原因。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不会让球掉下来，这句说的是下落的原因。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状说的是外观，不是让物体下落的力。"}], "explanations": {"重力": "正确：有重力，球扔上去才会掉下来。", "颜色": "语义：颜色和球会不会掉下来无关，不能作为原因。", "温度": "语义：温度不会让球掉下来，这句说的是下落的原因。", "形状": "语义：形状说的是外观，不是让物体下落的力。"}, "sentence_index": 0, "correct_answer": "重力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鞋底的重力很大，所以不容易滑倒。", "explanation": "这里应该用〈摩擦力〉。鞋底防滑靠的是与地面之间的摩擦力，重力不是这个意思。"}, {"text": "这个人的重力很低，所以不容易摔倒。", "explanation": "这里应该用〈重心〉。重心低人才稳，重力本身不能说高低，所以这里要说重心。"}, {"text": "这个苹果的重力是两百克。", "explanation": "这里应该用〈重量〉。重力是力，单位是牛顿；说东西有几克，要用重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重力", "is_correct": true, "explanation": "正确：树叶落到地上，是重力在拉它。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不会拉动树叶，不能作为树叶落下的原因。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不能拉动树叶，这句说的是拉它的力。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指人的高矮，不是拉动树叶的力。"}], "explanations": {"重力": "正确：树叶落到地上，是重力在拉它。", "味道": "语义：味道不会拉动树叶，不能作为树叶落下的原因。", "课本": "语义：课本不能拉动树叶，这句说的是拉它的力。", "身高": "语义：身高指人的高矮，不是拉动树叶的力。"}, "sentence_index": 6, "correct_answer": "重力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这袋米的重力是五公斤。", "explanation": "这里应该用〈重量〉。重力是力，单位是牛顿；说东西有几公斤，要用重量。"}, {"text": "水管里的重力很大，会把接口冲开。", "explanation": "这里应该用〈压力〉。水在管道里挤压管壁，是压力，不是重力。"}, {"text": "磁铁的重力能吸住铁钉。", "explanation": "这里应该用〈磁力〉。重力只指地球对物体的吸引，磁铁吸铁钉要用磁力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把笔放开，笔就会因为一个重力掉到地上。", "corrected_sentence": "我把笔放开，笔就会因为重力掉到地上。", "error_description": "量词错误：“重力”前面不加“个”，这里不需要数量词，应直接说“因为重力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "太空中的重力比地球小的多。", "corrected_sentence": "太空中的重力比地球小得多。", "error_description": "补语标记错误：程度补语应用“得”连接，不能用“的”。正确说法是“比地球小得多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
