INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24062, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情为什么是这样的道理。", "primary_collocate": null, "pronunciation": "yuán lǐ", "ipa": "ɥɛn˧˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师给我们讲了飞机飞起来的原理。", "target_word": "原理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器的工作原理很简单。", "target_word": "原理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道电灯为什么会亮，它的原理是什么吗？", "target_word": "原理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想弄明白手机的原理。", "target_word": "原理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学课上，我们学习了冰为什么会浮在水上的原理。", "target_word": "原理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两台机器的原理不一样。", "target_word": "原理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不懂这个原理，所以修不好。", "target_word": "原理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里用图片说明了空调的原理。", "target_word": "原理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们做实验，是为了理解这个原理。", "target_word": "原理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然原理不难，但是做起来很麻烦。", "target_word": "原理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "工作原理", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物运行或形成的基本道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca8c494-ae71-4330-9c72-7312641af8a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24062, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原理", "is_correct": true, "explanation": "原理：事物运行或形成的基本道理，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：讲解飞机飞起来的内容不能是颜色，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：「讲」的对象是道理或内容，「味道」不能作为讲解的内容。"}, {"text": "体重", "is_correct": false, "explanation": "语义：讲解飞行的内容不是体重，句意不通。"}], "explanations": {"原理": "原理：事物运行或形成的基本道理，符合句意。", "颜色": "语义：讲解飞机飞起来的内容不能是颜色，句意不通。", "味道": "搭配：「讲」的对象是道理或内容，「味道」不能作为讲解的内容。", "体重": "语义：讲解飞行的内容不是体重，句意不通。"}, "sentence_index": 0, "correct_answer": "原理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "做人要有做人的原理。", "explanation": "这里应该用〈道理〉。原理指事物运行或形成的基本规律，讲做人的准则要用道理。"}, {"text": "他失败的原理是粗心。", "explanation": "这里应该用〈原因〉。原理是事物运行的道理，不能用来说明导致失败的原因。"}, {"text": "这个灯的原理很大。", "explanation": "这里应该用〈功率〉。原理是道理，不能用大小来形容；灯的大小要用功率来说明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原理", "is_correct": true, "explanation": "原理：事物运行的基本道理，符合句意。"}, {"text": "座位", "is_correct": false, "explanation": "语义：不懂座位与修理机器无关，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄与修理机器无关，句意不通。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：「不懂」的对象应是道理或方法，「口味」不搭配。"}], "explanations": {"原理": "原理：事物运行的基本道理，符合句意。", "座位": "语义：不懂座位与修理机器无关，句意不通。", "年龄": "语义：年龄与修理机器无关，句意不通。", "口味": "搭配：「不懂」的对象应是道理或方法，「口味」不搭配。"}, "sentence_index": 6, "correct_answer": "原理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们必须遵守学校的原理。", "explanation": "这里应该用〈规定〉。原理是事物运作的道理，不是学校的规章；遵守规章要用规定。"}, {"text": "这道题用到了一张原理。", "explanation": "这里量词用错。原理应用〈个〉或〈条〉，〈张〉用于纸、桌子等平面的东西，不能用来数原理。"}, {"text": "这道题的原理是三。", "explanation": "这里应该用〈答案〉。原理是道理，不是数字结果；问题的结果要说答案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师向我们解释了一张物理原理。", "corrected_sentence": "老师向我们解释了一个物理原理。", "error_description": "错误：「原理」的量词应用「个」或「条」，不能用「张」（张用于纸、桌子等平面的东西）。应说「一个物理原理」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没弄清电视机的一本原理。", "corrected_sentence": "我还没弄清电视机的原理。", "error_description": "错误：「原理」不能用「本」来数（本用于书册）。应说「电视机的原理」，去掉数量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
