INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24064, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西或方法拿来用在某件事情上。", "primary_collocate": null, "pronunciation": "yòng dào", "ipa": "jʊŋ˥˩ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "做饭时，我常用到这把小刀。", "target_word": "用到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写字要用到笔和纸。", "target_word": "用到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这台机器我每天都用到。", "target_word": "用到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "煮面条要用到一口大锅。", "target_word": "用到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "修理房子时，我们用到了新买的电钻。", "target_word": "用到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷看报纸每天都要用到老花镜。", "target_word": "用到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过生日时，我们用到了漂亮的盘子。", "target_word": "用到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些旧东西以后也许能用到。", "target_word": "用到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打扫房间要用到扫把和水桶。", "target_word": "用到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明把零花钱用到了买书上。", "target_word": "用到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "用到了", "label": "体标"}, {"form": "用不到", "label": "否定"}], "register": "中性", "sense_fingerprint": "用到：把东西、方法等拿来用在某件事上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '772fca80-e265-4879-9a3c-3f993f58a8df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用到", "is_correct": true, "explanation": "正确：“用到”表示做饭时常用这把小刀，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，与做饭时使用工具的语境不符。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“这把小刀”做宾语。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”的对象是食物，“我常切这把小刀”不成立。"}], "explanations": {"用到": "正确：“用到”表示做饭时常用这把小刀，与句意相符。", "吃": "语义：“吃”的对象是食物，与做饭时使用工具的语境不符。", "睡": "配价：“睡”是不及物动词，不能带“这把小刀”做宾语。", "切": "搭配：“切”的对象是食物，“我常切这把小刀”不成立。"}, "sentence_index": 0, "correct_answer": "用到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用到周末学习钢琴。", "explanation": "这里应该用〈利用〉。用到指把东西拿来用，时间、机会要用利用。"}, {"text": "这个孩子用到大人的照顾。", "explanation": "这里应该用〈需要〉。用到指借助具体的物件，“照顾”这类要求要用需要。"}, {"text": "我用到这个题很难。", "explanation": "这里应该用〈觉得〉。用到指使用某物办事，对事情的看法要用觉得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用到", "is_correct": true, "explanation": "正确：“用到”表示过生日时用了漂亮的盘子，与句意相符。"}, {"text": "讲", "is_correct": false, "explanation": "搭配：“讲”的对象是道理或故事，不能说讲盘子。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”表示歌唱，与盘子的使用无关。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带“漂亮的盘子”做宾语。"}], "explanations": {"用到": "正确：“用到”表示过生日时用了漂亮的盘子，与句意相符。", "讲": "搭配：“讲”的对象是道理或故事，不能说讲盘子。", "唱": "语义：“唱”表示歌唱，与盘子的使用无关。", "笑": "配价：“笑”是不及物动词，不能带“漂亮的盘子”做宾语。"}, "sentence_index": 6, "correct_answer": "用到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事用到我很担心。", "explanation": "这里应该用〈让〉。用到指使用某物办事，不能表示使人心里产生某种感受，这里要用让。"}, {"text": "这件衣服用到了很多人的目光。", "explanation": "这里应该用〈吸引〉。用到指使用物件，人的目光要用吸引。"}, {"text": "他用到一脸笑容走进教室。", "explanation": "这里应该用〈露出〉。用到指使用某物办事，笑容是表情，要用露出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "写作业的时候，我常把用到铅笔。", "corrected_sentence": "写作业的时候，我常用到铅笔。", "error_description": "“把”误加：“用到”后直接带宾语，不能在“用到”前加“把”；多出的“把”应删去，应说“常用到铅笔”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈做饭时用到着那把旧菜刀。", "corrected_sentence": "妈妈做饭时用到了那把旧菜刀。", "error_description": "体标错误：「用到」是动补结构，表示结果，不能带表示持续的「着」，应说「用到了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
