INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24066, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一些数字合起来得到总数。", "primary_collocate": null, "pronunciation": "jì suàn", "ipa": "tɕi˥˩ suan˥˩", "syllable_count": 2, "sentences": [{"text": "请你计算一下一共多少钱。", "target_word": "计算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在纸上计算着总数。", "target_word": "计算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手机计算了这个月的花费。", "target_word": "计算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们计算这三个数的和。", "target_word": "计算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正在计算买菜的钱。", "target_word": "计算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你计算过今天花了多少钱吗？", "target_word": "计算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥很快就计算出了结果。", "target_word": "计算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些数字计算一下。", "target_word": "计算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个一个地计算桌上的钱。", "target_word": "计算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题要先计算两个数字的总数。", "target_word": "计算", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "计算了", "label": "完成体"}, {"form": "计算着", "label": "持续体"}, {"form": "计算过", "label": "经历体"}, {"form": "计算计算", "label": "重叠"}], "register": "中性", "sense_fingerprint": "把数字加在一起算出总数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89628db-2a92-48c4-bb2a-aa8338e4bf66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "计算", "is_correct": true, "explanation": "正确。“请你计算一下一共多少钱”表示把钱数算出来。"}, {"text": "玩", "is_correct": false, "explanation": "语义：“玩”指游戏娱乐，不能用来表示清点、算出钱数。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”用于人骑车、骑马等，不能用于算钱数。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与钱数无关。"}], "explanations": {"计算": "正确。“请你计算一下一共多少钱”表示把钱数算出来。", "玩": "语义：“玩”指游戏娱乐，不能用来表示清点、算出钱数。", "骑": "搭配：“骑”用于人骑车、骑马等，不能用于算钱数。", "唱": "语义：“唱”指发出歌声，与钱数无关。"}, "sentence_index": 0, "correct_answer": "计算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他计算了那本书的内容。", "explanation": "这里应该用〈阅读〉。“计算”指算出数字的总数，书的内容要读，不能计算。"}, {"text": "他认真计算了那幅画。", "explanation": "这里应该用〈欣赏〉。“计算”指按数字算出总数，不能用于画这类作品。"}, {"text": "这首诗计算了春天的来临。", "explanation": "这里应该用〈预示〉。“计算”只用于能算出数值的事，春天的来临不能算出总数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "计算", "is_correct": true, "explanation": "正确。“哥哥很快就计算出了结果”表示通过运算求出结果。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与“得出结果”无关。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指快速移动，不能表示求出结果。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”后接“照片”等可显影之物，不能接“结果”。"}], "explanations": {"计算": "正确。“哥哥很快就计算出了结果”表示通过运算求出结果。", "吃": "语义：“吃”指进食，与“得出结果”无关。", "跑": "语义：“跑”指快速移动，不能表示求出结果。", "洗": "搭配：“洗”后接“照片”等可显影之物，不能接“结果”。"}, "sentence_index": 6, "correct_answer": "计算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈计算了窗外的雨声。", "explanation": "这里应该用〈听〉。“计算”指算出总数，不能用于雨声这类声音。"}, {"text": "他计算了那只小猫的颜色。", "explanation": "这里应该用〈看〉。“计算”指算出数量，颜色要用眼睛看，不能计算。"}, {"text": "她计算了那首诗的香味。", "explanation": "这里应该用〈闻〉。“计算”指算出结果，香味要用鼻子闻，不能计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一起计算了了这笔花费。", "corrected_sentence": "我们一起计算了这笔花费。", "error_description": "错误：“计算了了”。正确：“计算了”。“了”只用一次，重复的“了”多余。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们昨天没计算了全部的费用。", "corrected_sentence": "他们昨天计算了全部的费用。", "error_description": "错误：“没计算了”。正确：“没计算”或“计算了”。否定“没”与完成“了”不能同时用在同一个动词上，否定未发生的动作时要去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
