INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24068, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "风洞是一个像大管子一样的东西，里面可以吹出很快的风，用来帮助造飞机和火箭的科学家做测试。", "primary_collocate": null, "pronunciation": "fēng dòng", "ipa": "fɤŋ˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "风洞里能吹出很大的风。", "target_word": "风洞", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "科学家在风洞里做飞机测试。", "target_word": "风洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个风洞像一根大管子。", "target_word": "风洞", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们把火箭模型放进风洞里。", "target_word": "风洞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风洞可以帮科学家造更好的飞机。", "target_word": "风洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "参观科学馆时，我看到了一个风洞。", "target_word": "风洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风洞里的风很快，吹得模型直晃。", "target_word": "风洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做火箭测试以前，要先开风洞。", "target_word": "风洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说风洞是造飞机的好帮手。", "target_word": "风洞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个风洞太大了，像一间房子。", "target_word": "风洞", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座风洞", "label": "量词"}, {"form": "一个风洞", "label": "量词"}, {"form": "风洞实验", "label": "复合"}, {"form": "風洞", "label": "繁体"}], "register": "科技", "sense_fingerprint": "像大管子的装置，能吹出很快的风，供科学家测试飞机和火箭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e653b9f-1786-4a98-96fa-5c2fd7ba68c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24068, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风洞", "is_correct": true, "explanation": "风洞是能吹出很快的风的像大管子的装置，符合句意。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装书本的袋子，不会吹出大风。"}, {"text": "鱼缸", "is_correct": false, "explanation": "语义：鱼缸用来养鱼，里面不会吹出风。"}, {"text": "饭碗", "is_correct": false, "explanation": "搭配：能吹出很大风的对象是风扇、风洞一类装置，不说“饭碗里能吹出很大的风”。"}], "explanations": {"风洞": "风洞是能吹出很快的风的像大管子的装置，符合句意。", "书包": "语义：书包是装书本的袋子，不会吹出大风。", "鱼缸": "语义：鱼缸用来养鱼，里面不会吹出风。", "饭碗": "搭配：能吹出很大风的对象是风扇、风洞一类装置，不说“饭碗里能吹出很大的风”。"}, "sentence_index": 0, "correct_answer": "风洞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厨房的风洞坏了，水一直在往外漏。", "explanation": "这里应该用〈水管〉。水管用来输送水，风洞是人工造风的实验设备，不能用来输水。"}, {"text": "司机在风洞里洗车，洗完就开走了。", "explanation": "这里应该用〈洗车场〉。风洞是做空气动力实验的设备，不能用来洗车。"}, {"text": "客厅的风洞烧得很旺。", "explanation": "这里应该用〈壁炉〉。壁炉是用来烧火取暖的，风洞是做实验吹风的设备，不能用来烧火。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风洞", "is_correct": true, "explanation": "风洞里的风很快，能把模型吹得直晃，符合句意。"}, {"text": "信箱", "is_correct": false, "explanation": "语义：信箱用来收信，里面不会有吹动模型的风。"}, {"text": "口袋", "is_correct": false, "explanation": "语义：口袋是装东西的小袋，不会产生吹动模型的风。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯是装水的容器，不会产生吹动模型的快风。"}], "explanations": {"风洞": "风洞里的风很快，能把模型吹得直晃，符合句意。", "信箱": "语义：信箱用来收信，里面不会有吹动模型的风。", "口袋": "语义：口袋是装东西的小袋，不会产生吹动模型的风。", "水杯": "语义：水杯是装水的容器，不会产生吹动模型的快风。"}, "sentence_index": 6, "correct_answer": "风洞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校新买了一辆风洞。", "explanation": "这里应该用〈座〉。“辆”用于车辆，风洞是固定的大型设备，应说“一座风洞”。"}, {"text": "研究所的走廊里放着一根风洞。", "explanation": "这里应该用〈座〉。“根”用于细长物，风洞是大型设备，应说“一座风洞”。"}, {"text": "工厂的仓库里堆着一张风洞。", "explanation": "这里应该用〈座〉。“张”用于平面物品，风洞是立体的大型设备，应说“一座风洞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究所有一辆风洞。", "corrected_sentence": "研究所有一座风洞。", "error_description": "量词错误：“辆”用于车辆，“风洞”是固定的大型设备，应配量词“座”，说“一座风洞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究所里有两座风洞们。", "corrected_sentence": "研究所里有两座风洞。", "error_description": "“们”错误：“们”只用于指人的名词之后，“风洞”是事物，不能加“们”表示复数；应直接说“两座风洞”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11dc1a6-578c-4e2c-94f2-1e7d320bd4a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
