INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24070, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24070, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "风吹到身上，让人感觉凉凉的。", "primary_collocate": null, "pronunciation": "chuī fēng", "ipa": "ʈʂʰweɪ˥ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "夏天晚上，我们坐在院子里吹风。", "target_word": "吹风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气很热，他站在门口吹风。", "target_word": "吹风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河边吹风很凉快。", "target_word": "吹风", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢开着窗户吹风。", "target_word": "吹风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐在车里，我把手伸出窗外吹风。", "target_word": "吹风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在海边吹风，心里很舒服。", "target_word": "吹风", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "热了一天，晚上去楼顶吹风吧。", "target_word": "吹风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宝宝出了汗，不要让他吹风。", "target_word": "吹风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他跑完步，站着吹风休息。", "target_word": "吹风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天晚饭后都去河边吹风。", "target_word": "吹风", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "吹吹风", "label": "重叠"}, {"form": "吹了风", "label": "体标"}, {"form": "吹着风", "label": "体标"}, {"form": "吹过风", "label": "体标"}, {"form": "吹風", "label": "繁体"}], "register": "口语", "sense_fingerprint": "吹风：风吹在身上，人觉得凉凉的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '772fca80-e265-4879-9a3c-3f993f58a8df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吹风", "is_correct": true, "explanation": "吹风：坐在院子里让风吹在身上，人觉得凉凉的，符合句意。"}, {"text": "取暖", "is_correct": false, "explanation": "语义：“取暖”是让身体变暖，与“夏天晚上”的凉爽语境矛盾。"}, {"text": "下雪", "is_correct": false, "explanation": "语义：“下雪”是天气现象，人不能在院子里“下雪”，句意不通。"}, {"text": "驱寒", "is_correct": false, "explanation": "搭配：“驱寒”要驱赶的是寒气，夏天晚上没有寒气可驱，不能搭配。"}], "explanations": {"吹风": "吹风：坐在院子里让风吹在身上，人觉得凉凉的，符合句意。", "取暖": "语义：“取暖”是让身体变暖，与“夏天晚上”的凉爽语境矛盾。", "下雪": "语义：“下雪”是天气现象，人不能在院子里“下雪”，句意不通。", "驱寒": "搭配：“驱寒”要驱赶的是寒气，夏天晚上没有寒气可驱，不能搭配。"}, "sentence_index": 0, "correct_answer": "吹风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "没有一点风，大家都到树下吹风。", "explanation": "这里应该用〈乘凉〉。吹风要有风吹到身上，这里说没有一点风。"}, {"text": "他每次聚会都爱吹风，说自己多能干。", "explanation": "这里应该用〈吹牛〉。吹风指风吹在身上，夸大自己、说大话要用吹牛，吹风没有这个意思。"}, {"text": "裁判一吹风，球员们就跑了起来。", "explanation": "这里应该用〈吹哨〉。吹风指风吹在身上，裁判用哨子发出信号要说吹哨，吹风没有这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吹风", "is_correct": true, "explanation": "吹风：到楼顶让凉风吹在身上，符合“热了一天”之后的语境。"}, {"text": "御寒", "is_correct": false, "explanation": "语域：“御寒”是书面语，口语句“……吧”里不用；语义：热了一天却要御寒，与句意矛盾。"}, {"text": "避寒", "is_correct": false, "explanation": "语义：“避寒”指躲避寒冷，与“热了一天”的语境矛盾。"}, {"text": "烤火", "is_correct": false, "explanation": "语义：“烤火”需要靠近火取暖，与热了一天之后去楼顶的语境不符。"}], "explanations": {"吹风": "吹风：到楼顶让凉风吹在身上，符合“热了一天”之后的语境。", "御寒": "语域：“御寒”是书面语，口语句“……吧”里不用；语义：热了一天却要御寒，与句意矛盾。", "避寒": "语义：“避寒”指躲避寒冷，与“热了一天”的语境矛盾。", "烤火": "语义：“烤火”需要靠近火取暖，与热了一天之后去楼顶的语境不符。"}, "sentence_index": 6, "correct_answer": "吹风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洗完头，妈妈拿出吹风把头发吹干。", "explanation": "这里应该用〈吹风机〉。吹风指风吹在身上，吹干头发的电器要说吹风机。"}, {"text": "屋外很冷，大家围在火炉旁吹风。", "explanation": "这里应该用〈取暖〉。吹风是凉风吹在身上，与“屋外很冷、围在火炉旁”的语境矛盾。"}, {"text": "北风呼呼地刮，他蹲在墙角吹风。", "explanation": "这里应该用〈避风〉。吹风指风吹在身上，北风呼呼刮时要躲在墙角避风，不能说吹风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在窗前吹风吹，很舒服。", "corrected_sentence": "他在窗前吹吹风，很舒服。", "error_description": "重叠形式错误：「吹风」重叠应为「吹吹风」，不能说「吹风吹」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚饭后，爸爸在河边吹着一会儿风，心里很舒服。", "corrected_sentence": "晚饭后，爸爸在河边吹了一会儿风，心里很舒服。", "error_description": "体标错误：离合词「吹风」带时量补语「一会儿」表示已完成的一段时间，要用「了」，说「吹了一会儿风」，不能用「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
