INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24072, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "工程就是建造大楼、修路等需要很多人一起做的大工作。", "primary_collocate": null, "pronunciation": "gōng chéng", "ipa": "kʊŋ˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这项工程要花两年时间。", "target_word": "工程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在做大桥的工程。", "target_word": "工程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新地铁工程已经开始了。", "target_word": "工程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工程需要几百个工人。", "target_word": "工程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校旁边的修路工程很大。", "target_word": "工程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，工程停了三天。", "target_word": "工程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家公司负责这项工程。", "target_word": "工程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么大的工程，一个人做不完。", "target_word": "工程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程完成以后，这里会有一座新桥。", "target_word": "工程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子旁边有个工程，每天都很吵。", "target_word": "工程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "工程队", "label": "复合"}, {"form": "工程师", "label": "复合"}], "register": "中性", "sense_fingerprint": "建大楼、修路等需要很多人合作的大型工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c53470-eab2-4aaa-a8c7-536b79bbc5b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饭", "is_correct": false, "explanation": "语义：饭是吃的东西，不是需要花两年时间完成的任务，“这项饭”说不通。"}, {"text": "工程", "is_correct": true, "explanation": "正确：“这项工程”指需要两年时间完成的大型工作。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以“花两年时间”去完成的事情。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“花两年时间”不用于感冒这样的状态，“这项感冒”也不通。"}], "explanations": {"饭": "语义：饭是吃的东西，不是需要花两年时间完成的任务，“这项饭”说不通。", "工程": "正确：“这项工程”指需要两年时间完成的大型工作。", "天气": "语义：天气不是可以“花两年时间”去完成的事情。", "感冒": "搭配：“花两年时间”不用于感冒这样的状态，“这项感冒”也不通。"}, "sentence_index": 0, "correct_answer": "工程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每周都去健身房做工程。", "explanation": "这里应该用〈锻炼〉。“工程”指建造大楼、修路等大工作，不能用来指锻炼身体。"}, {"text": "我们要工程一座新的图书馆。", "explanation": "这里应该用〈建设〉。工程是名词，不能作动词用；表示动作要用“建设”。"}, {"text": "这个月我们公司开始了一只新工程。", "explanation": "这里应该用〈项〉。“只”用于动物等，工程要用“项”或“个”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水", "is_correct": false, "explanation": "语义：水不是需要“负责”的任务，“负责这项水”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“负责”不接“年龄”这类词。"}, {"text": "工程", "is_correct": true, "explanation": "正确：“负责这项工程”指承担一项大型建设工作。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是需要承担的任务，句子说不通。"}], "explanations": {"水": "语义：水不是需要“负责”的任务，“负责这项水”说不通。", "年龄": "搭配：“负责”不接“年龄”这类词。", "工程": "正确：“负责这项工程”指承担一项大型建设工作。", "颜色": "语义：颜色不是需要承担的任务，句子说不通。"}, "sentence_index": 6, "correct_answer": "工程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在街上修了一本工程。", "explanation": "这里应该用〈项〉。“本”用于书籍和本子，工程不用“本”来数。"}, {"text": "工人们在工程里做衣服。", "explanation": "这里应该用〈工厂〉。工程指建造大楼、修路等大工作，不能当作生产衣服的地方。"}, {"text": "政府准备工程一座新桥。", "explanation": "这里应该用〈修建〉。工程是名词，不能作动词用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只工程今年年底就能完成。", "corrected_sentence": "这项工程今年年底就能完成。", "error_description": "量词错了：“工程”应该用“项”，说“这项工程”；“只”不能用来数工程。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆工程的进度比预期快。", "corrected_sentence": "这项工程的进度比预期快。", "error_description": "量词错了：“工程”应该用“项”，说“这项工程”；“辆”只用于车，不能用来数工程。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
