INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24074, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西变得和以前不一样了。", "primary_collocate": null, "pronunciation": "biàn huà", "ipa": "pjɛn˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市的变化很大。", "target_word": "变化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气的变化让我感冒了。", "target_word": "变化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你发现他有什么变化吗？", "target_word": "变化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，家乡发生了很大的变化。", "target_word": "变化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近他的变化让大家吃惊。", "target_word": "变化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天到了，树叶的颜色有变化。", "target_word": "变化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没看出你的发型有什么变化。", "target_word": "变化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的价格每天都有变化。", "target_word": "变化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的身体变化很快。", "target_word": "变化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对变化，我们要慢慢适应。", "target_word": "变化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种变化", "label": "量词"}], "register": "中性", "sense_fingerprint": "事物和以前不同的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d952261-361f-4475-b6c1-65e9db11d94e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变化", "is_correct": true, "explanation": "正确：变化是名词，“这个城市的变化很大”说城市发生的改变大，搭配自然。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“很大”不用来形容颜色，颜色通常说深浅。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或动物的重量，不能用于城市。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人或动物的身体高度，不能说城市的身高。"}], "explanations": {"变化": "正确：变化是名词，“这个城市的变化很大”说城市发生的改变大，搭配自然。", "颜色": "搭配：“很大”不用来形容颜色，颜色通常说深浅。", "体重": "语义：体重指人或动物的重量，不能用于城市。", "身高": "体貌：身高指人或动物的身体高度，不能说城市的身高。"}, "sentence_index": 0, "correct_answer": "变化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两件衣服的变化很大，一件红一件蓝。", "explanation": "这里应该用〈差别〉。变化指事物跟以前相比不一样了；比较两件同时存在的东西的不同，要用差别。"}, {"text": "两人的变化很大，哥哥比弟弟高。", "explanation": "这里应该用〈差距〉。变化指前后的改变；比较两人身高、水平的高低，要用差距。"}, {"text": "这两本书的变化很大，一本是红色封面，一本是蓝色封面。", "explanation": "这里应该用〈区别〉。变化指前后的改变；比较两本书的不同之处要用区别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变化", "is_correct": true, "explanation": "正确：“看出……有什么变化”指发型的改变，变化是名词，搭配自然。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：发型没有味道，“味道”不与发型搭配，不能说“有什么味道”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音指声响，发型不能发出声音，与“看出”的对象不符。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重指身体的重量，不能用来描述发型。"}], "explanations": {"变化": "正确：“看出……有什么变化”指发型的改变，变化是名词，搭配自然。", "味道": "搭配：发型没有味道，“味道”不与发型搭配，不能说“有什么味道”。", "声音": "语义：声音指声响，发型不能发出声音，与“看出”的对象不符。", "体重": "体貌：体重指身体的重量，不能用来描述发型。"}, "sentence_index": 6, "correct_answer": "变化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两种方法的变化很明显：一种快，一种慢。", "explanation": "这里应该用〈差异〉。变化指事物跟以前相比不一样了；比较两种同时存在的方法之间的不同，要用差异。"}, {"text": "这两个地方的变化很大，气候大不一样。", "explanation": "这里应该用〈不同〉。变化指前后的改变；比较两个地方同时存在的差别，要用不同。"}, {"text": "两个孩子的变化很大，性格相差很远。", "explanation": "这里应该用〈反差〉。变化指前后的改变；比较两个孩子同时存在的性格差别，要用反差。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气有了一只变化。", "corrected_sentence": "天气有了一种变化。", "error_description": "错误形式：“一只变化”；正确形式：“一种变化”。“只”用于动物，“变化”应搭配量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "气温变化的大。", "corrected_sentence": "气温变化很大。", "error_description": "错误形式：“变化的大”；正确形式：“变化很大”。“的”不能放在“变化”和“大”之间，形容词“大”前应用程度副词“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
