INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24078, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情变化中一直存在的那个样子。", "primary_collocate": null, "pronunciation": "guī lǜ", "ipa": "kuei˥ ly˥˩", "syllable_count": 2, "sentences": [{"text": "学习汉字有自己的规律。", "target_word": "规律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家找到了天气变化的规律。", "target_word": "规律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春夏秋冬的变化有一定的规律。", "target_word": "规律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们发现词语的规律。", "target_word": "规律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先找出数字的规律，再做题。", "target_word": "规律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮的变化是有规律的。", "target_word": "规律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些数字有什么规律？", "target_word": "规律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民很懂得自然的规律。", "target_word": "规律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏有一个简单的规律。", "target_word": "规律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究地球运动的规律。", "target_word": "规律", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "规律性", "label": "复合"}, {"form": "自然规律", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物变化中一直存在的、可以找出来的固定样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffce3848-4e7c-4ec3-885e-673579ba7e56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规律", "is_correct": true, "explanation": "正确：“自己的规律”指学习汉字时有固定的方法和样子，与句意一致。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：学习汉字谈不上身高，“自己的身高”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”指人或物的重量，学习不能有体重。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“数量”指多少，不说“学习汉字有自己的数量”。"}], "explanations": {"规律": "正确：“自己的规律”指学习汉字时有固定的方法和样子，与句意一致。", "身高": "体貌：学习汉字谈不上身高，“自己的身高”说不通。", "体重": "体貌：“体重”指人或物的重量，学习不能有体重。", "数量": "搭配：“数量”指多少，不说“学习汉字有自己的数量”。"}, "sentence_index": 0, "correct_answer": "规律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路的规律很宽，车子开起来很舒服。", "explanation": "这里应该用〈宽度〉。规律指事物变化的固定样子，不能用来形容路的宽窄。"}, {"text": "学校制定了新的规律，全体同学都要学习。", "explanation": "这里应该用〈制度〉。规律是事物变化中固定的样子，不能制定；“制定”要搭配〈制度〉。"}, {"text": "他违反了国家的规律，被警察带走了。", "explanation": "这里应该用〈法律〉。规律指事物变化的固定样子，违反的是法律，不是规律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规律", "is_correct": true, "explanation": "正确：“有什么规律”问数字有没有固定的变化样子，与句意一致。"}, {"text": "心情", "is_correct": false, "explanation": "语义：数字没有心情，“有什么心情”说不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：数字没有性格，“性格”只能用于人。"}, {"text": "辩论", "is_correct": false, "explanation": "搭配：“辩论”指人之间的争论，不能对数字说“有什么辩论”。"}], "explanations": {"规律": "正确：“有什么规律”问数字有没有固定的变化样子，与句意一致。", "心情": "语义：数字没有心情，“有什么心情”说不通。", "性格": "语义：数字没有性格，“性格”只能用于人。", "辩论": "搭配：“辩论”指人之间的争论，不能对数字说“有什么辩论”。"}, "sentence_index": 6, "correct_answer": "规律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间教室的规律很亮，大家都很喜欢。", "explanation": "这里应该用〈光线〉。规律指事物变化的固定样子，不能用来形容房间的明暗。"}, {"text": "他脸上的规律很可怕，大家都不敢看他。", "explanation": "这里应该用〈表情〉。规律指事物变化的固定样子，不能用来形容脸上的神情。"}, {"text": "他的规律很大，一生气就摔东西。", "explanation": "这里应该用〈脾气〉。规律指事物变化的固定样子，不能用来形容人的脾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家找到了一只新的规律。", "corrected_sentence": "科学家找到了一个新的规律。", "error_description": "量词错误：“规律”应用量词“个”，不用“只”，应说“一个新的规律”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师讲了一张很有意思的规律。", "corrected_sentence": "老师讲了一个很有意思的规律。", "error_description": "量词错误：“规律”应用量词“个”，不用“张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
