INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24080, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情要遵守的规则。", "primary_collocate": null, "pronunciation": "fǎ zé", "ipa": "fa˨˩˦ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "排队是公共场所的基本法则。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个游戏都有自己的法则。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，比赛有比赛的法则，大家都要遵守。", "target_word": "法则", "complexity_tier": "T3", "furigana": "bàba shuō, bǐsài yǒu bǐsài de fǎzé, dàjiā dōu yào zūnshǒu", "sentence_source": "generated"}, {"text": "我们要先了解比赛的法则，再开始玩。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这家公司工作，要记住几条法则。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条法则很简单：不能迟到。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁破坏了法则，谁就要离开。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照这条法则做事，不会出错。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车有开车的法则，安全第一。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们一起定下了几条班级法则。", "target_word": "法则", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条法则", "label": "量词"}, {"form": "游戏法则", "label": "复合"}, {"form": "法則", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做事情要遵守的规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa298e6-cfcf-449f-90b9-c2a575b9f960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24080, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法则", "is_correct": true, "explanation": "正确。“基本法则”指公共场所应遵守的基本规则，与“排队”的语境相符。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是可以喝的东西，不是公共场所应遵守的规则。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是日子，不是可以作为“基本”准则的内容。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“基本”修饰的是准则、知识等抽象内容，不能说“基本身高”。"}], "explanations": {"法则": "正确。“基本法则”指公共场所应遵守的基本规则，与“排队”的语境相符。", "饮料": "语义：饮料是可以喝的东西，不是公共场所应遵守的规则。", "节日": "语义：节日是日子，不是可以作为“基本”准则的内容。", "身高": "搭配：“基本”修饰的是准则、知识等抽象内容，不能说“基本身高”。"}, "sentence_index": 0, "correct_answer": "法则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道汤的法则太咸了。", "explanation": "这里应该用〈味道〉。“太咸了”形容食物的味道，“法则”指做事要遵守的规则，不能用来形容汤。"}, {"text": "他用布擦法则。", "explanation": "这里应该用〈桌子〉。“擦”的对象是有形的物体，法则是抽象的规则，不能被擦。"}, {"text": "他把书放在法则上。", "explanation": "这里应该用〈书架〉。书可以放在书架上，法则不是可以放东西的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法则", "is_correct": true, "explanation": "正确。“破坏了法则”指违反规则，“谁就要离开”符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能被“破坏”后让人离开，句意不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“破坏”的对象应是可受损的事物，“时间”不能说“破坏了时间”（应说“浪费时间”）。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的暗像，不是可以被破坏并导致人离开的对象。"}], "explanations": {"法则": "正确。“破坏了法则”指违反规则，“谁就要离开”符合句意。", "月亮": "语义：月亮是天体，不能被“破坏”后让人离开，句意不通。", "时间": "搭配：“破坏”的对象应是可受损的事物，“时间”不能说“破坏了时间”（应说“浪费时间”）。", "影子": "语义：影子是光线形成的暗像，不是可以被破坏并导致人离开的对象。"}, "sentence_index": 6, "correct_answer": "法则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想去超市买些法则。", "explanation": "这里应该用〈水果〉。“买”的对象是可买卖的物品，法则是抽象的规则，不能买。"}, {"text": "我们终于爬上了法则。", "explanation": "这里应该用〈高山〉。“爬上”的对象是地形或建筑，法则不是可以爬的东西。"}, {"text": "他很会踢法则。", "explanation": "这里应该用〈足球〉。“踢”的对象是球类等实物，法则不能被踢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条法则已经改着了。", "corrected_sentence": "这条法则已经改了。", "error_description": "体标错误：表示已经完成的变化应用“了”，不能用“着”（“着”表示持续的动作或状态）。“改着了”应改为“改了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他遵守了所有个法则。", "corrected_sentence": "他遵守了所有的法则。", "error_description": "量词错误：“所有”修饰名词时应用助词“的”，不能用量词“个”。应说“所有的法则”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24082, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "运输", "is_correct": false, "explanation": "运输：指把货物从一地运到另一地，与“造”没有反义关系。"}, {"text": "驾驶", "is_correct": false, "explanation": "驾驶：指操纵车、船等交通工具，与“造”不构成反义。"}, {"text": "拆", "is_correct": true, "explanation": "拆：与“造”相对，指把造好的东西拆开、拆散，与“造出”意思相反。"}, {"text": "修理", "is_correct": false, "explanation": "修理：指使坏的东西恢复原状，与“造”不构成反义。"}], "correct_answer": "拆", "explanations": {"运输": "运输：指把货物从一地运到另一地，与“造”没有反义关系。", "驾驶": "驾驶：指操纵车、船等交通工具，与“造”不构成反义。", "拆": "拆：与“造”相对，指把造好的东西拆开、拆散，与“造出”意思相反。", "修理": "修理：指使坏的东西恢复原状，与“造”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24082, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "欣赏", "is_correct": false, "explanation": "欣赏：指喜爱地观看、品味，与“造”没有反义关系。"}, {"text": "拆解", "is_correct": true, "explanation": "拆解：与“造”相对，指把成品拆开分解，与“造出”意思相反。"}, {"text": "发送", "is_correct": false, "explanation": "发送：指把信息或物品送出去，与“造”没有反义关系。"}, {"text": "参观", "is_correct": false, "explanation": "参观：指到某处观看，与“造”没有反义关系。"}], "correct_answer": "拆解", "explanations": {"欣赏": "欣赏：指喜爱地观看、品味，与“造”没有反义关系。", "拆解": "拆解：与“造”相对，指把成品拆开分解，与“造出”意思相反。", "发送": "发送：指把信息或物品送出去，与“造”没有反义关系。", "参观": "参观：指到某处观看，与“造”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24082, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出或发明出以前没有的东西。", "primary_collocate": null, "pronunciation": "zào chū", "ipa": "tsɑʊ˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "爱迪生造出了第一盏电灯。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国工程师造出了新的高铁。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用纸造出一座小城市。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想造出一台会说话的机器。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家第一次造出了汽车。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们能造出比它更轻的车吗？", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用旧瓶子造出一盏小灯。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了十年，造出了一艘大船。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人造出过这样的机器。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司希望造出便宜的电动车。", "target_word": "造出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "造出了", "label": "完成体"}, {"form": "造出过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "造出：做出或发明出以前没有的新东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '772fca80-e265-4879-9a3c-3f993f58a8df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24082, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "造出", "is_correct": true, "explanation": "造出（zào chū）：正确答案，指做出或发明出以前没有的东西。"}, {"text": "照出", "is_correct": false, "explanation": "zhào（第四声）与 zào 声母不同（zh/z），意思是光线照射而显现出来。"}, {"text": "早出", "is_correct": false, "explanation": "zǎo（第三声）与 zào（第四声）声调不同，意思是早早出去。"}, {"text": "道出", "is_correct": false, "explanation": "dào 与 zào 声母不同（d/z），意思是用语言说出、表达出来。"}, {"text": "导出", "is_correct": false, "explanation": "dǎo 与 zào 声母和声调都不同，意思是引导出去，或导出数据。"}], "explanations": {"造出": "造出（zào chū）：正确答案，指做出或发明出以前没有的东西。", "照出": "zhào（第四声）与 zào 声母不同（zh/z），意思是光线照射而显现出来。", "早出": "zǎo（第三声）与 zào（第四声）声调不同，意思是早早出去。", "道出": "dào 与 zào 声母不同（d/z），意思是用语言说出、表达出来。", "导出": "dǎo 与 zào 声母和声调都不同，意思是引导出去，或导出数据。"}, "sentence_index": null, "correct_answer": "造出"}, "level_3": {"options": [{"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”只用于可吃之物，不能说“吃掉一盏电灯”。"}, {"text": "造出", "is_correct": true, "explanation": "造出：通过制作、发明做出以前没有的电灯，符合句意。"}, {"text": "唱出", "is_correct": false, "explanation": "语义：“唱出”指用声音表达，与做出电灯无关，句意不通。"}, {"text": "摘取", "is_correct": false, "explanation": "搭配：“摘取”用于果实、花朵等可摘之物，不能用于电灯。"}], "explanations": {"吃掉": "搭配：“吃掉”只用于可吃之物，不能说“吃掉一盏电灯”。", "造出": "造出：通过制作、发明做出以前没有的电灯，符合句意。", "唱出": "语义：“唱出”指用声音表达，与做出电灯无关，句意不通。", "摘取": "搭配：“摘取”用于果实、花朵等可摘之物，不能用于电灯。"}, "sentence_index": 0, "correct_answer": "造出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天文学家造出了一颗新星。", "explanation": "这里应该用〈发现〉。新星本来就存在，是被发现的，不是被造出的；造出指做出以前没有的东西。"}, {"text": "科学家造出了新品种的水稻。", "explanation": "这里应该用〈培育〉。造出用于人工制作的物品，动植物新品种要用培育。"}, {"text": "这位作家造出了一部新的长篇小说。", "explanation": "这里应该用〈创作〉。造出指做出具体物品，长篇小说这类作品要用创作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24082, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "造出", "is_correct": true, "explanation": "造出（zào chū）：正确答案，指做出或发明出以前没有的东西。"}, {"text": "凿出", "is_correct": false, "explanation": "záo（第二声）与 zào（第四声）声调不同，意思是用凿子凿出。"}, {"text": "奏出", "is_correct": false, "explanation": "zòu 与 zào 韵母不同（ou/ao），意思是演奏出（乐曲）。"}, {"text": "找出", "is_correct": false, "explanation": "zhǎo 与 zào 声母和声调都不同，意思是寻找并找到。"}], "explanations": {"造出": "造出（zào chū）：正确答案，指做出或发明出以前没有的东西。", "凿出": "záo（第二声）与 zào（第四声）声调不同，意思是用凿子凿出。", "奏出": "zòu 与 zào 韵母不同（ou/ao），意思是演奏出（乐曲）。", "找出": "zhǎo 与 zào 声母和声调都不同，意思是寻找并找到。"}, "sentence_index": null, "correct_answer": "造出"}, "level_3": {"options": [{"text": "啃", "is_correct": false, "explanation": "搭配：“啃”指咬食物，不能说“啃出一盏小灯”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洁，不指用材料做出物件，句意不通。"}, {"text": "造出", "is_correct": true, "explanation": "造出：用旧瓶子做出一盏小灯，符合句意。"}, {"text": "吞掉", "is_correct": false, "explanation": "搭配：“吞掉”只用于可吞之物，不能说“吞掉一盏小灯”。"}], "explanations": {"啃": "搭配：“啃”指咬食物，不能说“啃出一盏小灯”。", "洗": "语义：“洗”指清洁，不指用材料做出物件，句意不通。", "造出": "造出：用旧瓶子做出一盏小灯，符合句意。", "吞掉": "搭配：“吞掉”只用于可吞之物，不能说“吞掉一盏小灯”。"}, "sentence_index": 6, "correct_answer": "造出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他造出了很多朋友。", "explanation": "这里应该用〈交〉。造出指做出具体的东西，人际关系要用交，不能说“造出朋友”。"}, {"text": "她造出了一身的伤。", "explanation": "这里应该用〈受〉。伤是受来的，造出指做出具体的东西，不能用于伤害。"}, {"text": "这部电影造出了很多人的眼泪。", "explanation": "这里应该用〈赚走〉。“赚走眼泪”是固定说法；造出指做出以前没有的具体东西，不能用于眼泪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家终于把造出了一台能治病的新机器。", "corrected_sentence": "科学家终于造出了一台能治病的新机器。", "error_description": "句式错误：「把」字句须为「把＋宾语＋动词」，「造出」前不能加「把」，应删去「把」，说「终于造出了一台能治病的新机器」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师们还没造出了新的高铁。", "corrected_sentence": "工程师们还没造出新的高铁。", "error_description": "体标错误：「没（有）」否定「造出」时，动词后不能再加「了」。正确形式是「还没造出新的高铁」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
