INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24088, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大气层是包在地球外面的一层空气，它保护我们。", "primary_collocate": null, "pronunciation": "dà qì céng", "ipa": "ta˥˩ tɕʰi˥˩ tsʰɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "大气层在地球外面。", "target_word": "大气层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们生活在大气层里。", "target_word": "大气层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大气层里有我们要呼吸的空气。", "target_word": "大气层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大气层保护我们不受太阳伤害。", "target_word": "大气层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "离地面越高，大气层越薄。", "target_word": "大气层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了大气层。", "target_word": "大气层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大气层的上面是太空。", "target_word": "大气层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天气变化发生在大气层里。", "target_word": "大气层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "污染让大气层变脏了。", "target_word": "大气层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家研究地球的大气层。", "target_word": "大气层", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "包在地球外面、保护我们的空气层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa298e6-cfcf-449f-90b9-c2a575b9f960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24088, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大气层", "is_correct": true, "explanation": "正确：大气层位于地球外面，正是句子所描述的位置。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不会位于地球外面，与句子的空间位置不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "配价：“在……外面”需要能处于某一位置的主体，冰箱是家用电器，一般说“放在……”，不说在地球外面。"}, {"text": "地下室", "is_correct": false, "explanation": "语义：地下室位于地下，与“地球外面”的位置正相反。"}], "explanations": {"大气层": "正确：大气层位于地球外面，正是句子所描述的位置。", "课本": "语义：课本是书，不会位于地球外面，与句子的空间位置不符。", "冰箱": "配价：“在……外面”需要能处于某一位置的主体，冰箱是家用电器，一般说“放在……”，不说在地球外面。", "地下室": "语义：地下室位于地下，与“地球外面”的位置正相反。"}, "sentence_index": 0, "correct_answer": "大气层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "房间里的大气层很新鲜。", "explanation": "这里应该用〈空气〉。大气层指包在地球外面的整层气体，房间里的空气不能称为大气层。"}, {"text": "我们头顶上有一座大气层。", "explanation": "这里应该用〈层〉。大气层是一层气体，量词要用〈层〉；〈座〉用于山、楼等大型物体，不能称量大气层。"}, {"text": "妈妈把大气层装进瓶子里，放在桌上。", "explanation": "这里应该用〈空气〉。大气层是包在地球外面的整层空气，不能装进瓶子里；瓶子里只能装一些空气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大气层", "is_correct": true, "explanation": "正确：大气层在地球之上，其上面才是太空，句意通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子的上面是天花板，不会是太空，与句子描述的地球外围结构不符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是建筑内部的空间，它的上面是屋顶，不是太空。"}, {"text": "水井", "is_correct": false, "explanation": "搭配：“……的上面是太空”要求主语是包裹地球的层次，水井是地面上的深洞，不能这样说。"}], "explanations": {"大气层": "正确：大气层在地球之上，其上面才是太空，句意通顺。", "桌子": "语义：桌子的上面是天花板，不会是太空，与句子描述的地球外围结构不符。", "教室": "语义：教室是建筑内部的空间，它的上面是屋顶，不是太空。", "水井": "搭配：“……的上面是太空”要求主语是包裹地球的层次，水井是地面上的深洞，不能这样说。"}, "sentence_index": 6, "correct_answer": "大气层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在大气层上种庄稼。", "explanation": "这里应该用〈地面〉。种庄稼要在土地上进行，大气层是包围地球的气体层，不能用来种植。"}, {"text": "考古学家在大气层挖掘文物。", "explanation": "这里应该用〈地下〉。挖掘文物要在地下进行，大气层是气体层，不能被挖掘。"}, {"text": "我们每天喝干净的大气层。", "explanation": "这里应该用〈水〉。能喝的是液体，大气层是气体层，不能饮用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地球外面包着一座厚厚的大气层。", "corrected_sentence": "地球外面包着一层厚厚的大气层。", "error_description": "量词错误：大气层是一层气体，应用量词“层”，不能用“座”。错误句中的“一座”应改为“一层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地球周围有大气层们。", "corrected_sentence": "地球周围有大气层。", "error_description": "词尾错误：“们”只能加在指人的名词或代词后面，“大气层”是无生命的名词，不能加“们”。错误句中的“大气层们”应改为“大气层”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
