INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24090, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究东西怎么动和为什么动的学问。", "primary_collocate": null, "pronunciation": "dòng lì xué", "ipa": "tʊŋ˥˩ li˥˩ ɕɥɛ˧˥", "syllable_count": 3, "sentences": [{"text": "动力学研究东西怎么动。", "target_word": "动力学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "球为什么会滚，动力学可以解释。", "target_word": "动力学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥大学学的是动力学。", "target_word": "动力学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "动力学告诉我们物体为什么会动。", "target_word": "动力学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想知道车怎么跑，要学动力学。", "target_word": "动力学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在课上讲了动力学的基本知识。", "target_word": "动力学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "动力学能解释苹果为什么往下掉。", "target_word": "动力学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书讲的是动力学，不是电学。", "target_word": "动力学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王对动力学很感兴趣。", "target_word": "动力学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学动力学要懂数学和物理。", "target_word": "动力学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "学问：研究物体怎么动、为什么动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9032895-3c87-4536-a6ce-a44d1ddecd4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24090, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史", "is_correct": false, "explanation": "语义：历史研究过去的事件，不研究东西怎么动。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是大气现象，不研究物体怎么动。"}, {"text": "动力学", "is_correct": true, "explanation": "正确：“动力学”是研究东西怎么动和为什么动的学问，符合“___研究东西怎么动”的语境。"}, {"text": "小把戏", "is_correct": false, "explanation": "语域：“小把戏”是口语，带轻视意味，不适合作学问的名称。"}], "explanations": {"历史": "语义：历史研究过去的事件，不研究东西怎么动。", "天气": "语义：天气是大气现象，不研究物体怎么动。", "动力学": "正确：“动力学”是研究东西怎么动和为什么动的学问，符合“___研究东西怎么动”的语境。", "小把戏": "语域：“小把戏”是口语，带轻视意味，不适合作学问的名称。"}, "sentence_index": 0, "correct_answer": "动力学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "动力学只研究东西怎么动，不管为什么动。", "explanation": "这里应该用〈运动学〉。运动学只研究东西怎么动，不管为什么动；“动力学”还研究东西为什么动，不能说它不管为什么动。"}, {"text": "这台机器的动力学很足。", "explanation": "这里应该用〈动力〉。“动力”指机器输出的力量，“动力学”是研究运动规律的学问，不能用来形容机器。"}, {"text": "动力学表示一个动作。", "explanation": "这里应该用〈动词〉。“动词”表示动作，“动力学”是研究东西怎么动和为什么动的学问，不表示动作，应说“动词”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "童话", "is_correct": false, "explanation": "语义：童话是虚构的故事，不能解释物体下落的原因。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵是植物的器官，不能解释物体下落的原因。"}, {"text": "动力学", "is_correct": true, "explanation": "正确：“动力学”研究东西为什么会动，能解释苹果为什么往下掉。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语，指传闻，不能用来解释科学现象。"}], "explanations": {"童话": "语义：童话是虚构的故事，不能解释物体下落的原因。", "花朵": "语义：花朵是植物的器官，不能解释物体下落的原因。", "动力学": "正确：“动力学”研究东西为什么会动，能解释苹果为什么往下掉。", "八卦": "语域：“八卦”是口语，指传闻，不能用来解释科学现象。"}, "sentence_index": 6, "correct_answer": "动力学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "动力学研究静止的物体，不研究运动。", "explanation": "这里应该用〈静力学〉。静力学研究静止物体的受力，“动力学”研究东西怎么动、为什么动，与“不研究运动”相矛盾。"}, {"text": "动力学研究能量与热的转化。", "explanation": "这里应该用〈热力学〉。热力学研究能量与热的转化，“动力学”研究东西怎么动，不研究热。"}, {"text": "动力学研究光的传播和反射。", "explanation": "这里应该用〈光学〉。光学研究光的传播与反射，“动力学”研究东西怎么动、为什么动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于弄了懂动力学。", "corrected_sentence": "他终于弄懂了动力学。", "error_description": "补语位置错误：“弄懂”是结果补语，“了”应放在“懂”之后，说“弄懂了动力学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我学了过动力学。", "corrected_sentence": "我学过动力学。", "error_description": "时态标记错误：“过”表示经历，不能与“了”同时用在同一个动词后，应说“学过动力学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
