INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24092, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "应用就是把知识、方法、技术或材料等用到实际的事情上。", "primary_collocate": null, "pronunciation": "yìng yòng", "ipa": "iŋ˥˩ yʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师教我们把学到的知识应用到生活中。", "target_word": "应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新方法已经应用在很多学校里。", "target_word": "应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要学会应用所学的知识。", "target_word": "应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这个办法应用到了工作中。", "target_word": "应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项技术可以应用在医院里。", "target_word": "应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了语法以后，要在写作中应用它。", "target_word": "应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师把新方法应用到做菜上。", "target_word": "应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方法很简单，大家都能应用到自己的学习中。", "target_word": "应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他应用了老师教的办法，很快做好了。", "target_word": "应用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料应用在房子上很安全。", "target_word": "应用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "应用了", "label": "体标"}, {"form": "应用过", "label": "体标"}, {"form": "应用程序", "label": "复合"}, {"form": "應用", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把知识、方法、技术等拿来使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c53470-eab2-4aaa-a8c7-536b79bbc5b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24092, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讨论", "is_correct": false, "explanation": "语义：讨论是交换意见，不能把知识“讨论”到生活中。"}, {"text": "忘记", "is_correct": false, "explanation": "配价：“忘记”不能带“到生活中”这样的处所补语，句子说不通。"}, {"text": "应用", "is_correct": true, "explanation": "正确：“应用”指把知识、方法拿来用，这里是把学到的知识用到生活中。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔到”指丢掉，不能说把知识扔到生活中。"}], "explanations": {"讨论": "语义：讨论是交换意见，不能把知识“讨论”到生活中。", "忘记": "配价：“忘记”不能带“到生活中”这样的处所补语，句子说不通。", "应用": "正确：“应用”指把知识、方法拿来用，这里是把学到的知识用到生活中。", "扔": "搭配：“扔到”指丢掉，不能说把知识扔到生活中。"}, "sentence_index": 0, "correct_answer": "应用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去那家公司应用了一份工作。", "explanation": "这里应该用〈申请〉。“应用”指把东西或方法拿来用，不能用来表示向公司提出申请。"}, {"text": "他每天都应用筷子吃饭。", "explanation": "这里应该用〈用〉。“应用”多指把方法、知识用在某事上，拿筷子吃饭要说“用”。"}, {"text": "他应用空闲时间看书。", "explanation": "这里应该用〈利用〉。“应用”指把方法、知识用于某事，“空闲时间”要说“利用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切", "is_correct": false, "explanation": "语义：切的对象是具体的东西，不能“切”方法。"}, {"text": "吃", "is_correct": false, "explanation": "语义：方法不能吃，“吃到做菜上”说不通。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂到”指挂在某处，不用于把方法用在做菜上。"}, {"text": "应用", "is_correct": true, "explanation": "正确：“应用到做菜上”指把新方法拿来用在做菜上。"}], "explanations": {"切": "语义：切的对象是具体的东西，不能“切”方法。", "吃": "语义：方法不能吃，“吃到做菜上”说不通。", "挂": "搭配：“挂到”指挂在某处，不用于把方法用在做菜上。", "应用": "正确：“应用到做菜上”指把新方法拿来用在做菜上。"}, "sentence_index": 6, "correct_answer": "应用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "面对这么多工作，他一个人应用不过来。", "explanation": "这里应该用〈应付〉。“应用”指把东西拿来用，不能表示应对、处理事情，那要说“应付”。"}, {"text": "他应用小刀削苹果。", "explanation": "这里应该用〈用〉。“应用”多用于方法、知识，拿工具来用要说“用”。"}, {"text": "他会应用汽车。", "explanation": "这里应该用〈驾驶〉。“应用”指把方法、知识用于某事，不能用来指开车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把学到的方法应用了到写作中。", "corrected_sentence": "她把学到的方法应用到了写作中。", "error_description": "“了”位置错了：应说“应用到了”，“了”放在“到”后面；不能说“应用了到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方法能应用农业上。", "corrected_sentence": "这个方法能应用到农业上。", "error_description": "缺少“到”：“应用”后面接处所时要说“应用到……上”，应说“应用到农业上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
