INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24096, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这是关于造飞机和飞船的学问。", "primary_collocate": null, "pronunciation": "háng kōng gōng chéng", "ipa": "xɑŋ˧˥ kʰʊŋ˥˥ kʊŋ˥˥ ʈʂʰɤŋ˧˥", "syllable_count": 4, "sentences": [{"text": "航空工程是造飞机的学问。", "target_word": "航空工程", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我对航空工程很有兴趣。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在学校里学航空工程，想造飞机。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学好航空工程，要先学好数学。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "航空工程不只研究飞机，也研究飞船。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的老师是航空工程的专家。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说航空工程专业的学生都很忙。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想用航空工程的知识设计新飞机。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书介绍了航空工程的历史。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做航空工程研究的人，常常去看飞机。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "关于制造飞机、飞船的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '427906b5-fb0b-4248-ba62-52818e8c3b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24096, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "航空工程", "is_correct": true, "explanation": "航空工程：造飞机、飞船的学问，与「造飞机的学问」相符。"}, {"text": "园艺", "is_correct": false, "explanation": "语义：园艺是种植花卉果蔬的技艺，不是造飞机的学问。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做菜的技艺，与「造飞机」的语境不符。"}, {"text": "航空公司", "is_correct": false, "explanation": "搭配：「是……的学问」要接学科名，「航空公司」是机构，不能作「学问」。"}], "explanations": {"航空工程": "航空工程：造飞机、飞船的学问，与「造飞机的学问」相符。", "园艺": "语义：园艺是种植花卉果蔬的技艺，不是造飞机的学问。", "烹饪": "语义：烹饪是做菜的技艺，与「造飞机」的语境不符。", "航空公司": "搭配：「是……的学问」要接学科名，「航空公司」是机构，不能作「学问」。"}, "sentence_index": 0, "correct_answer": "航空工程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在航空工程的候机厅里等了两个小时。", "explanation": "这里应该用〈机场〉。机场是候机、登机的场所；航空工程是学科，不是可以等候的地点。"}, {"text": "航空工程每天安排很多航班。", "explanation": "这里应该用〈航空公司〉。航空公司负责运营航班；航空工程是学科，不负责运营航班。"}, {"text": "航空工程需要定期体检。", "explanation": "这里应该用〈飞行员〉。飞行员是人，要定期体检；航空工程是学科，不能体检。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "航空工程", "is_correct": true, "explanation": "航空工程：是学科名称，可以用作「专业」的修饰语，与语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「专业」前要接学科名，「天气」不能作专业名。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：「专业」前要接学科名，「水果」不是学科，不能说「水果专业」。"}, {"text": "航空器", "is_correct": false, "explanation": "语义：航空器指飞机等实体，不是学科，不能作专业名。"}], "explanations": {"航空工程": "航空工程：是学科名称，可以用作「专业」的修饰语，与语境相符。", "天气": "搭配：「专业」前要接学科名，「天气」不能作专业名。", "水果": "搭配：「专业」前要接学科名，「水果」不是学科，不能说「水果专业」。", "航空器": "语义：航空器指飞机等实体，不是学科，不能作专业名。"}, "sentence_index": 6, "correct_answer": "航空工程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在大学里认识了一个航空工程，两人常一起吃饭。", "explanation": "这里应该用〈同学〉。同学是人；航空工程是学科，不能用来指人。"}, {"text": "航空工程是一台能载人飞行的机器。", "explanation": "这里应该用〈航空器〉。航空器是能载人飞行的机器；航空工程是学科和技术领域，不是机器。"}, {"text": "航空工程每年都要检修。", "explanation": "这里应该用〈飞机〉。飞机是实体，需要检修；航空工程是学科，不能检修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究航空工程人越来越多。", "corrected_sentence": "研究航空工程的人越来越多。", "error_description": "「研究航空工程人」应为「研究航空工程的人」：定语「研究航空工程」修饰「人」时，后面要加「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "航空工程是一门很难地学问。", "corrected_sentence": "航空工程是一门很难的学问。", "error_description": "「很难地学问」应为「很难的学问」：「很难」修饰名词「学问」作定语，要用「的」，「地」只修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
