INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "阳光照在飞机地机翼上。", "corrected_sentence": "阳光照在飞机的机翼上。", "error_description": "结构助词错误：“飞机”修饰“机翼”时应用结构助词“的”，说“飞机的机翼上”；“地”多用于修饰动词，此处误用，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人给飞机的两本机翼都刷了漆。", "corrected_sentence": "工人给飞机的两个机翼都刷了漆。", "error_description": "量词错误：“本”用于书本，不能修饰“机翼”，应说“两个机翼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24104, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "犹豫", "is_correct": true, "explanation": "正确：“犹豫”与“决定”意思相反，一个是拿不定主意，一个是拿定主意。"}, {"text": "修理", "is_correct": false, "explanation": "与“决定”没有反义关系：“修理”指修复损坏的东西。"}, {"text": "保存", "is_correct": false, "explanation": "与“决定”没有反义关系：“保存”指把东西留存下来。"}, {"text": "观察", "is_correct": false, "explanation": "与“决定”没有反义关系：“观察”指仔细看并研究。"}], "correct_answer": "犹豫", "explanations": {"犹豫": "正确：“犹豫”与“决定”意思相反，一个是拿不定主意，一个是拿定主意。", "修理": "与“决定”没有反义关系：“修理”指修复损坏的东西。", "保存": "与“决定”没有反义关系：“保存”指把东西留存下来。", "观察": "与“决定”没有反义关系：“观察”指仔细看并研究。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
