INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24104, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里想好要做一件事，不再改变。", "primary_collocate": null, "pronunciation": "jué dìng", "ipa": "tɕyɛ˧˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我决定明年去北京学中文。", "target_word": "决定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他决定不吃肉了。", "target_word": "决定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你决定好去哪儿了吗？", "target_word": "决定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们决定周末一起去爬山。", "target_word": "决定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想了很久，才决定留在这个城市。", "target_word": "决定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他已经决定了，谁说也没用。", "target_word": "决定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我还没决定要不要买这件衣服。", "target_word": "决定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王决定每天早上六点起床跑步。", "target_word": "决定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很多次决定要戒烟，可是都没做到。", "target_word": "决定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都同意，所以老师决定明天开会。", "target_word": "决定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "决定了", "label": "体标"}, {"form": "决定过", "label": "体标"}, {"form": "决定权", "label": "复合"}], "register": "中性", "sense_fingerprint": "经过考虑后确定要做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22aa5821-43c2-4f1a-bd68-eccc7ce09b8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24104, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "决定", "is_correct": true, "explanation": "正确：“决定”后面接要做的事，与“明年去北京学中文”相符。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”不能表示拿定主意去做某事，句子意思不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能带“明年去北京学中文”这样的内容。"}, {"text": "擦", "is_correct": false, "explanation": "配价：“擦”只能带具体物体作宾语，不能带动词短语。"}], "explanations": {"决定": "正确：“决定”后面接要做的事，与“明年去北京学中文”相符。", "写": "语义：“写”不能表示拿定主意去做某事，句子意思不通。", "吃": "语义：“吃”不能带“明年去北京学中文”这样的内容。", "擦": "配价：“擦”只能带具体物体作宾语，不能带动词短语。"}, "sentence_index": 0, "correct_answer": "决定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生决定了病人的眼睛。", "explanation": "这里应该用〈治疗〉。“治疗”指给病人看病、用药，“决定”是拿主意，不能用于眼睛这类身体部位。"}, {"text": "这个词的决定很简单。", "explanation": "这里应该用〈定义〉。“定义”是对词义的解释；“决定”是拿主意，不能用来指词的意思。"}, {"text": "护士决定了病人的心跳。", "explanation": "这里应该用〈测量〉。“测量”指用仪器量出数值；“决定”是拿主意，不能用于心跳这类生理数值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "决定", "is_correct": true, "explanation": "正确：“决定”表示拿主意，与“还没决定要不要买这件衣服”相符。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指搬动物体，不能带“要不要买这件衣服”的内容。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”针对喜事，与“要不要买衣服”不搭。"}, {"text": "生气", "is_correct": false, "explanation": "配价：“生气”是不及物动词，不能带“要不要买”这样的选择结构作宾语。"}], "explanations": {"决定": "正确：“决定”表示拿主意，与“还没决定要不要买这件衣服”相符。", "搬": "语义：“搬”指搬动物体，不能带“要不要买这件衣服”的内容。", "庆祝": "语义：“庆祝”针对喜事，与“要不要买衣服”不搭。", "生气": "配价：“生气”是不及物动词，不能带“要不要买”这样的选择结构作宾语。"}, "sentence_index": 6, "correct_answer": "决定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "阳光决定了房间。", "explanation": "这里应该用〈照亮〉。“照亮”指光线使地方变亮；“决定”是心里想好要做的事，不能用阳光作主语。"}, {"text": "我每年决定一份杂志。", "explanation": "这里应该用〈订阅〉。“订阅”指定期购买报刊，“决定”后面不接报刊这类物品。"}, {"text": "消防员决定了大火。", "explanation": "这里应该用〈扑灭〉。“扑灭”指把火弄灭；“决定”是拿主意，不能用于大火这类事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈了决定把旧房子卖掉。", "corrected_sentence": "妈妈决定把旧房子卖掉。", "error_description": "“了”表示完成，应放在动词之后，不能放在“决定”前面。正确是“妈妈决定把旧房子卖掉”，错误是“妈妈了决定把旧房子卖掉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他还没决定了去不去。", "corrected_sentence": "他还没决定去不去。", "error_description": "“没”否定动作已经发生，后面的“决定”不能再带“了”。正确是“没决定”，错误是“没决定了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
