INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24106, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "最根本的，做其他事情都要用到的。", "primary_collocate": null, "pronunciation": "jī běn", "ipa": "tɕi⁵⁵ pən²¹⁴", "syllable_count": 2, "sentences": [{"text": "学汉语要先学好基本的词。", "target_word": "基本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是做人的基本道理。", "target_word": "基本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳的基本动作很简单。", "target_word": "基本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭睡觉是每个人的基本需要。", "target_word": "基本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先教我们基本的写字方法。", "target_word": "基本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题只用到基本的数学知识。", "target_word": "基本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请遵守最基本的规则。", "target_word": "基本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做菜要先学会最基本的方法。", "target_word": "基本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子要有基本的礼貌。", "target_word": "基本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些是开车必须知道的基本知识。", "target_word": "基本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "基本上", "label": "复合"}, {"form": "基本功", "label": "复合"}], "register": "中性", "sense_fingerprint": "基本：形容词，最根本的、做别的事都要用到的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48420b25-8f0d-4c8e-9a02-21c20436390e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基本", "is_correct": true, "explanation": "“基本”指最根本的，修饰“词”，符合句意。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能修饰“词”。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”形容人的心情，不能说“高兴的词”。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”指形状，不能修饰“词”。"}], "explanations": {"基本": "“基本”指最根本的，修饰“词”，符合句意。", "聪明": "语义：“聪明”形容人的智力，不能修饰“词”。", "高兴": "搭配：“高兴”形容人的心情，不能说“高兴的词”。", "圆": "语义：“圆”指形状，不能修饰“词”。"}, "sentence_index": 0, "correct_answer": "基本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥的基本很牢固。", "explanation": "这里应该用〈基础〉。基本不能作名词指建筑的根基，建筑的底部要说基础。"}, {"text": "我们的基本在山上。", "explanation": "这里应该用〈基地〉。基本没有指地点的意思，驻扎或作业的场所要说基地。"}, {"text": "他是我们团队的基本。", "explanation": "这里应该用〈骨干〉。基本不能指人，团队中起核心作用的人要说骨干。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基本", "is_correct": true, "explanation": "“基本”指最根本的，修饰“规则”，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，不能修饰“规则”。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”形容环境或人的状态，不能说“安静的规则”。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地，不能修饰“规则”。"}], "explanations": {"基本": "“基本”指最根本的，修饰“规则”，符合句意。", "甜": "语义：“甜”形容味道，不能修饰“规则”。", "安静": "搭配：“安静”形容环境或人的状态，不能说“安静的规则”。", "柔软": "语义：“柔软”形容质地，不能修饰“规则”。"}, "sentence_index": 6, "correct_answer": "基本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个数的基本是三。", "explanation": "这里应该用〈底数〉。基本没有数学中“底数”的意思，乘方中作底的数要说底数。"}, {"text": "妈妈让我去商店买一斤基本。", "explanation": "这里应该用〈鸡蛋〉。基本是形容词，不能指能买的东西。"}, {"text": "我把基本放在桌子上。", "explanation": "这里应该用〈底座〉。基本没有承托物体的意思，东西下面承托的部分要说底座。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方法很很基本，大家都会。", "corrected_sentence": "这个方法很基本，大家都会。", "error_description": "程度副词重复：“很”只用一次，不能说“很很”修饰形容词“基本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个非常基本问题。", "corrected_sentence": "这是一个非常基本的问题。", "error_description": "缺少“的”：“非常基本”是带程度副词的形容词短语，修饰名词“问题”时后面要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
