INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24108, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个东西互相影响。", "primary_collocate": null, "pronunciation": "xiāng hù zuò yòng", "ipa": "ɕjɑŋ˥ xu˥˩ tsuo˥˩ jʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "两块磁铁会相互作用。", "target_word": "相互作用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "太阳和行星相互作用。", "target_word": "相互作用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这两种药不能一起吃，会相互作用。", "target_word": "相互作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风和海水相互作用，形成了海浪。", "target_word": "相互作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "身体和心理常常相互作用。", "target_word": "相互作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验里的两种液体相互作用后变色了。", "target_word": "相互作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "带电的东西靠近时会相互作用。", "target_word": "相互作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地球和月亮一直在相互作用。", "target_word": "相互作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把两种化学品放在一起，它们会相互作用。", "target_word": "相互作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，大气和海洋会相互作用。", "target_word": "相互作用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "相互作用着", "label": "体标"}, {"form": "相互作用力", "label": "复合"}], "register": "中性", "sense_fingerprint": "两个东西互相影响，动词用法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0613f2b4-d7bd-4ccb-9ae8-298ca11c53e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相互作用", "is_correct": true, "explanation": "正确：两块磁铁会互相影响（吸引或排斥）。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：磁铁不会游泳，与句中的物理语境不合。"}, {"text": "生气", "is_correct": false, "explanation": "语义：磁铁没有情绪，不会生气。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：磁铁不会吃饭，与句中的物理语境不合。"}], "explanations": {"相互作用": "正确：两块磁铁会互相影响（吸引或排斥）。", "游泳": "语义：磁铁不会游泳，与句中的物理语境不合。", "生气": "语义：磁铁没有情绪，不会生气。", "吃饭": "语义：磁铁不会吃饭，与句中的物理语境不合。"}, "sentence_index": 0, "correct_answer": "相互作用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个消息对大家相互作用很大。", "explanation": "这里应该用〈影响〉。“相互作用”强调双方互相影响，这句只说消息对大家的单向影响。"}, {"text": "这种病会通过空气相互作用。", "explanation": "这里应该用〈传染〉。病从一个人传给另一个人是单方向的扩散，“相互作用”强调双方彼此影响，不能说病通过空气相互作用。"}, {"text": "他每天相互作用三个小时，练习钢琴。", "explanation": "这里应该用〈练习〉。“相互作用”指事物之间互相影响，不指个人反复练习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相互作用", "is_correct": true, "explanation": "正确：带电的东西靠近时会互相影响。"}, {"text": "冻结", "is_correct": false, "explanation": "搭配：“冻结”多搭配水、资产等，带电的东西不会被“冻结”。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：带电的东西不会唱歌，句子描述的是物理现象。"}, {"text": "生长", "is_correct": false, "explanation": "语义：带电的东西不会生长，与句中的语境不合。"}], "explanations": {"相互作用": "正确：带电的东西靠近时会互相影响。", "冻结": "搭配：“冻结”多搭配水、资产等，带电的东西不会被“冻结”。", "唱歌": "语义：带电的东西不会唱歌，句子描述的是物理现象。", "生长": "语义：带电的东西不会生长，与句中的语境不合。"}, "sentence_index": 6, "correct_answer": "相互作用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这件事相互作用很快。", "explanation": "这里应该用〈反应〉。“相互作用”强调双方互相影响，这句只是一方对事情的反应。"}, {"text": "老师对学生的提问相互作用很快。", "explanation": "这里应该用〈回应〉。回应是一方对另一方的答复，“相互作用”强调双方彼此影响。"}, {"text": "他为了穿上这双鞋，相互作用了半天。", "explanation": "这里应该用〈折腾〉。“相互作用”指事物之间互相影响，不用来形容一个人忙活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨水和土壤会相互作用土壤，改变土壤的性质。", "corrected_sentence": "雨水和土壤会相互作用，改变土壤的性质。", "error_description": "及物用法错误：“相互作用”不能直接带宾语，说“与土壤相互作用”或“会相互作用”，不能说“相互作用土壤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两种液体混合后会与相互作用，颜色慢慢变深。", "corrected_sentence": "两种液体混合后会相互作用，颜色慢慢变深。", "error_description": "介词误用：“相互作用”前不能加“与”，“与”需要带出对象（如“与X相互作用”），此处缺少对象。应说“会相互作用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
