INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24110, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做一件事能不能做成。", "primary_collocate": null, "pronunciation": "kě xíng xìng", "ipa": "kʰɤ˨˩˦ ɕiŋ˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这个计划的可行性很高。", "target_word": "可行性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先研究一下这个办法的可行性。", "target_word": "可行性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板问这个想法有没有可行性。", "target_word": "可行性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都在讨论这个方案的可行性。", "target_word": "可行性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法的可行性不大。", "target_word": "可行性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家论证了这个计划的可行性。", "target_word": "可行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先弄清楚这个计划的可行性，再决定要不要做。", "target_word": "可行性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开公司以前要先研究可行性。", "target_word": "可行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得这件事有可行性吗？", "target_word": "可行性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为钱不够，所以计划没有可行性。", "target_word": "可行性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "可行性报告", "label": "复合"}, {"form": "可行性研究", "label": "复合"}], "register": "书面", "sense_fingerprint": "名词：一件事能不能做成的可能程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b205cd2-e5b8-488e-969b-5b81b72010f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24110, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可行性", "is_correct": true, "explanation": "正确。“这个计划的可行性很高”表示计划能做成的可能性大。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不说“高”，不能说“颜色很高”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高只属于人或动物，计划没有身高。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：计划没有寿命，“寿命很高”不通。"}], "explanations": {"可行性": "正确。“这个计划的可行性很高”表示计划能做成的可能性大。", "颜色": "搭配：“颜色”不说“高”，不能说“颜色很高”。", "身高": "体貌：身高只属于人或动物，计划没有身高。", "寿命": "语义：计划没有寿命，“寿命很高”不通。"}, "sentence_index": 0, "correct_answer": "可行性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这顿饭的可行性很高，大家吃得很满意。", "explanation": "这里应该用〈味道〉。“可行性”指做得成不成，说饭好吃要用“味道”。"}, {"text": "这本书的可行性很高，值得一读。", "explanation": "这里应该用〈价值〉。“可行性”不用来评价书，书要说“价值”。"}, {"text": "这个孩子的可行性很高，将来一定有出息。", "explanation": "这里应该用〈潜力〉。“可行性”指做事能否做成，说孩子的发展前景要用“潜力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b707e52-d132-4454-90c2-19cc87727299') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可行性", "is_correct": true, "explanation": "正确。“可行性”指计划能否做成，要先弄清楚才能决定做不做。"}, {"text": "音量", "is_correct": false, "explanation": "语义：计划没有音量，与“要不要做”无关，句子不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重只属于人或动物，计划没有体重。"}, {"text": "气味", "is_correct": false, "explanation": "语义：计划没有气味，与“要不要做”无关，句子不通。"}], "explanations": {"可行性": "正确。“可行性”指计划能否做成，要先弄清楚才能决定做不做。", "音量": "语义：计划没有音量，与“要不要做”无关，句子不通。", "体重": "体貌：体重只属于人或动物，计划没有体重。", "气味": "语义：计划没有气味，与“要不要做”无关，句子不通。"}, "sentence_index": 6, "correct_answer": "可行性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的可行性很高，用了五年也没坏。", "explanation": "这里应该用〈可靠性〉。“可行性”指做得成不成，机器用久了不坏要说“可靠性”。"}, {"text": "这次活动参加的可行性很多。", "explanation": "这里应该用〈人数〉。“可行性”不用来说数量，人多要说“人数”。"}, {"text": "他的可行性很高，大家都喜欢他。", "explanation": "这里应该用〈人缘〉。“可行性”指做事能否做成，形容人的好感要说“人缘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b707e52-d132-4454-90c2-19cc87727299') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要先做一只可行性研究。", "corrected_sentence": "我们要先做一项可行性研究。", "error_description": "量词错误：“可行性研究”用“项”，不用“只”。正确的说法是“做一项可行性研究”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b707e52-d132-4454-90c2-19cc87727299') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "领导要求我们调查了这个方案的可行性。", "corrected_sentence": "领导要求我们调查这个方案的可行性。", "error_description": "“要求”之后的动作尚未发生，“调查”后不能加“了”。正确的说法是“要求我们调查这个方案的可行性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b707e52-d132-4454-90c2-19cc87727299') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
