INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24116, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "把两个东西放在一起看，找出不一样的地方。", "primary_collocate": null, "pronunciation": "xiāng bǐ zhī xià", "ipa": "ɕiaŋ˥ pi˨˩ ʈʂɻ̩˥ ɕia˥˩", "syllable_count": 4, "sentences": [{"text": "这两本书都不错，相比之下，红色的更有意思。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的房间很小，相比之下，朋友的房间大多了。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果五块一斤，相比之下，香蕉便宜一些。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走路去学校，相比之下，我骑车快多了。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天风很大，相比之下，昨天没有风。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐很高，相比之下，妹妹矮一点。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路很窄，相比之下，那条路宽多了。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里人很多，相比之下，河边安静得多。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我做的菜太咸了，相比之下，妈妈做的刚好。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李学了三年汉语，相比之下，我才学了三个月。", "target_word": "相比之下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "把两样东西放在一起比较，指出它们不同的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43abfa4c-343c-4bb7-89da-1317173c8205') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相比之下", "is_correct": true, "explanation": "相比之下：把两本书放在一起比较，指出红色的更有意思。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，句中是两本书的比较，不是因果关系。"}, {"text": "因而", "is_correct": false, "explanation": "语义：“因而”表示由此导致的结果，与比较两本书的语境不符。"}, {"text": "于是", "is_correct": false, "explanation": "搭配：“于是”承接前面的动作，后面不接表示比较的分句。"}], "explanations": {"相比之下": "相比之下：把两本书放在一起比较，指出红色的更有意思。", "因此": "语义：“因此”表示因果，句中是两本书的比较，不是因果关系。", "因而": "语义：“因而”表示由此导致的结果，与比较两本书的语境不符。", "于是": "搭配：“于是”承接前面的动作，后面不接表示比较的分句。"}, "sentence_index": 0, "correct_answer": "相比之下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他先吃午饭，相比之下去散步了。", "explanation": "这里应该用〈然后〉。前后是先后顺序，没有可以比较的对象，不用“相比之下”。"}, {"text": "天气很热，相比之下，我们决定在家吹空调。", "explanation": "这里应该用〈因此〉。前后是因果关系，没有比较两者。"}, {"text": "我去邮局，相比之下寄了一封信。", "explanation": "这里应该用〈顺便〉。寄信只是顺带做的事，不是比较两者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相比之下", "is_correct": true, "explanation": "相比之下：引出后一分句，与前面一条路窄的情况对比，指出另一条路更宽。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示并列或递进，前后一窄一宽，不能这样相接。"}, {"text": "从而", "is_correct": false, "explanation": "语义：“从而”表示由此达到的结果，与一窄一宽的对比不符。"}, {"text": "进而", "is_correct": false, "explanation": "语域：“进而”偏书面语，表示递进，与前后的对比关系不符。"}], "explanations": {"相比之下": "相比之下：引出后一分句，与前面一条路窄的情况对比，指出另一条路更宽。", "而且": "语义：“而且”表示并列或递进，前后一窄一宽，不能这样相接。", "从而": "语义：“从而”表示由此达到的结果，与一窄一宽的对比不符。", "进而": "语域：“进而”偏书面语，表示递进，与前后的对比关系不符。"}, "sentence_index": 6, "correct_answer": "相比之下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "相比之下，他先去了银行。", "explanation": "这里应该用〈首先〉。句首没有可以比较的前文，这里只是先后顺序。"}, {"text": "妈妈做完饭，相比之下，去叫爸爸吃饭。", "explanation": "这里应该用〈接着〉。前后是先后动作，不是比较两者。"}, {"text": "她连续熬夜，相比之下，生病了。", "explanation": "这里应该用〈结果〉。前后是因果关系，不是比较两者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家面包店很大，相比之下了，那家小多了。", "corrected_sentence": "这家面包店很大，相比之下，那家小多了。", "error_description": "词语后附错误：“相比之下”是连词，后面不能加“了”，应去掉“了”，写作“相比之下，”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跑得很快，相比之下的，我跑得慢多了。", "corrected_sentence": "他跑得很快，相比之下，我跑得慢多了。", "error_description": "词语后附错误：“相比之下”是连词，后面不能加“的”，应去掉“的”，写作“相比之下，”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24120, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "较小", "is_correct": true, "explanation": "正确。两者相比，“较小”与“较大”相对，指体积或数量较低的一个。"}, {"text": "清脆", "is_correct": false, "explanation": "“清脆”形容声音，与“较大”的比较义没有相对关系。"}, {"text": "直率", "is_correct": false, "explanation": "“直率”形容性格，与“较大”没有相对关系。"}, {"text": "珍贵", "is_correct": false, "explanation": "“珍贵”形容价值，与“较大”的比较义不构成反义。"}], "correct_answer": "较小", "explanations": {"较小": "正确。两者相比，“较小”与“较大”相对，指体积或数量较低的一个。", "清脆": "“清脆”形容声音，与“较大”的比较义没有相对关系。", "直率": "“直率”形容性格，与“较大”没有相对关系。", "珍贵": "“珍贵”形容价值，与“较大”的比较义不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24120, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "较小", "is_correct": true, "explanation": "正确。两者相比，“较小”与“较大”相对，指程度或数量较低的一个。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”形容心情或做事不费力，与“较大”没有相对关系。"}, {"text": "冷淡", "is_correct": false, "explanation": "“冷淡”形容态度，与“较大”的比较义不构成反义。"}, {"text": "干燥", "is_correct": false, "explanation": "“干燥”形容含水少，与“较大”没有相对关系。"}], "correct_answer": "较小", "explanations": {"较小": "正确。两者相比，“较小”与“较大”相对，指程度或数量较低的一个。", "轻松": "“轻松”形容心情或做事不费力，与“较大”没有相对关系。", "冷淡": "“冷淡”形容态度，与“较大”的比较义不构成反义。", "干燥": "“干燥”形容含水少，与“较大”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24120, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西比另一个更多、更大。", "primary_collocate": null, "pronunciation": "jiào dà", "ipa": "tɕjɑʊ˥˩ tɑ˥˩", "syllable_count": 2, "sentences": [{"text": "两个苹果里，我要较大的那个。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个箱子，较大的一个放书。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把较大的盘子拿给我。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟分到了较大的一块蛋糕。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了两条鱼，较大的一条做汤。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个西瓜里，较大的那个更甜。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两袋米，较大的那袋我来提。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架上的书，较大的放下层。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他选了两个包里较大的那个。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "较大的杯子给爸爸，较小的给我。", "target_word": "较大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "較大", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在两个事物中比较，指其中体积或数量更大的那一个，如“较大的那个”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0613f2b4-d7bd-4ccb-9ae8-298ca11c53e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "较大", "is_correct": true, "explanation": "正确。两个苹果相比，较大的那个就是体积更大的那个。"}, {"text": "较年轻", "is_correct": false, "explanation": "语义：苹果没有年龄，“较年轻的那个”与苹果不相配。"}, {"text": "较聪明", "is_correct": false, "explanation": "语义：苹果不具有智力，这一比较在句中不成立。"}, {"text": "较古老", "is_correct": false, "explanation": "语义：苹果不谈古老，“较古老的那个”不合语境。"}], "explanations": {"较大": "正确。两个苹果相比，较大的那个就是体积更大的那个。", "较年轻": "语义：苹果没有年龄，“较年轻的那个”与苹果不相配。", "较聪明": "语义：苹果不具有智力，这一比较在句中不成立。", "较古老": "语义：苹果不谈古老，“较古老的那个”不合语境。"}, "sentence_index": 0, "correct_answer": "较大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个碗，颜色较大的那个是我的。", "explanation": "这里应该用〈较深〉。颜色的深浅用“深”，“较大”不指颜色。"}, {"text": "两个孩子，性格较大的那个更爱说话。", "explanation": "这里应该用〈较外向〉。性格的倾向用“外向、内向”描述，“较大”不说性格。"}, {"text": "两个人练字，姿势较大的那个写得更好。", "explanation": "这里应该用〈较标准〉。姿势的规范程度用“标准”描述，“较大”不说姿势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较大", "is_correct": true, "explanation": "正确。两袋米相比，较大的那袋指体积或重量更大的一袋。"}, {"text": "较甜", "is_correct": false, "explanation": "语义：米袋不能用甜淡来区分，句中没有味道的语境。"}, {"text": "较年轻", "is_correct": false, "explanation": "语义：米袋没有年龄，“较年轻的那袋”不合语境。"}, {"text": "较热", "is_correct": false, "explanation": "语义：米袋在两者之间的比较不说冷热，“较热的那袋”不合语境。"}], "explanations": {"较大": "正确。两袋米相比，较大的那袋指体积或重量更大的一袋。", "较甜": "语义：米袋不能用甜淡来区分，句中没有味道的语境。", "较年轻": "语义：米袋没有年龄，“较年轻的那袋”不合语境。", "较热": "语义：米袋在两者之间的比较不说冷热，“较热的那袋”不合语境。"}, "sentence_index": 6, "correct_answer": "较大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两首歌，节奏较大的那首更好听。", "explanation": "这里应该用〈较快〉。节奏的快慢用“快、慢”描述，“较大”不说节奏。"}, {"text": "两个孩子，表情较大的那个很凶。", "explanation": "这里应该用〈较凶〉。表情用“凶、和”描述，“较大”不说表情。"}, {"text": "两块布，质地较大的那块是丝的。", "explanation": "这里应该用〈较软〉。质地的软硬用“软、硬”描述，“较大”不说质地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个盘子里，我要较大那个。", "corrected_sentence": "这两个盘子里，我要较大的那个。", "error_description": "“的”遗漏：“较大”修饰“那个”，中间要加结构助词“的”，应说“较大的那个”，不能直接说“较大那个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两只狗，很较大的那只叫得很响。", "corrected_sentence": "这两只狗，较大的那只叫得很响。", "error_description": "程度副词重复：“较大”已含比较程度，前面不能再加“很”，应说“较大的那只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
