INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24122, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "水流或空气流动的快慢。", "primary_collocate": null, "pronunciation": "liú sù", "ipa": "ljoʊ˧˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "这里的流速很慢，适合划船。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，河水的流速明显变快了。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气的流速越大，风就越强。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开窗户，室内空气的流速加快了。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼喜欢在流速慢的地方休息。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了看水面，判断出这里的流速。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水龙头开大一点，水的流速就快一些。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河中间的流速比岸边快。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山谷里空气的流速较快，风声很响。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流速不同，水声也不一样。", "target_word": "流速", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指水流或空气流动的快慢，如“流速很慢”“流速加快”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0613f2b4-d7bd-4ccb-9ae8-298ca11c53e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24122, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流速", "is_correct": true, "explanation": "正确：“流速”指水流或空气流动的快慢，“很慢”正符合此处的描述。"}, {"text": "水深", "is_correct": false, "explanation": "搭配：“水深”说深浅，不能与“很慢”搭配。"}, {"text": "流量", "is_correct": false, "explanation": "语义：“流量”指流过的量，不表示快慢，与“很慢”不相容。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”说冷热，不能说“很慢”。"}], "explanations": {"流速": "正确：“流速”指水流或空气流动的快慢，“很慢”正符合此处的描述。", "水深": "搭配：“水深”说深浅，不能与“很慢”搭配。", "流量": "语义：“流量”指流过的量，不表示快慢，与“很慢”不相容。", "温度": "搭配：“温度”说冷热，不能说“很慢”。"}, "sentence_index": 0, "correct_answer": "流速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆摩托车的流速每小时能达到一百公里。", "explanation": "这里应该用〈速度〉。流速只指水流或空气流动的快慢，摩托车的行驶快慢要用速度。"}, {"text": "这条管道每秒的流速是十升。", "explanation": "这里应该用〈流量〉。流速说的是流动的快慢，每秒流过多少体积要用流量。"}, {"text": "这台机器的流速提高了两成。", "explanation": "这里应该用〈效率〉。流速只指水流或空气流动的快慢，机器做事的好坏和快慢要用效率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流速", "is_correct": true, "explanation": "正确：水龙头开大后，水的流速会加快，“流速”指水流快慢。"}, {"text": "压力", "is_correct": false, "explanation": "语义：“压力”不能用“快一些”来形容。"}, {"text": "水量", "is_correct": false, "explanation": "搭配：“水量”说多少，不说“快”。"}, {"text": "水位", "is_correct": false, "explanation": "搭配：“水位”说高低，不能用“快一些”描述。"}], "explanations": {"流速": "正确：水龙头开大后，水的流速会加快，“流速”指水流快慢。", "压力": "语义：“压力”不能用“快一些”来形容。", "水量": "搭配：“水量”说多少，不说“快”。", "水位": "搭配：“水位”说高低，不能用“快一些”描述。"}, "sentence_index": 6, "correct_answer": "流速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑完步后，心跳的流速明显加快。", "explanation": "这里应该用〈心率〉。流速只指水流或空气流动的快慢，心跳的快慢要用心率。"}, {"text": "这次施工的流速比计划快。", "explanation": "这里应该用〈进度〉。流速只指水流或空气流动的快慢，工程推进的快慢要用进度。"}, {"text": "他说话的流速很快，大家听不清。", "explanation": "这里应该用〈语速〉。流速只指水流或空气流动的快慢，说话的快慢要用语速。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一段河的流速慢很，很适合划船。", "corrected_sentence": "这一段河的流速很慢，很适合划船。", "error_description": "状语位置错误：副词“很”修饰形容词“慢”，应放在“慢”之前说“流速很慢”，不能说“流速慢很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水从窄口流出时，流速明显快加了。", "corrected_sentence": "水从窄口流出时，流速明显加快了。", "error_description": "补语错误：“加快”是动词加结果补语，不能颠倒成“快加”，应说“流速明显加快了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24124, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "较快", "is_correct": true, "explanation": "「较快」与「较慢」在速度义项上互为反义。"}, {"text": "柔软", "is_correct": false, "explanation": "「柔软」形容质地，与「较慢」的速度义无关，不构成反义。"}, {"text": "厚重", "is_correct": false, "explanation": "「厚重」形容分量或质感，与「较慢」的速度义无关，不构成反义。"}, {"text": "清脆", "is_correct": false, "explanation": "「清脆」形容声音，与「较慢」的速度义无关，不构成反义。"}], "correct_answer": "较快", "explanations": {"较快": "「较快」与「较慢」在速度义项上互为反义。", "柔软": "「柔软」形容质地，与「较慢」的速度义无关，不构成反义。", "厚重": "「厚重」形容分量或质感，与「较慢」的速度义无关，不构成反义。", "清脆": "「清脆」形容声音，与「较慢」的速度义无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
