INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24124, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "速度比一般略慢一些，即速度不快。", "primary_collocate": null, "pronunciation": "jiào màn", "ipa": "tɕjɑʊ˥˩ man˥˩", "syllable_count": 2, "sentences": [{"text": "这辆车的速度较慢，我们可能会迟到。", "target_word": "较慢", "complexity_tier": "T3", "furigana": "zhè liàng chē de sùdù jiào màn, wǒmen kěnéng huì chídào。", "sentence_source": "generated"}, {"text": "妹妹吃饭的速度较慢，每次都最后吃完。", "target_word": "较慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天河水流动较慢，有的地方还结了冰。", "target_word": "较慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跑步的速度较慢，所以没有拿到奖。", "target_word": "较慢", "complexity_tier": "T3", "furigana": "wǒ pǎobù de sùdù jiào màn, suǒyǐ méiyǒu nádào jiǎng。", "sentence_source": "generated"}, {"text": "这家饭馆上菜较慢，客人要等二十分钟。", "target_word": "较慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写字的速度较慢，但是字写得很好看。", "target_word": "较慢", "complexity_tier": "T3", "furigana": "tā xiězì de sùdù jiào màn, dànshì zì xiě de hěn hǎokàn。", "sentence_source": "generated"}, {"text": "这个城市的生活节奏较慢，很适合老人。", "target_word": "较慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后路很滑，大家走路的速度都较慢。", "target_word": "较慢", "complexity_tier": "T3", "furigana": "yǔ hòu lù hěn huá, dàjiā zǒulù de sùdù dōu jiào màn。", "sentence_source": "generated"}, {"text": "我的手机反应较慢，该换新的了。", "target_word": "较慢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说话较慢，同学们都听得清楚。", "target_word": "较慢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "速度不快，相对一般而言稍慢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43abfa4c-343c-4bb7-89da-1317173c8205') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24124, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "较慢", "is_correct": true, "explanation": "较慢（jiào màn）指速度比一般略慢一些，即速度不快。"}, {"text": "叫卖", "is_correct": false, "explanation": "mài（第四声）与 màn（第四声）韵母不同，意思是沿街吆喝着卖东西。"}, {"text": "叫骂", "is_correct": false, "explanation": "mà 比 màn 少了鼻音 n，意思是大声骂人。"}, {"text": "浇满", "is_correct": false, "explanation": "jiāo（第一声）与 jiào（第四声）、mǎn（第三声）与 màn（第四声）声调不同，意思是把东西倒到满。"}, {"text": "娇蛮", "is_correct": false, "explanation": "jiāo 与 jiào、mán 与 màn 声调不同，意思是娇惯而蛮横。"}], "explanations": {"较慢": "较慢（jiào màn）指速度比一般略慢一些，即速度不快。", "叫卖": "mài（第四声）与 màn（第四声）韵母不同，意思是沿街吆喝着卖东西。", "叫骂": "mà 比 màn 少了鼻音 n，意思是大声骂人。", "浇满": "jiāo（第一声）与 jiào（第四声）、mǎn（第三声）与 màn（第四声）声调不同，意思是把东西倒到满。", "娇蛮": "jiāo 与 jiào、mán 与 màn 声调不同，意思是娇惯而蛮横。"}, "sentence_index": null, "correct_answer": "较慢"}, "level_3": {"options": [{"text": "较慢", "is_correct": true, "explanation": "「较慢」说车速比一般低，与「可能会迟到」的推论一致。"}, {"text": "较快", "is_correct": false, "explanation": "语义：车速「较快」就不容易迟到，与「我们可能会迟到」的推论相矛盾。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：「结实」形容物体坚固，不用来描述车速。"}, {"text": "宽阔", "is_correct": false, "explanation": "搭配：「宽阔」形容空间面积，不用来描述车速。"}], "explanations": {"较慢": "「较慢」说车速比一般低，与「可能会迟到」的推论一致。", "较快": "语义：车速「较快」就不容易迟到，与「我们可能会迟到」的推论相矛盾。", "结实": "搭配：「结实」形容物体坚固，不用来描述车速。", "宽阔": "搭配：「宽阔」形容空间面积，不用来描述车速。"}, "sentence_index": 0, "correct_answer": "较慢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的工资较慢，我买了一台新电脑。", "explanation": "这里应该用〈较高〉。「较慢」只说速度或频率，工资多少要用「较高」。"}, {"text": "他的成绩较慢，需要再努力。", "explanation": "这里应该用〈较差〉。「较慢」形容速度，成绩好坏要用「较差」。"}, {"text": "我家到学校的距离较慢，每天要走一个小时。", "explanation": "这里应该用〈较远〉。「较慢」不能形容距离，距离远近要用「较远」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较慢", "is_correct": true, "explanation": "「较慢」说城市节奏比一般慢，与「很适合老人」相呼应。"}, {"text": "紧张", "is_correct": false, "explanation": "语义：「紧张」与「很适合老人」相矛盾，节奏紧张并不适合老人。"}, {"text": "尖锐", "is_correct": false, "explanation": "搭配：「尖锐」形容棱角或声音，不用来描述生活节奏。"}, {"text": "轻巧", "is_correct": false, "explanation": "搭配：「轻巧」形容物体分量轻、灵便，不说生活节奏轻巧。"}], "explanations": {"较慢": "「较慢」说城市节奏比一般慢，与「很适合老人」相呼应。", "紧张": "语义：「紧张」与「很适合老人」相矛盾，节奏紧张并不适合老人。", "尖锐": "搭配：「尖锐」形容棱角或声音，不用来描述生活节奏。", "轻巧": "搭配：「轻巧」形容物体分量轻、灵便，不说生活节奏轻巧。"}, "sentence_index": 6, "correct_answer": "较慢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "参加比赛的人数较慢，只有十个人报名。", "explanation": "这里应该用〈较少〉。「较慢」形容速度，人数多少要用「较少」。"}, {"text": "我的体重较慢，所以需要多运动。", "explanation": "这里应该用〈较重〉。「较慢」只说速度或频率，体重轻重要用「较重」。"}, {"text": "我弟弟的年龄较慢，才十岁。", "explanation": "这里应该用〈较小〉。「较慢」不能形容年龄，年龄大小要用「较小」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种型号的电脑处理速度很较慢，所以我们换了一台。", "corrected_sentence": "这种型号的电脑处理速度较慢，所以我们换了一台。", "error_description": "「较慢」已含「较」表示程度，不能再受「很」修饰，应去掉「很」，写作「速度较慢」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家店的上菜速度较较慢，但是东西很好吃。", "corrected_sentence": "那家店的上菜速度较慢，但是东西很好吃。", "error_description": "重复错误：「较慢」中的「较」不能重复，应只保留一个「较」，写作「速度较慢」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24126, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好", "is_correct": true, "explanation": "正确：“好”与“差”构成反义，指字写得好、水平高。"}, {"text": "快", "is_correct": false, "explanation": "快：形容速度，与“差”不构成反义。"}, {"text": "大", "is_correct": false, "explanation": "大：形容大小，与“差”不构成反义。"}, {"text": "长", "is_correct": false, "explanation": "长：形容长短，与“差”不构成反义。"}], "correct_answer": "好", "explanations": {"好": "正确：“好”与“差”构成反义，指字写得好、水平高。", "快": "快：形容速度，与“差”不构成反义。", "大": "大：形容大小，与“差”不构成反义。", "长": "长：形容长短，与“差”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24126, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好", "is_correct": true, "explanation": "正确：“好”与“差”构成反义，指收成、质量良好。"}, {"text": "高", "is_correct": false, "explanation": "高：形容高低，与“差”不构成反义。"}, {"text": "远", "is_correct": false, "explanation": "远：形容距离，与“差”不构成反义。"}, {"text": "轻", "is_correct": false, "explanation": "轻：形容重量，与“差”不构成反义。"}], "correct_answer": "好", "explanations": {"好": "正确：“好”与“差”构成反义，指收成、质量良好。", "高": "高：形容高低，与“差”不构成反义。", "远": "远：形容距离，与“差”不构成反义。", "轻": "轻：形容重量，与“差”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24126, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不好，比如东西坏了或者做得不对。", "primary_collocate": null, "pronunciation": "chà", "ipa": "ʈʂʰɑ˥˩", "syllable_count": 1, "sentences": [{"text": "这台电脑太差了，老是死机。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的天气很差，我没出门。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的东西质量差，别买。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的字写得很差，我看不清。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的网络信号差，打不开视频。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天的心情很差。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋做得太差，才穿一天就坏了。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的记性差，常常忘事。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部手机的电池差，一天要充三次。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的收成很差，农民很担心。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容质量、状态或表现不好，如“质量差”“信号差”“心情差”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0613f2b4-d7bd-4ccb-9ae8-298ca11c53e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24126, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "差", "is_correct": true, "explanation": "正确：差 chà，表示质量或状态不好。"}, {"text": "茶", "is_correct": false, "explanation": "chá（第二声）与 chà（第四声）声调不同，意思是茶。"}, {"text": "查", "is_correct": false, "explanation": "chá（第二声）与 chà（第四声）声调不同，意思是检查。"}, {"text": "察", "is_correct": false, "explanation": "chá（第二声）与 chà（第四声）声调不同，意思是观察。"}], "explanations": {"差": "正确：差 chà，表示质量或状态不好。", "茶": "chá（第二声）与 chà（第四声）声调不同，意思是茶。", "查": "chá（第二声）与 chà（第四声）声调不同，意思是检查。", "察": "chá（第二声）与 chà（第四声）声调不同，意思是观察。"}, "sentence_index": null, "correct_answer": "差"}, "level_3": {"options": [{"text": "差", "is_correct": true, "explanation": "正确：“太差了”说明电脑质量不好，与“老是死机”相符。"}, {"text": "甜", "is_correct": false, "explanation": "语义：电脑的性能不能用“甜”来形容，“太甜了”说不通。"}, {"text": "圆", "is_correct": false, "explanation": "搭配：“圆”形容形状，不能用来形容电脑性能。"}, {"text": "香", "is_correct": false, "explanation": "搭配：“香”形容气味或味道，不能用来形容电脑质量。"}], "explanations": {"差": "正确：“太差了”说明电脑质量不好，与“老是死机”相符。", "甜": "语义：电脑的性能不能用“甜”来形容，“太甜了”说不通。", "圆": "搭配：“圆”形容形状，不能用来形容电脑性能。", "香": "搭配：“香”形容气味或味道，不能用来形容电脑质量。"}, "sentence_index": 0, "correct_answer": "差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身高很差，打篮球很有优势。", "explanation": "这里应该用〈高〉。“差”说质量或水平不好，身高的高低要用“高”或“矮”。"}, {"text": "他的年龄很差，已经退休了。", "explanation": "这里应该用〈大〉。“差”说质量或水平不好，年龄的多少要用“大”或“小”。"}, {"text": "他是我的长辈，辈分很差。", "explanation": "这里应该用〈高〉。“差”说质量不好，辈分的高低要用“高”或“低”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24126, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "差", "is_correct": true, "explanation": "正确：差 chà，表示质量或状态不好。"}, {"text": "插", "is_correct": false, "explanation": "chā（第一声）与 chà（第四声）声调不同，意思是插入。"}, {"text": "叉", "is_correct": false, "explanation": "chā（第一声）与 chà（第四声）声调不同，意思是叉子。"}, {"text": "茶", "is_correct": false, "explanation": "chá（第二声）与 chà（第四声）声调不同，意思是茶。"}], "explanations": {"差": "正确：差 chà，表示质量或状态不好。", "插": "chā（第一声）与 chà（第四声）声调不同，意思是插入。", "叉": "chā（第一声）与 chà（第四声）声调不同，意思是叉子。", "茶": "chá（第二声）与 chà（第四声）声调不同，意思是茶。"}, "sentence_index": null, "correct_answer": "差"}, "level_3": {"options": [{"text": "差", "is_correct": true, "explanation": "正确：“做得太差”说明鞋的做工不好，与“才穿一天就坏了”相符。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”形容光线，不能形容鞋的做工。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，不能形容鞋的做工。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：“冷”形容温度，不能说“做得太冷”。"}], "explanations": {"差": "正确：“做得太差”说明鞋的做工不好，与“才穿一天就坏了”相符。", "亮": "语义：“亮”形容光线，不能形容鞋的做工。", "咸": "语义：“咸”形容味道，不能形容鞋的做工。", "冷": "搭配：“冷”形容温度，不能说“做得太冷”。"}, "sentence_index": 6, "correct_answer": "差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有个差习惯，改起来很难。", "explanation": "这里应该用〈坏〉。“差”多用于质量、水平，习惯的好坏要用“坏”，不说“差习惯”。"}, {"text": "这块肉放了太久，已经差了，不能吃。", "explanation": "这里应该用〈坏〉。“差”说质量或水平不好，食物变质要说“坏了”。"}, {"text": "他又犯差了。", "explanation": "这里应该用〈错〉。“差”表示不好，不能说“犯差”，犯错要用“错”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的字这次写很差，老师没看清。", "corrected_sentence": "他的字这次写得很差，老师没看清。", "error_description": "补语错误：“写”后面的状态补语要用“得”，应说“写得很差”，不能说“写很差”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台打印机的质量差太，经常卡纸。", "corrected_sentence": "这台打印机的质量太差，经常卡纸。", "error_description": "语序错误：程度副词“太”应放在形容词“差”之前，应说“太差”，不能说“差太”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24128, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放慢", "is_correct": true, "explanation": "正确：放慢与加快意义相反，指速度变慢，二者构成反义关系。"}, {"text": "保持", "is_correct": false, "explanation": "语义：保持指维持原样，与速度的变化无关，不是“加快”的反义词。"}, {"text": "整理", "is_correct": false, "explanation": "语义：整理指使事物有条理，不表示速度的变化。"}, {"text": "观察", "is_correct": false, "explanation": "语义：观察指仔细看，与速度无关，不构成反义关系。"}], "correct_answer": "放慢", "explanations": {"放慢": "正确：放慢与加快意义相反，指速度变慢，二者构成反义关系。", "保持": "语义：保持指维持原样，与速度的变化无关，不是“加快”的反义词。", "整理": "语义：整理指使事物有条理，不表示速度的变化。", "观察": "语义：观察指仔细看，与速度无关，不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24128, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放慢", "is_correct": true, "explanation": "正确：放慢与加快意义相反，指速度变慢，二者构成反义关系。"}, {"text": "收集", "is_correct": false, "explanation": "语义：收集指把分散的东西聚在一起，与速度无关。"}, {"text": "参观", "is_correct": false, "explanation": "语义：参观指到某地去看，与速度的变化无关。"}, {"text": "储存", "is_correct": false, "explanation": "语义：储存指保存物品，与速度无关，不构成反义关系。"}], "correct_answer": "放慢", "explanations": {"放慢": "正确：放慢与加快意义相反，指速度变慢，二者构成反义关系。", "收集": "语义：收集指把分散的东西聚在一起，与速度无关。", "参观": "语义：参观指到某地去看，与速度的变化无关。", "储存": "语义：储存指保存物品，与速度无关，不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24128, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让事情做得更快。", "primary_collocate": null, "pronunciation": "jiā kuài", "ipa": "tɕia˥ kʰuaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "路上人少，司机加快了速度。", "target_word": "加快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要加快脚步，不然会迟到。", "target_word": "加快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请大家加快写作业的速度。", "target_word": "加快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛快结束了，他开始加快速度。", "target_word": "加快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想加快新产品的开发。", "target_word": "加快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你加快一点儿，我们快要迟到了。", "target_word": "加快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，大家都加快了回家的脚步。", "target_word": "加快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们加快工作进度，想早点完成。", "target_word": "加快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市正在加快地铁的建设。", "target_word": "加快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把说话的速度加快了，我听不清。", "target_word": "加快", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加快了", "label": "体标"}, {"form": "加快过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使速度或进度变快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22aa5821-43c2-4f1a-bd68-eccc7ce09b8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讨论", "is_correct": false, "explanation": "语义：讨论需要多人交流，与“司机一人开车”的情境不符。"}, {"text": "加快", "is_correct": true, "explanation": "正确：加快表示使速度变快，与“路上人少”的语境相符。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫指清除垃圾、保持清洁，与“速度”无关，句子说不通。"}, {"text": "装修", "is_correct": false, "explanation": "语义：装修是改造房屋的动作，与“速度”无关，句子说不通。"}], "explanations": {"讨论": "语义：讨论需要多人交流，与“司机一人开车”的情境不符。", "加快": "正确：加快表示使速度变快，与“路上人少”的语境相符。", "打扫": "语义：打扫指清除垃圾、保持清洁，与“速度”无关，句子说不通。", "装修": "语义：装修是改造房屋的动作，与“速度”无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "加快"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试他的成绩加快了很多。", "explanation": "这里应该用〈提高〉。加快只用于速度、进度，成绩的进步要用“提高”。"}, {"text": "这个月的工资加快了五百块。", "explanation": "这里应该用〈增加〉。加快只用于速度、进度，工资数额的增加要用“增加”。"}, {"text": "他把价格加快了两块钱。", "explanation": "这里应该用〈提高〉。加快只用于速度、进度，价格的上涨要用“提高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏指欣赏美好的事物，“欣赏回家的脚步”说不通。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：搬运的宾语是货物，不能说“搬运脚步”。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：驾驶的宾语须是车辆，不能用于“脚步”。"}, {"text": "加快", "is_correct": true, "explanation": "正确：加快表示使速度变快，与“下雨了”急着回家的语境相符。"}], "explanations": {"欣赏": "语义：欣赏指欣赏美好的事物，“欣赏回家的脚步”说不通。", "搬运": "搭配：搬运的宾语是货物，不能说“搬运脚步”。", "驾驶": "配价：驾驶的宾语须是车辆，不能用于“脚步”。", "加快": "正确：加快表示使速度变快，与“下雨了”急着回家的语境相符。"}, "sentence_index": 6, "correct_answer": "加快"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "航班加快了两个小时，大家都很意外。", "explanation": "这里应该用〈延迟〉。加快描述速度，航班时间的推后要用“延迟”。"}, {"text": "他把每天的睡眠加快了两小时。", "explanation": "这里应该用〈减少〉。加快只指速度，睡眠时长的缩短要用“减少”。"}, {"text": "这所学校加快了两个班级。", "explanation": "这里应该用〈增设〉。加快只用于速度、进度，增加班级要用“增设”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他加快地步伐，赶上了火车。", "corrected_sentence": "他加快了步伐，赶上了火车。", "error_description": "助词错误：“加快”后面接宾语“步伐”时，应在动词后用“了”，说“加快了步伐”。“地”只用于修饰动词的状语，不能放在名词“步伐”前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把跑步的速度加快了点一。", "corrected_sentence": "她把跑步的速度加快了一点。", "error_description": "数量词语序错误：“加快了”后面的数量补语应为“一点”，数词要在量词前，不能说“点一”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
