INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24130, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24130, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一定会发生，不会改变。", "primary_collocate": null, "pronunciation": "bì rán", "ipa": "pi˥˩ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "天黑以后，气温必然会下降。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天过去了，春天必然会到来。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总是迟到，老板必然会生气。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格太高，买的人必然很少。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水加热到一百度，必然会变成水蒸气。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不复习功课，考试时必然会遇到困难。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年纪大了，头发必然会变白。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多练习说汉语，进步必然很快。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不迟到，今天必然也会准时到。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天天吃甜食，牙齿必然会出问题。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "必然性", "label": "复合"}], "register": "中性", "sense_fingerprint": "按照事理一定会发生，结果不会改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43abfa4c-343c-4bb7-89da-1317173c8205') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必然", "is_correct": true, "explanation": "「必然」表示必定会发生，符合天黑以后气温下降的常理。"}, {"text": "绝不", "is_correct": false, "explanation": "语义：「绝不」表示否定，与「天黑以后」气温下降的常理相矛盾。"}, {"text": "断然", "is_correct": false, "explanation": "搭配：「断然」用于决断语境，不修饰气温的自然变化。"}, {"text": "从不", "is_correct": false, "explanation": "语义：「从不」表示从来没有，与「必然会下降」的结论相矛盾。"}], "explanations": {"必然": "「必然」表示必定会发生，符合天黑以后气温下降的常理。", "绝不": "语义：「绝不」表示否定，与「天黑以后」气温下降的常理相矛盾。", "断然": "搭配：「断然」用于决断语境，不修饰气温的自然变化。", "从不": "语义：「从不」表示从来没有，与「必然会下降」的结论相矛盾。"}, "sentence_index": 0, "correct_answer": "必然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你必然在八点前到校。", "explanation": "这里应该用〈必须〉。「必然」说客观规律的必定，不表示对人的要求或命令。"}, {"text": "他或许必然会来，你再等等吧。", "explanation": "这里应该用〈会〉。「必然」表示确定，与「或许」的不确定语气冲突。"}, {"text": "我昨天在超市必然碰到了老师。", "explanation": "这里应该用〈偶然〉。「必然」指必定会发生，偶然碰到是意外，不能说「必然碰到」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "必然", "is_correct": true, "explanation": "「必然」表示必定如此，符合年纪增长后头发变白的自然结果。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示不常发生，与「年纪大了」带来的必然变化相矛盾。"}, {"text": "顺便", "is_correct": false, "explanation": "搭配：「顺便」表示附带做事，不能修饰头发变白这种自然变化。"}, {"text": "不妨", "is_correct": false, "explanation": "搭配：「不妨」用于提出建议，不能用来描述头发的自然变化。"}], "explanations": {"必然": "「必然」表示必定如此，符合年纪增长后头发变白的自然结果。", "偶尔": "语义：「偶尔」表示不常发生，与「年纪大了」带来的必然变化相矛盾。", "顺便": "搭配：「顺便」表示附带做事，不能修饰头发变白这种自然变化。", "不妨": "搭配：「不妨」用于提出建议，不能用来描述头发的自然变化。"}, "sentence_index": 6, "correct_answer": "必然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "希望你必然能通过考试。", "explanation": "这里应该用〈一定〉。「必然」说事理上的必定，不用于对他人的希望或祝愿。"}, {"text": "我必然喜欢这个颜色。", "explanation": "这里应该用〈肯定〉。「必然」说客观规律的必然，不用于表达个人喜好。"}, {"text": "这个消息必然是真的，但我们还不能确定。", "explanation": "这里应该用〈可能〉。「必然」表示确定，与「还不能确定」的语境相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "坚持服药，病情很必然会好转。", "corrected_sentence": "坚持服药，病情必然会好转。", "error_description": "「必然」是副词，不能受「很」修饰，应去掉「很」，写作「病情必然会好转」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "长期加班，睡眠质量会必然下降。", "corrected_sentence": "长期加班，睡眠质量必然下降。", "error_description": "「会」不能放在副词「必然」之前，应写作「睡眠质量必然下降」（或「必然会下降」，此时「会」在「必然」之后），不能写成「会必然下降」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
